    '137cfed2-0d62-4813-aff3-3efdcd637501', 'LS6_KNTT_B17', 'ab344111-fd0e-4e3c-b4f8-60c56c9e9331', '6', 'KNTT', 'LS', 
    17, 'CUỘC ĐẤU TRANH BẢO TỒN VÀ PHÁT TRIỂN VĂN HOÁ DÂN TỘC CỦA NGƯỜI VIỆT', 
