) VALUES (
    'Q_LS6_B02_10', '9d6d7489-cc1d-4916-a93f-0055ad5c0a4c', 'LS6_KNTT_B02', 'Hạn chế cần lưu ý khi sử dụng tư liệu chữ viết',
    'chỉ phản ánh đời sống vật chất nên không có thông tin về con người', 'thường không còn nguyên vẹn nên hoàn toàn không thể khai thác', 'có thể chịu ảnh hưởng bởi quan điểm và thế giới quan của người viết', 'không thể cung cấp chi tiết về sự kiện dù văn bản còn đầy đủ',
    3, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là C: có thể chịu ảnh hưởng bởi quan điểm và thế giới quan của người viết'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
