    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS6_B05_05', '22ef9f91-17be-4b62-a4c1-7474ad62e080', 'LS6_KNTT_B05', 'Công cụ đá tiêu biểu của bầy người nguyên thủy được SGK mô tả',
    'rìu đá ghè đẽo thô sơ dùng để đào củ và chặt cành', 'rìu đá mài nhẵn toàn thân dùng chủ yếu trong nông nghiệp', 'lưỡi cày kim loại sắc bén dùng để mở rộng ruộng canh tác', 'dao sắt có cán chắc dùng để khai phá những vùng rừng lớn',
    1, 20, 'WARM_UP', 'EASY', 'Đáp án đúng là A: rìu đá ghè đẽo thô sơ dùng để đào củ và chặt cành'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS6_B05_06', '22ef9f91-17be-4b62-a4c1-7474ad62e080', 'LS6_KNTT_B05', 'Phát minh giúp người nguyên thủy nâng cao hiệu quả săn bắt',
    'thuyền buồm', 'cung tên', 'xe kéo', 'bánh xe',
    2, 20, 'WARM_UP', 'EASY', 'Đáp án đúng là B: cung tên'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS6_B05_07', '22ef9f91-17be-4b62-a4c1-7474ad62e080', 'LS6_KNTT_B05', 'Nhóm vật liệu được người nguyên thủy sử dụng làm đồ trang sức ở giai đoạn sớm',
    'vàng, bạc và đá quý đã được gia công tinh xảo', 'đồng, sắt và thiếc đã được luyện thành những vòng nhỏ', 'vỏ ốc, xương hoặc răng thú được đục lỗ để xỏ dây', 'thủy tinh, gốm men và kim loại được ghép thành chuỗi',
    3, 20, 'WARM_UP', 'EASY', 'Đáp án đúng là C: vỏ ốc, xương hoặc răng thú được đục lỗ để xỏ dây'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS6_B05_08', '22ef9f91-17be-4b62-a4c1-7474ad62e080', 'LS6_KNTT_B05', 'Hoạt động sản xuất thể hiện bước tiến của công xã thị tộc',
    'chỉ dựa vào hái lượm các sản vật có sẵn trong tự nhiên', 'chỉ dựa vào săn bắt thú rừng bằng công cụ đá ghè đẽo', 'chủ yếu trao đổi hàng hóa giữa các thị tộc bằng tiền kim loại', 'trồng rau, trồng lúa và chăn nuôi một số loài gia súc',
    4, 20, 'WARM_UP', 'EASY', 'Đáp án đúng là D: trồng rau, trồng lúa và chăn nuôi một số loài gia súc'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS6_B05_09', '22ef9f91-17be-4b62-a4c1-7474ad62e080', 'LS6_KNTT_B05', 'Nghề thủ công được người nguyên thủy phát triển trong công xã thị tộc',
    'làm đồ gốm và dệt vải từ sợi vỏ cây', 'đúc công cụ sắt và rèn vũ khí bằng thép', 'in sách trên giấy và khắc chữ trên bản gỗ', 'đóng tàu lớn và chế tạo dụng cụ hàng hải',
    1, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là A: làm đồ gốm và dệt vải từ sợi vỏ cây'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS6_B05_10', '22ef9f91-17be-4b62-a4c1-7474ad62e080', 'LS6_KNTT_B05', 'Biểu hiện cho thấy đời sống tinh thần của người nguyên thủy đã phát triển hơn',
    'tích trữ nhiều lương thực để trao đổi giữa các cộng đồng', 'chôn người chết và thực hành những hình thức thờ thần linh', 'xây thành lũy và tổ chức quân đội để bảo vệ nơi cư trú', 'đúc tiền kim loại và hình thành những trung tâm buôn bán',
    2, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là B: chôn người chết và thực hành những hình thức thờ thần linh'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS6_B05_11', '22ef9f91-17be-4b62-a4c1-7474ad62e080', 'LS6_KNTT_B05', 'Dấu tích tại các di chỉ Hòa Bình, Bắc Sơn cho thấy cư dân Việt Nam đã',
    'sống hoàn toàn bằng săn bắt và chưa biết chế tác đồ gốm', 'sử dụng phổ biến công cụ kim loại trong sản xuất nông nghiệp', 'bước đầu biết làm nông nghiệp và chăn nuôi một số gia súc', 'xây dựng nhà nước và phân chia xã hội thành nhiều giai cấp',
    3, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là C: bước đầu biết làm nông nghiệp và chăn nuôi một số gia súc'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS6_B05_12', '22ef9f91-17be-4b62-a4c1-7474ad62e080', 'LS6_KNTT_B05', 'Nhóm địa điểm ở Việt Nam có công cụ đá ghè đẽo thô sơ thuộc giai đoạn sớm',
    'Hòa Bình, Bắc Sơn và Quỳnh Văn', 'Bắc Sơn, Quỳnh Văn và Đồng Nội', 'Quỳnh Văn, Đồng Nội và Hòa Bình', 'Núi Đọ, Sơn Vi và Xuân Lộc',
    4, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là D: Núi Đọ, Sơn Vi và Xuân Lộc'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS6_B05_13', '22ef9f91-17be-4b62-a4c1-7474ad62e080', 'LS6_KNTT_B05', 'Sự xuất hiện của Người tinh khôn làm bầy người nguyên thủy dần nhường chỗ cho công xã thị tộc chủ yếu vì',
    'quan hệ họ hàng giúp hình thành tổ chức xã hội chặt chẽ hơn', 'của cải tư nhân tăng khiến các gia đình sống riêng biệt', 'nhà nước xuất hiện và chia cư dân thành các đơn vị hành chính', 'buôn bán bằng tiền phát triển nên hình thành các đô thị',
    1, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là A: quan hệ họ hàng và đời sống cộng đồng tạo điều kiện hình thành tổ chức xã hội chặt chẽ hơn'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS6_B05_14', '22ef9f91-17be-4b62-a4c1-7474ad62e080', 'LS6_KNTT_B05', 'Đặc điểm bình đẳng, cùng làm chung và hưởng chung của công xã thị tộc phản ánh',
    'sự phân chia xã hội thành các tầng lớp có quyền lợi đối lập nhau', 'quan hệ cộng đồng gắn bó và sự hợp tác trong lao động, sinh hoạt', 'sự xuất hiện của thị trường trao đổi và quyền sở hữu tư nhân phổ biến', 'sự hình thành bộ máy nhà nước để điều hành mọi hoạt động của cộng đồng',
    2, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là B: quan hệ cộng đồng gắn bó và sự hợp tác trong lao động, sinh hoạt'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS6_B05_15', '22ef9f91-17be-4b62-a4c1-7474ad62e080', 'LS6_KNTT_B05', 'So với Người tối cổ, đời sống vật chất của Người tinh khôn tiến bộ rõ ở việc',
    'tiếp tục chỉ dùng công cụ đá ghè đẽo và dựa hoàn toàn vào hái lượm', 'ngừng chế tạo công cụ để tận dụng hoàn toàn những vật có sẵn trong tự nhiên', 'biết mài đá, làm gốm, dệt vải, trồng trọt và chăn nuôi', 'sử dụng rộng rãi kim loại, tiền tệ và phương tiện vận tải đường dài',
    3, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là C: biết mài đá, làm gốm, dệt vải, trồng trọt và chăn nuôi'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS6_B05_16', '22ef9f91-17be-4b62-a4c1-7474ad62e080', 'LS6_KNTT_B05', 'Việc tạo ra lửa và phát minh cung tên cho thấy lao động đã',
    'làm con người lệ thuộc hơn vào những nguồn thức ăn có sẵn', 'khiến các nhóm người giảm hợp tác và chuyển sang sinh sống riêng lẻ', 'làm cho hoạt động kiếm sống chỉ còn dựa vào săn bắt thú rừng', 'giúp cải tiến cách kiếm sống và tăng khả năng chế ngự tự nhiên',
    4, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là D: giúp con người cải tiến phương tiện kiếm sống và tăng khả năng chế ngự tự nhiên'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS6_B05_17', '22ef9f91-17be-4b62-a4c1-7474ad62e080', 'LS6_KNTT_B05', 'Đồ trang sức và tranh vẽ trên vách hang của người nguyên thủy phản ánh',
    'con người đã có nhu cầu thẩm mĩ và đời sống tinh thần bước đầu phát triển', 'con người đã hình thành quân đội chuyên nghiệp và những nghi lễ nhà nước', 'các cộng đồng đã sử dụng chữ viết để ghi chép đầy đủ đời sống hằng ngày', 'sản xuất đã chuyển hẳn từ săn bắt sang luyện kim, buôn bán',
    1, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là A: con người đã có nhu cầu thẩm mĩ và đời sống tinh thần bước đầu phát triển'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS6_B05_18', '22ef9f91-17be-4b62-a4c1-7474ad62e080', 'LS6_KNTT_B05', 'Tục chôn người chết và thờ thần linh ở công xã thị tộc cho thấy',
    'con người đã sáng tạo ra hệ thống chữ viết để truyền lại tín ngưỡng', 'đời sống tinh thần phong phú hơn và xuất hiện những quan niệm tín ngưỡng', 'xã hội đã phân hóa sâu sắc và hình thành những giai cấp đối kháng', 'mọi cộng đồng đều theo một tôn giáo thống nhất có tổ chức chặt chẽ',
    2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: đời sống tinh thần phong phú hơn và xuất hiện những quan niệm tín ngưỡng'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS6_B05_19', '22ef9f91-17be-4b62-a4c1-7474ad62e080', 'LS6_KNTT_B05', 'Tìm thấy đá mài, gốm, xương thú, hạt cây ở Hòa Bình, Bắc Sơn cho thấy',
    'cư dân chỉ sống bằng săn bắt thú rừng và chưa biết chế biến thức ăn', 'cư dân dùng phổ biến kim loại và sản xuất thủ công quy mô lớn', 'cư dân kết hợp nhiều hoạt động kiếm sống và bước đầu biết làm nông nghiệp', 'cư dân đã xây dựng các đô thị và tổ chức xã hội thành những nhà nước cổ đại',
    3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: cư dân kết hợp nhiều hoạt động kiếm sống và bước đầu biết làm nông nghiệp'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS6_B05_20', '22ef9f91-17be-4b62-a4c1-7474ad62e080', 'LS6_KNTT_B05', 'Ý nghĩa khái quát của lao động đối với quá trình phát triển xã hội nguyên thủy',
    'chỉ đổi hình dáng công cụ, không ảnh hưởng con người và cộng đồng', 'chỉ tăng thức ăn nhưng không đổi cách thức tổ chức xã hội', 'chủ yếu tạo của cải riêng, thúc đẩy cá nhân rời cộng đồng', 'hoàn thiện con người, gắn kết cộng đồng, đổi mới công cụ, nâng đời sống',
    4, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là D: góp phần hoàn thiện con người, gắn kết cộng đồng, đổi mới công cụ và nâng cao đời sống'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS6_B05_21', '22ef9f91-17be-4b62-a4c1-7474ad62e080', 'LS6_KNTT_B05', 'Một di chỉ mới phát hiện có rìu đá mài, đồ gốm, xương gia súc và nhiều hạt cây ăn được. Nhận định phù hợp nhất',
    'cư dân tiến bộ hơn, bước đầu phát triển trồng trọt và chăn nuôi', 'cư dân vẫn chỉ dựa vào hái lượm, chưa có hoạt động sản xuất thức ăn', 'cư dân đã bước vào thời đại kim loại và hình thành nhà nước có giai cấp', 'cư dân chủ yếu sống bằng thương mại và trao đổi sản phẩm giữa các đô thị',
    1, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là A: cư dân đã ở giai đoạn tiến bộ hơn, bước đầu phát triển trồng trọt và chăn nuôi'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS6_B05_22', '22ef9f91-17be-4b62-a4c1-7474ad62e080', 'LS6_KNTT_B05', 'Chuỗi biến đổi từ công cụ đá ghè đẽo đến đá mài, đồ gốm rồi trồng trọt, chăn nuôi cho phép rút ra kết luận',
    'công cụ thay đổi nhưng đời sống, xã hội hầu như không chuyển biến', 'tiến bộ công cụ và sản xuất gắn với quá trình phát triển xã hội', 'nông nghiệp xuất hiện trước khi con người cải tiến công cụ lao động', 'đời sống tinh thần quyết định hoàn toàn sự thay đổi kĩ thuật, sản xuất',
    2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: tiến bộ của công cụ và phương thức sản xuất gắn với quá trình phát triển của xã hội'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS6_B05_23', '22ef9f91-17be-4b62-a4c1-7474ad62e080', 'LS6_KNTT_B05', 'Chế tác công cụ đá cần lặp lại thao tác và phối hợp. Liên hệ đúng về vai trò lao động:',
    'chỉ tăng sản phẩm nhưng không ảnh hưởng đến kĩ năng con người', 'làm cá nhân ngày càng tách biệt, không giúp hình thành cộng đồng', 'vừa rèn luyện kĩ năng, vừa thúc đẩy hợp tác và sáng tạo cộng đồng', 'chỉ có ý nghĩa khi đã biết dùng kim loại và có tổ chức nhà nước',
    3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: lao động vừa rèn luyện kĩ năng cơ thể vừa thúc đẩy hợp tác, sáng tạo trong cộng đồng'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS6_B05_24', '22ef9f91-17be-4b62-a4c1-7474ad62e080', 'LS6_KNTT_B05', 'Khi nghiên cứu một địa điểm có công cụ đá, đồ trang sức, tranh vẽ và mộ táng, cách khai thác tư liệu phù hợp nhất',
    'chỉ dựa vào công cụ đá để kết luận toàn bộ đời sống của cư dân tại địa điểm', 'chỉ dựa vào tranh vẽ để xác định mọi hoạt động sản xuất của cư dân', 'chỉ dựa vào mộ táng để xác định đầy đủ cơ cấu tổ chức xã hội của cộng đồng', 'đối chiếu nhiều di vật để nhận xét cả đời sống vật chất và tinh thần',
    4, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là D: đối chiếu nhiều loại di vật để nhận xét đồng thời đời sống vật chất và tinh thần'
