    'Q_LS6_B11_13', 'b2070266-20a5-4291-9929-e7ca2caddcc2', 'LS6_KNTT_B11', 'Đông Nam Á được coi là "ngã tư đường" của thế giới cổ đại chủ yếu do',
    'nằm biệt lập giữa nhiều dãy núi, ít tiếp xúc với bên ngoài', 'có hoang mạc rộng lớn nối liền các tuyến đường bộ xuyên lục địa', 'nằm trên tuyến hàng hải nối hai đại dương và nhiều trung tâm văn minh', 'ở sát Bắc Băng Dương nên thuận lợi tiếp xúc với các vùng phương bắc',
    3, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là C: nằm trên tuyến hàng hải nối hai đại dương và nhiều trung tâm văn minh'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
