INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS7_B05_13', '6c9fd6ff-970f-45fb-83cc-24480c11eb1a', 'LS7_KNTT_B05', 'Nguyên nhân chủ yếu khiến thời Gúp-ta được xem là thời hoàng kim của Ấn Độ',
    'đất nước ngừng giao thương với bên ngoài và chỉ dựa vào tự cấp, tự túc', 'các cuộc xâm lược liên tục mở rộng làm đời sống dân cư ngày càng khó khăn', 'nhà nước xoá bỏ hoàn toàn mọi khác biệt xã hội và tôn giáo trong cả nước', 'kinh tế tiến bộ rõ rệt, đất nước ổn định và đời sống người dân sung túc hơn',
    4, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là D: kinh tế tiến bộ rõ rệt, đất nước ổn định và đời sống người dân sung túc hơn'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS7_B05_14', '6c9fd6ff-970f-45fb-83cc-24480c11eb1a', 'LS7_KNTT_B05', 'Nguyên nhân làm mâu thuẫn dân tộc dưới thời Đê-li vẫn gay gắt dù kinh tế tiếp tục phát triển',
    'nhà nước cấm toàn bộ hoạt động thương mại với các khu vực bên ngoài', 'sự phân biệt sắc tộc và tôn giáo vẫn tồn tại trong chính sách cai trị', 'nông nghiệp bị xoá bỏ để chuyển hẳn sang thủ công nghiệp, thương mại', 'các tín đồ Hin-đu nắm toàn bộ chức vụ quan trọng trong bộ máy chính quyền',
    2, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là B: sự phân biệt sắc tộc và tôn giáo vẫn tồn tại trong chính sách cai trị'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS7_B05_15', '6c9fd6ff-970f-45fb-83cc-24480c11eb1a', 'LS7_KNTT_B05', 'Điểm nổi bật trong chính sách của A-co-ba giúp xã hội Mô-gôn ổn định hơn thời Đê-li',
    'hạn chế phân biệt sắc tộc, tôn giáo và xây dựng khối hoà hợp dân tộc', 'trao mọi chức vụ quan trọng cho một nhóm tôn giáo duy nhất trong triều đình', 'chia đất nước thành các lãnh địa độc lập, giảm quyền lực trung ương', 'đóng cửa các thành phố hải cảng và hạn chế sự giao lưu giữa các vùng',
    1, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là A: hạn chế phân biệt sắc tộc, tôn giáo và xây dựng khối hoà hợp dân tộc'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS7_B05_16', '6c9fd6ff-970f-45fb-83cc-24480c11eb1a', 'LS7_KNTT_B05', 'Tác dụng trực tiếp của việc đo đạc lại ruộng đất, định mức thuế hợp lí và thống nhất đo lường dưới thời A-co-ba',
    'làm hoạt động nông nghiệp phụ thuộc nhiều hơn vào từng lãnh địa riêng biệt', 'thu hẹp buôn bán do mỗi nơi dùng một hệ thống đo lường khác nhau', 'giúp quản lí kinh tế thống nhất hơn, giảm bớt gánh nặng bất hợp lí', 'xoá bỏ mọi mâu thuẫn xã hội, chấm dứt hoàn toàn sự bóc lột của quý tộc',
    3, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là C: tạo điều kiện quản lí kinh tế thống nhất hơn và giảm bớt gánh nặng bất hợp lí'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS7_B05_17', '6c9fd6ff-970f-45fb-83cc-24480c11eb1a', 'LS7_KNTT_B05', 'Nhận xét phù hợp về tác động của điều kiện tự nhiên đối với Ấn Độ thời phong kiến',
    'địa hình bằng phẳng nên các vùng phát triển kinh tế theo cùng mô hình', 'Hi-ma-lay-a chắn phía bắc; đồng bằng, cao nguyên giúp phát triển đa dạng', 'Ấn Độ bị cô lập tuyệt đối, gần như không buôn bán với bên ngoài', 'khí hậu đồng nhất nên hoạt động sản xuất không khác biệt giữa các vùng',
    2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: Hi-ma-lay-a tạo rào chắn phía bắc, còn đồng bằng và cao nguyên tạo điều kiện phát triển đa dạng'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS7_B05_18', '6c9fd6ff-970f-45fb-83cc-24480c11eb1a', 'LS7_KNTT_B05', 'Nét thể hiện rõ tính thống nhất trong đa dạng của văn hoá Ấn Độ từ thế kỉ IV đến giữa thế kỉ XIX',
    'chỉ một tôn giáo được duy trì, còn các tôn giáo khác hoàn toàn biến mất', 'các thành tựu văn hoá chủ yếu sao chép từ ngoài, không có nét riêng', 'chữ viết và văn học không có sự tiếp nối qua các giai đoạn lịch sử', 'nhiều tôn giáo, văn hoá cùng tồn tại nhưng bản sắc Ấn Độ vẫn duy trì',
    4, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là D: nhiều tôn giáo và yếu tố văn hoá cùng tồn tại nhưng bản sắc Ấn Độ vẫn được duy trì'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS7_B05_19', '6c9fd6ff-970f-45fb-83cc-24480c11eb1a', 'LS7_KNTT_B05', 'Ý nghĩa nổi bật của chữ Phạn đối với văn hoá Ấn Độ',
    'chỉ dùng trong hoạt động buôn bán ở các thành phố hải cảng', 'thay thế hoàn toàn mọi ngôn ngữ nói của cư dân trên toàn bán đảo', 'dùng sáng tác văn học và là nguồn gốc của chữ Hin-đi ngày nay', 'được du nhập từ Tây Á và chỉ phát triển dưới thời Vương triều Đê-li',
    3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: là ngôn ngữ - văn tự sáng tác văn học và là nguồn gốc của chữ Hin-đi ngày nay'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS7_B05_20', '6c9fd6ff-970f-45fb-83cc-24480c11eb1a', 'LS7_KNTT_B05', 'Đặc điểm nổi bật của kiến trúc Ấn Độ thời phong kiến',
    'chịu ảnh hưởng sâu sắc của Phật giáo, Hin-đu giáo và Hồi giáo', 'chỉ phát triển trong cung điện và không gắn với đời sống tôn giáo', 'hoàn toàn tách biệt khỏi điêu khắc và các hình thức nghệ thuật khác', 'chủ yếu mô phỏng kiến trúc châu Âu và ít thể hiện bản sắc bản địa',
    1, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là A: chịu ảnh hưởng sâu sắc của Phật giáo, Hin-đu giáo và Hồi giáo'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS7_B05_21', '6c9fd6ff-970f-45fb-83cc-24480c11eb1a', 'LS7_KNTT_B05', 'Các mốc năm 320 - 1206 - đầu thế kỉ XVI - giữa thế kỉ XIX gắn với Gúp-ta, Đê-li, Mô-gôn cho thấy',
    'Ấn Độ chỉ có một vương triều duy nhất tồn tại liên tục suốt thời phong kiến', 'mọi lần đổi triều đại đều làm kinh tế, văn hoá Ấn Độ ngừng phát triển', 'chính trị nhiều lần đổi thay nhưng lịch sử Ấn Độ vẫn có sự tiếp nối', 'các vương triều lập cùng lúc và có chính sách cai trị giống hệt nhau',
    3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: quyền lực chính trị nhiều lần thay đổi nhưng lịch sử Ấn Độ vẫn có sự tiếp nối qua các triều đại'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS7_B05_22', '6c9fd6ff-970f-45fb-83cc-24480c11eb1a', 'LS7_KNTT_B05', 'Từ quan hệ buôn bán đường biển thời Gúp-ta và hoạt động của các hải cảng thời Đê-li, Mô-gôn có thể rút ra',
    'Ấn Độ chỉ trao đổi nội địa, không tham gia thương mại khu vực', 'Ấn Độ nằm trong mạng lưới nối Nam Á với Đông Nam Á, Tây Á, phương Tây', 'thương mại chỉ phát triển khi nông nghiệp và các thành thị suy thoái', 'hoạt động buôn bán Ấn Độ phụ thuộc hoàn toàn vào một nước bên ngoài',
    2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: Ấn Độ có vị trí trong mạng lưới giao thương nối Nam Á với Đông Nam Á, Tây Á và phương Tây'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS7_B05_23', '6c9fd6ff-970f-45fb-83cc-24480c11eb1a', 'LS7_KNTT_B05', 'Đặt chùa hang A-gian-ta, đền Kha-giu-ra-hô và các công trình Hồi giáo cạnh nhau, nhận xét phù hợp',
    'cho thấy kiến trúc Ấn Độ chỉ phát triển trong một tôn giáo duy nhất', 'các công trình xây cùng thời gian và có phong cách hoàn toàn giống nhau', 'chứng tỏ văn hoá bản địa đã bị xoá bỏ hoàn toàn bởi yếu tố bên ngoài', 'kiến trúc, điêu khắc đa dạng, chịu ảnh hưởng từ nhiều tôn giáo',
    4, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là D: kiến trúc, điêu khắc Ấn Độ phong phú và phản ánh ảnh hưởng của nhiều truyền thống tôn giáo'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS7_B05_24', '6c9fd6ff-970f-45fb-83cc-24480c11eb1a', 'LS7_KNTT_B05', 'Tiếp thu nhiều yếu tố nhưng giữ bản sắc và lan toả ra Đông Nam Á cho thấy văn hoá Ấn Độ:',
    'có sức sống bền bỉ, khả năng dung hợp và sức lan toả rộng lớn', 'chỉ có giá trị trong bán đảo và hầu như không ảnh hưởng ra bên ngoài', 'tiếp nhận yếu tố mới làm thành tựu truyền thống bị thay thế hoàn toàn', 'tôn giáo đa dạng khiến văn hoá không hình thành đặc trưng chung',
    1, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là A: văn hoá Ấn Độ có sức sống bền bỉ, khả năng dung hợp và sức lan toả rộng trong khu vực'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS7_B05_TF01', '6c9fd6ff-970f-45fb-83cc-24480c11eb1a', 'LS7_KNTT_B05', 'Tư liệu phản ánh đời sống Ấn Độ vào thế kỉ V dưới thời Vương triều Gúp-ta',
    'Đúng', 'Sai', NULL, NULL,
    1, 20, 'WARM_UP', 'EASY', 'Nhận định này là ĐÚNG.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
