) VALUES (
    'Q_LS7_B06_18', 'd80abc75-a3a2-44c0-9601-a6803b71c9e4', 'LS7_KNTT_B06', 'Nhận xét phù hợp về văn hoá Đông Nam Á từ nửa sau thế kỉ X đến nửa đầu thế kỉ XVI',
    'chỉ sao chép nguyên vẹn văn hoá Ấn Độ và Trung Quốc', 'tiếp thu có chọn lọc ảnh hưởng bên ngoài và phát huy sự sáng tạo bản địa', 'phát triển tách biệt hoàn toàn với giao lưu khu vực và quốc tế', 'chỉ có thành tựu tôn giáo, không xuất hiện văn học và kiến trúc',
    2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: tiếp thu có chọn lọc ảnh hưởng bên ngoài và phát huy sự sáng tạo bản địa'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS7_B06_19', 'd80abc75-a3a2-44c0-9601-a6803b71c9e4', 'LS7_KNTT_B06', 'Mối quan hệ giữa nông nghiệp lúa nước và buôn bán đường biển đối với sự thịnh đạt của các vương quốc',
    'hai hoạt động cạnh tranh nhau nên làm suy yếu kinh tế của các vương quốc', 'thương mại phát triển khiến nông nghiệp lúa nước không còn vai trò đáng kể', 'nông nghiệp chỉ phục vụ tín ngưỡng còn thương mại chỉ phục vụ triều đình', 'nông nghiệp tạo nền tảng sản xuất, thương mại giúp mở rộng trao đổi',
    4, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là D: nông nghiệp tạo nền tảng sản xuất, còn thương mại mở rộng trao đổi và làm kinh tế thêm phong phú'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS7_B06_20', 'd80abc75-a3a2-44c0-9601-a6803b71c9e4', 'LS7_KNTT_B06', 'Sự xuất hiện nhiều tác phẩm văn học viết ở In-đô-nê-xi-a và Ma-lai-xi-a phản ánh',
    'đời sống văn hoá phát triển, ghi lại sự thịnh đạt của vương quốc', 'văn học dân gian hoàn toàn biến mất khi chữ viết được sử dụng', 'mọi tác phẩm trong khu vực đều dùng chung một ngôn ngữ và chữ viết', 'văn học chỉ phục vụ thương nhân nước ngoài, không gắn với đời sống bản địa',
    1, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là A: đời sống văn hoá phát triển và có khả năng ghi lại sự hưng thịnh của các vương quốc'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
