) VALUES (
    'Q_LS7_B06_21', 'd80abc75-a3a2-44c0-9601-a6803b71c9e4', 'LS7_KNTT_B06', 'Từ lược đồ các vương quốc phong kiến Đông Nam Á, nhận xét phù hợp về quá trình phát triển chính trị của khu vực',
    'chỉ quốc gia lục địa phát triển, vùng hải đảo không có vương quốc', 'vương quốc ở cả lục địa và hải đảo, có kế thừa và thống nhất lãnh thổ', 'toàn bộ khu vực được thống nhất thành một vương quốc duy nhất từ thế kỉ X', 'ranh giới xưa hoàn toàn trùng khớp với biên giới quốc gia hiện nay',
    2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: nhiều vương quốc phân bố cả lục địa và hải đảo, có sự kế thừa, hình thành mới và thống nhất lãnh thổ'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
