    'Q_LS7_B07_17', '50815b3c-7426-4a38-b103-3548cbed2845', 'LS7_KNTT_B07', 'Chính sách đối ngoại của Lan Xang trong các thế kỉ XV - XVII thể hiện',
    'chỉ ưu tiên chiến tranh để mở rộng lãnh thổ sang các quốc gia láng giềng', 'duy trì hoà hiếu khi có thể nhưng kiên quyết bảo vệ độc lập trước xâm lược', 'đóng cửa với mọi nước để tránh tác động từ các cuộc xung đột trong khu vực', 'phụ thuộc vào các nước láng giềng và từ bỏ quyền tự quyết về đối ngoại',
    2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: duy trì hoà hiếu khi có thể nhưng kiên quyết bảo vệ độc lập trước xâm lược'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
