) VALUES (
    'Q_LS7_B10_16', '9b755e9a-7f9b-44a3-83f6-e738fbcf101a', 'LS7_KNTT_B10', 'Địa thế Hoa Lư thuận lợi cho việc đặt kinh đô buổi đầu độc lập chủ yếu vì',
    'nằm giữa đồng bằng rộng lớn, thuận tiện phát triển các đô thị ven biển', 'ở sát biên giới phía bắc, dễ quan sát trực tiếp hoạt động của nhà Tống', 'có nhiều cảng biển lớn, thuận lợi giao thương với các nước trong khu vực', 'vùng đất hẹp, có nhiều núi bao quanh, thuận lợi tổ chức phòng thủ',
    4, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là D: vùng đất hẹp, có nhiều núi bao quanh, thuận lợi tổ chức phòng thủ'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS7_B10_17', '9b755e9a-7f9b-44a3-83f6-e738fbcf101a', 'LS7_KNTT_B10', 'Nhóm việc làm phản ánh rõ ý thức khẳng định vị thế độc lập của nhà Đinh',
    'xưng Hoàng đế, đặt quốc hiệu và niên hiệu, đúc tiền, giao hảo với nhà Tống', 'giữ nguyên danh xưng cũ, dùng tiền nhà Tống và không đặt niên hiệu riêng', 'trao quyền cho các sứ quân, bãi bỏ quân đội và luật lệ của triều đình', 'dời đô ra Đại La, lập Quốc Tử Giám và tổ chức khoa thi Nho học đầu tiên',
    1, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là A: xưng Hoàng đế, đặt quốc hiệu và niên hiệu, đúc tiền, giao hảo với nhà Tống'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS7_B10_18', '9b755e9a-7f9b-44a3-83f6-e738fbcf101a', 'LS7_KNTT_B10', 'Các nhà sư có vị trí đáng kể trong đời sống xã hội thời Đinh - Tiền Lê vì',
    'họ trực tiếp nắm toàn bộ quân đội và hệ thống quan lại ở địa phương', 'Phật giáo phổ biến, nhiều nhà sư có học thức và được triều đình coi trọng', 'Nho giáo bị cấm hoàn toàn nên chỉ nhà sư mới được phép sử dụng chữ viết', 'các nhà sư là lực lượng đông nhất và trực tiếp cày cấy ruộng công làng xã',
    2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: Phật giáo phổ biến, nhiều nhà sư có học thức và được triều đình coi trọng'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
