) VALUES (
    'Q_LS7_B10_19', '9b755e9a-7f9b-44a3-83f6-e738fbcf101a', 'LS7_KNTT_B10', 'Nhận xét phù hợp về cơ cấu xã hội thời Đinh - Tiền Lê',
    'mọi tầng lớp có địa vị ngang nhau vì đất nước vừa giành lại độc lập', 'thương nhân là lực lượng đông nhất và giữ địa vị cao nhất trong xã hội', 'xã hội gồm bộ phận thống trị và bị trị, trong đó nông dân đông đảo nhất', 'nô tì chiếm phần lớn dân cư và là lực lượng chính trong bộ máy nhà nước',
    3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: xã hội gồm bộ phận thống trị và bị trị, trong đó nông dân đông đảo nhất'
);
INSERT INTO lesson_question (
