INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS7_B11_13', 'bc6ab0f1-90d7-4090-979b-f69da4c16837', 'LS7_KNTT_B11', 'Lý Công Uẩn chọn Đại La làm kinh đô chủ yếu vì',
    'vị trí thuận lợi, địa thế rộng cao, dân cư và sản vật dễ phát triển', 'nơi đây nằm biệt lập với các tuyến giao thông và xa khu vực dân cư đông đúc', 'địa hình hiểm trở phù hợp xây kinh đô khép kín, ít liên hệ các vùng khác', 'gần biên giới phía bắc, thuận tiện tập trung vào hoạt động quân sự',
    1, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là A: vị trí thuận lợi, địa thế rộng cao, dân cư và sản vật có điều kiện phát triển'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS7_B11_14', 'bc6ab0f1-90d7-4090-979b-f69da4c16837', 'LS7_KNTT_B11', 'Việc tổ chức chính quyền từ Trung ương đến địa phương dưới thời Lý cho thấy',
    'triều đình trao toàn bộ quyền cho tù trưởng, hào trưởng địa phương', 'nhà Lý củng cố bộ máy quản lí, tăng quyền lực chính quyền trung ương', 'nhà Lý duy trì mô hình cai trị thời Bắc thuộc ở mọi cấp hành chính', 'quyền lực vua bị thu hẹp do các lộ, phủ, châu hoạt động độc lập',
    2, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là B: nhà Lý từng bước củng cố bộ máy quản lí và tăng cường quyền lực của chính quyền trung ương'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS7_B11_15', 'bc6ab0f1-90d7-4090-979b-f69da4c16837', 'LS7_KNTT_B11', 'Việc ban hành Hình thư và xây dựng quân đội được huấn luyện chu đáo phản ánh',
    'triều đình chỉ chú ý nghi lễ, chưa quản lí xã hội và bảo vệ đất nước', 'nhà Lý giảm vai trò luật pháp, giao việc phòng thủ cho địa phương', 'nhà Lý coi trọng pháp luật, giữ trật tự và bảo vệ quốc gia', 'triều đình dùng dân binh thay quân đội, bỏ cấm quân ở kinh thành',
    3, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là C: nhà Lý chú trọng xây dựng pháp luật, giữ trật tự và tăng cường khả năng bảo vệ quốc gia'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS7_B11_16', 'bc6ab0f1-90d7-4090-979b-f69da4c16837', 'LS7_KNTT_B11', 'Chính sách mềm dẻo với tù trưởng miền núi nhưng kiên quyết trấn áp thế lực li khai thể hiện',
    'nhà Lý để các vùng miền núi tách khỏi sự quản lí của triều đình', 'triều đình chỉ dùng quân sự, không dùng hôn nhân hay liên kết', 'nhà Lý bỏ mục tiêu đoàn kết dân cư để tập trung đối ngoại', 'kết hợp củng cố khối đoàn kết dân tộc và bảo vệ thống nhất Đại Việt',
    4, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là D: sự kết hợp linh hoạt giữa củng cố đoàn kết dân tộc và bảo vệ sự thống nhất của Đại Việt'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS7_B11_17', 'bc6ab0f1-90d7-4090-979b-f69da4c16837', 'LS7_KNTT_B11', 'Những biện pháp khai hoang, đào kênh mương, đắp đê và bảo vệ trâu bò có tác dụng chủ yếu',
    'thúc đẩy sản xuất nông nghiệp, mở rộng canh tác, ổn định đời sống', 'chuyển kinh tế nông nghiệp sang khai thác khoáng sản quy mô lớn', 'hạn chế mở rộng đất để dồn lao động làm thủ công cho triều đình', 'giảm vai trò làng xã, đưa ruộng đất về tay nhà vua trực tiếp quản lí',
    1, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là A: khuyến khích sản xuất nông nghiệp, mở rộng canh tác và góp phần ổn định đời sống'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS7_B11_18', 'bc6ab0f1-90d7-4090-979b-f69da4c16837', 'LS7_KNTT_B11', 'Việc năm 1040 nhà vua cho dùng gấm vóc do trong nước dệt được thay cho hàng Tống cho thấy',
    'thủ công nghiệp suy giảm nên triều đình phải tiết kiệm hàng dệt', 'nghề dệt tiến bộ, thể hiện khả năng sản xuất và ý thức tự chủ kinh tế', 'nhà Lý cấm hoàn toàn việc trao đổi hàng hóa với Trung Quốc thời đó', 'thủ công nghiệp chỉ có trong cung đình, chưa phát triển trong dân',
    2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: nghề dệt trong nước có bước tiến, thể hiện khả năng sản xuất và ý thức tự chủ về kinh tế'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS7_B11_19', 'bc6ab0f1-90d7-4090-979b-f69da4c16837', 'LS7_KNTT_B11', 'Sự hình thành các chợ, trung tâm trao đổi và cảng Vân Đồn phản ánh',
    'thương nghiệp chỉ phục vụ triều đình, không gắn với địa phương', 'buôn bán bên ngoài bị hạn chế, kinh tế khép kín trong làng xã', 'thương nghiệp phát triển trong nước, biên giới và ngoại thương', 'kinh tế chuyển hẳn sang thương nghiệp, nông nghiệp mất vai trò',
    3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: thương nghiệp phát triển với mạng lưới trao đổi trong nước, biên giới và giao thương với nước ngoài'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS7_B11_20', 'bc6ab0f1-90d7-4090-979b-f69da4c16837', 'LS7_KNTT_B11', 'Việc dựng Văn Miếu, mở khoa thi và lập Quốc Tử Giám phản ánh',
    'Phật giáo bị xoá bỏ hoàn toàn khỏi đời sống từ nửa sau thế kỉ XI', 'triều đình chỉ dạy quý tộc, không cần bổ sung người tài cho bộ máy', 'nhà Lý thay thi cử bằng chế độ cha truyền con nối cho mọi chức vụ', 'nhà Lý ngày càng coi trọng học tập, thi cử và tuyển chọn người tài',
    4, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là D: nhà Lý ngày càng coi trọng học tập, thi cử và tuyển chọn người có năng lực phục vụ đất nước'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS7_B11_21', 'bc6ab0f1-90d7-4090-979b-f69da4c16837', 'LS7_KNTT_B11', 'Từ các đặc điểm của Đại La trong Chiếu dời đô, đánh giá phù hợp về quyết định của Lý Công Uẩn',
    'thể hiện tầm nhìn chiến lược khi chọn trung tâm phát triển lâu dài', 'nhằm tách kinh đô khỏi dân cư, hạn chế giao lưu giữa các vùng', 'chỉ nhằm phòng thủ trước mắt, ít có ý nghĩa phát triển quốc gia', 'cho thấy triều đình ưu tiên địa hình biệt lập hơn kinh tế, giao thông',
    1, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là A: quyết định thể hiện tầm nhìn chiến lược khi lựa chọn một trung tâm có điều kiện phát triển lâu dài'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS7_B11_22', 'bc6ab0f1-90d7-4090-979b-f69da4c16837', 'LS7_KNTT_B11', 'Kết hợp các mốc 1009, 1010 và 1054, nhận xét có cơ sở về quá trình xây dựng đất nước thời Lý',
    'chỉ đổi tên kinh đô, chưa có bước củng cố nào về nhà nước, quốc gia', 'từng bước lập vương triều, định đô mới và củng cố vị thế Đại Việt', 'cho thấy nhà Lý muốn quay lại mô hình lệ thuộc chính trị phương Bắc', 'nhà Lý liên tục đổi kinh đô vì chưa tìm được trung tâm ổn định',
    2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: nhà Lý từng bước xác lập vương triều, xây dựng trung tâm chính trị mới và củng cố ý thức quốc gia Đại Việt'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS7_B11_23', 'bc6ab0f1-90d7-4090-979b-f69da4c16837', 'LS7_KNTT_B11', 'Từ chính sách nông nghiệp, sự phát triển thủ công nghiệp và hoạt động buôn bán, kết luận phù hợp',
    'kinh tế chỉ dựa vào tự cấp, thủ công và buôn bán không phát triển', 'thủ công và thương nghiệp phát triển nhưng tách rời chính sách nhà nước', 'kinh tế phát triển toàn diện, chú trọng nông, thủ công và thương nghiệp', 'chỉ quan tâm thương nghiệp, còn nông nghiệp và thủ công nghiệp suy giảm',
    3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: nền kinh tế có bước phát triển tương đối toàn diện, trong đó nông nghiệp được coi trọng cùng thủ công và thương nghiệp'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS7_B11_24', 'bc6ab0f1-90d7-4090-979b-f69da4c16837', 'LS7_KNTT_B11', 'Kết hợp tình hình tôn giáo, văn học, nghệ thuật và giáo dục, đánh giá phù hợp về văn hoá thời Lý',
