) VALUES (
    'Q_LS7_B12_15', '59e7a729-5c0a-4ee8-b581-e7557a212cb7', 'LS7_KNTT_B12', 'Sông Như Nguyệt được chọn làm nơi xây dựng phòng tuyến chủ yếu vì',
    'nằm hoàn toàn ngoài đường tiến quân của quân Tống', 'là con sông duy nhất nối Đại Việt với lãnh thổ nhà Tống', 'chắn đường bộ vào Thăng Long và có địa thế thuận lợi phòng ngự', 'có thể giúp quân Đại Việt tránh mọi cuộc giao chiến với quân Tống',
    3, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là C: chắn đường bộ vào Thăng Long và có địa thế thuận lợi phòng ngự'
);
INSERT INTO lesson_question (
