) VALUES (
    'Q_LS7_B12_16', '59e7a729-5c0a-4ee8-b581-e7557a212cb7', 'LS7_KNTT_B12', 'Việc bố trí thuỷ binh ở vùng Đông Bắc kết hợp với phòng tuyến sông Như Nguyệt nhằm',
    'đưa toàn bộ lực lượng Đại Việt chuyển sang chiến đấu trên biển', 'mở đường cho quân Tống rút nhanh về nước theo cả hai hướng', 'tách quân bộ Đại Việt khỏi lực lượng phòng thủ ở vùng biên giới', 'ngăn thuỷ quân Tống phối hợp với quân bộ trong cuộc tiến công',
    4, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là D: ngăn thuỷ quân Tống phối hợp với quân bộ trong cuộc tiến công'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
