) VALUES (
    'Q_LS7_B12_17', '59e7a729-5c0a-4ee8-b581-e7557a212cb7', 'LS7_KNTT_B12', 'Việc Lý Thường Kiệt cho người ngâm bài Nam quốc sơn hà trong lúc chiến đấu có tác dụng chủ yếu',
    'khẳng định chính nghĩa và khích lệ tinh thần chiến đấu của quân sĩ', 'thông báo cho quân Tống biết kế hoạch phản công của Đại Việt', 'thay thế hoàn toàn các biện pháp quân sự trên phòng tuyến', 'kêu gọi quân Tống cùng phối hợp chống lại lực lượng của Quách Quỳ',
    1, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là A: khẳng định chính nghĩa và khích lệ tinh thần chiến đấu của quân sĩ'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
