) VALUES (
    'Q_LS7_B12_18', '59e7a729-5c0a-4ee8-b581-e7557a212cb7', 'LS7_KNTT_B12', 'Quách Quỳ nhiều lần cho quân tìm cách vượt sông Như Nguyệt nhưng đều bị đẩy lùi cho thấy',
    'quân Tống đã hoàn toàn chủ động trong toàn bộ cuộc chiến', 'phòng tuyến phát huy hiệu quả, khiến quân Tống ngày càng bị động', 'quân Đại Việt chỉ phòng thủ mà không chuẩn bị bất kì cuộc phản công nào', 'thuỷ quân Tống đã phối hợp thành công với quân bộ ở phía bắc',
    2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: phòng tuyến phát huy hiệu quả, khiến quân Tống ngày càng bị động'
);
INSERT INTO lesson_question (
