) VALUES (
    'Q_LS7_B12_19', '59e7a729-5c0a-4ee8-b581-e7557a212cb7', 'LS7_KNTT_B12', 'Lý Thường Kiệt mở cuộc phản công lớn vào cuối mùa xuân năm 1077 khi quân Tống đã mệt mỏi cho thấy',
    'quân Đại Việt chuyển sang rút lui để bảo toàn lực lượng', 'nhà Lý chỉ dựa vào phòng tuyến và không quan tâm thời cơ', 'người chỉ huy biết chọn thời cơ chuyển từ phòng ngự sang tiến công', 'mục tiêu của Đại Việt là kéo dài chiến tranh càng lâu càng tốt',
    3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: người chỉ huy biết chọn thời cơ chuyển từ phòng ngự sang tiến công'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS7_B12_20', '59e7a729-5c0a-4ee8-b581-e7557a212cb7', 'LS7_KNTT_B12', 'Việc chủ động đề nghị giảng hoà khi đang ở thế thắng phản ánh cách kết thúc chiến tranh',
    'bị động vì Đại Việt đã mất hoàn toàn khả năng tiếp tục chiến đấu', 'nhượng bộ vì quân Tống đã làm chủ toàn bộ phòng tuyến Như Nguyệt', 'cứng nhắc vì chỉ chú trọng tiêu diệt quân địch đến người cuối cùng', 'linh hoạt, hạn chế tổn thất không cần thiết và tạo điều kiện hoà bình',
    4, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là D: linh hoạt, hạn chế tổn thất không cần thiết và tạo điều kiện hoà bình'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS7_B12_21', '59e7a729-5c0a-4ee8-b581-e7557a212cb7', 'LS7_KNTT_B12', 'Chuỗi hành động tiến công sang đất Tống, lập phòng tuyến, phản công rồi giảng hoà phản ánh nét độc đáo nổi bật',
    'chủ động về chiến lược, linh hoạt giữa tiến công, phòng thủ và ngoại giao', 'chỉ tập trung cố thủ lâu dài để làm tiêu hao lực lượng quân Tống', 'luôn tránh giao chiến trực tiếp và dựa hoàn toàn vào địa hình hiểm trở', 'đặt mục tiêu mở rộng lãnh thổ cao hơn nhiệm vụ bảo vệ nền độc lập',
    1, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là A: chủ động về chiến lược, linh hoạt giữa tiến công, phòng thủ và ngoại giao'
);
INSERT INTO lesson_question (
