) VALUES (
    'Q_LS7_B14_17', 'dec49919-7b33-4933-b216-f93a8c1bacd3', 'LS7_KNTT_B14', 'Chiến thắng Vân Đồn - Cửa Lục đầu năm 1288 có tác động trực tiếp đối với quân Nguyên',
    'làm mất nguồn lương thực quan trọng và đẩy quân địch vào khó khăn', 'buộc toàn bộ quân bộ của Thoát Hoan đầu hàng ngay tại Thăng Long', 'khiến quân Nguyên chuyển toàn bộ lực lượng sang tiến công bằng đường biển', 'giúp quân Nguyên giữ vững căn cứ Vạn Kiếp và tiếp tục tiến công lâu dài',
    1, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là A: làm mất nguồn lương thực quan trọng và đẩy quân địch vào khó khăn'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
