) VALUES (
    'Q_LS7_B14_18', 'dec49919-7b33-4933-b216-f93a8c1bacd3', 'LS7_KNTT_B14', 'Việc bố trí bãi cọc ngầm và chọn thời điểm nước triều ở Bạch Đằng năm 1288 thể hiện',
    'sự phụ thuộc hoàn toàn vào yếu tố tự nhiên trong tổ chức chiến đấu', 'chủ trương tránh giao chiến trực tiếp với thuỷ quân của quân Nguyên', 'nghệ thuật lợi dụng địa hình, thuỷ triều kết hợp mai phục và phản công', 'kế hoạch chỉ nhằm cản đường rút lui mà không tiêu diệt lực lượng địch',
    3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: nghệ thuật lợi dụng địa hình, thuỷ triều kết hợp mai phục và phản công'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
