) VALUES (
    'Q_LS7_B14_19', 'dec49919-7b33-4933-b216-f93a8c1bacd3', 'LS7_KNTT_B14', 'Điểm chung nổi bật trong cách đánh của nhà Trần ở cả ba lần kháng chiến',
    'luôn giữ Thăng Long bằng mọi giá ngay từ khi quân địch tiến vào', 'chủ động tránh chỗ mạnh, bảo toàn lực lượng rồi phản công khi thời cơ đến', 'chỉ sử dụng thuỷ quân và không tổ chức chiến đấu trên các tuyến đường bộ', 'đưa quân sang đất địch trước khi quân Mông - Nguyên mở cuộc xâm lược',
    2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: chủ động tránh chỗ mạnh, bảo toàn lực lượng rồi phản công khi thời cơ đến'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS7_B14_20', 'dec49919-7b33-4933-b216-f93a8c1bacd3', 'LS7_KNTT_B14', 'Ý nghĩa quốc tế được SGK nêu về thắng lợi của ba lần kháng chiến chống Mông - Nguyên',
    'mở đầu quá trình hình thành nhà nước phong kiến độc lập ở Đại Việt', 'giúp Đại Việt mở rộng lãnh thổ sang toàn bộ khu vực Đông Nam Á', 'làm cho đế chế Mông - Nguyên chấm dứt tồn tại ngay sau năm 1288', 'Góp phần ngăn chặn xâm lược Nhật Bản, Đông Nam Á và làm suy yếu đế chế',
    4, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là D: góp phần ngăn chặn xâm lược đối với Nhật Bản, Đông Nam Á và làm suy yếu đế chế'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS7_B14_21', 'dec49919-7b33-4933-b216-f93a8c1bacd3', 'LS7_KNTT_B14', 'Từ diễn biến hai cuộc kháng chiến năm 1258 và 1285, nhận xét phù hợp về việc quân địch chiếm Thăng Long',
    'Cả hai lần địch đều biến Thăng Long thành căn cứ ổn định, đủ lương thực', 'Quân Trần mất hoàn toàn khả năng phản công sau khi rời Thăng Long', 'Chiếm kinh thành không đồng nghĩa với khuất phục triều đình và quân dân', 'Nhà Trần chủ động giao kinh thành cho địch, không tổ chức đánh trả',
    3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: việc chiếm kinh thành không đồng nghĩa với khuất phục được triều đình và quân dân Đại Việt'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
