INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS7_B17_13', '5cf5d0e7-2761-461e-8c23-7e1e23e59874', 'LS7_KNTT_B17', 'Sự thành lập nhà Lê sơ năm 1428 phản ánh kết quả trực tiếp của quá trình',
    'giành lại độc lập, khôi phục quốc gia sau thắng lợi của khởi nghĩa Lam Sơn', 'mở rộng lãnh thổ về phía nam sau cuộc tiến quân năm 1471', 'cải tổ bộ máy hành chính dưới triều vua Lê Thánh Tông', 'xây dựng hệ thống trường học và tổ chức khoa cử thường xuyên',
    1, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là A: giành lại độc lập, khôi phục quốc gia sau thắng lợi của khởi nghĩa Lam Sơn'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS7_B17_15', '5cf5d0e7-2761-461e-8c23-7e1e23e59874', 'LS7_KNTT_B17', 'Các biện pháp đặt Khuyến nông sứ, thực hiện quân điền, khai hoang và làm thủy lợi cho thấy',
    'nhà Lê sơ chỉ dựa vào thương nghiệp, ít quan tâm sản xuất nông nghiệp', 'ruộng công làng xã bị xóa bỏ hoàn toàn sang sở hữu tư nhân địa chủ', 'triều đình coi trọng phục hồi, mở rộng nông nghiệp và ổn định đời sống', 'nông nghiệp tự phát, hầu như không có chính sách hỗ trợ từ nhà nước',
    3, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là C: triều đình coi trọng phục hồi, mở rộng sản xuất nông nghiệp và ổn định đời sống'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS7_B17_16', '5cf5d0e7-2761-461e-8c23-7e1e23e59874', 'LS7_KNTT_B17', 'Sự xuất hiện nhiều làng nghề, phường nghề và sản phẩm gốm được thương nhân nước ngoài đặt mua phản ánh',
    'thủ công nghiệp chỉ phục vụ cung đình, chưa gắn với trao đổi hàng hóa', 'thủ công nghiệp bị thu hẹp do nhà nước chỉ tập trung vào nông nghiệp', 'nghề thủ công mất dần, bị thay hoàn toàn bằng hàng nhập khẩu', 'thủ công nghiệp theo hướng chuyên môn hoá hơn, gắn với thị trường',
    4, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là D: thủ công nghiệp phát triển theo hướng chuyên môn hoá hơn và có liên hệ với thị trường'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS7_B17_17', '5cf5d0e7-2761-461e-8c23-7e1e23e59874', 'LS7_KNTT_B17', 'Việc lập chợ, duy trì Vân Đồn và đón thuyền buôn nhiều nước cho thấy thương nghiệp thời Lê sơ',
    'có bước phát triển cả trong nước và trong quan hệ buôn bán với bên ngoài', 'chỉ giới hạn trong phạm vi làng xã và không có các trung tâm trao đổi lớn', 'phụ thuộc hoàn toàn vào ngoại thương, buôn bán nội địa suy giảm', 'bị triều đình đình chỉ để ưu tiên tuyệt đối cho sản xuất nông nghiệp',
    1, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là A: có bước phát triển cả trong nước và trong quan hệ buôn bán với bên ngoài'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS7_B17_18', '5cf5d0e7-2761-461e-8c23-7e1e23e59874', 'LS7_KNTT_B17', 'Tầng lớp quý tộc, quan lại, địa chủ có nhiều đặc quyền, trong khi nông dân chiếm số đông phản ánh',
    'xã hội không còn phân chia tầng lớp, mọi người có địa vị như nhau', 'xã hội phân hoá rõ về quyền lợi và nghĩa vụ giữa các tầng lớp', 'nông dân trở thành giai cấp thống trị, nắm bộ máy nhà nước', 'thợ thủ công, thương nhân có địa vị cao hơn quan lại, nắm ruộng đất',
    2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: xã hội có sự phân hoá rõ, trong đó quyền lợi và nghĩa vụ giữa các tầng lớp khác nhau'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS7_B17_19', '5cf5d0e7-2761-461e-8c23-7e1e23e59874', 'LS7_KNTT_B17', 'Nho giáo được đề cao, văn học chữ Hán và chữ Nôm cùng phát triển cho thấy',
    'văn hoá chỉ tiếp nhận bên ngoài, không mang tinh thần dân tộc', 'Nho giáo làm sáng tác văn học và nghiên cứu lịch sử chấm dứt', 'văn hoá vừa gắn với Nho giáo vừa có nhiều thành tựu đậm bản sắc dân tộc', 'chữ Nôm bị cấm sử dụng nên mọi tác phẩm đều viết bằng chữ Hán',
    3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: đời sống văn hoá vừa gắn với nhà nước Nho giáo vừa có nhiều thành tựu mang bản sắc dân tộc'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS7_B17_20', '5cf5d0e7-2761-461e-8c23-7e1e23e59874', 'LS7_KNTT_B17', 'Việc phục hồi Quốc Tử Giám, tổ chức khoa thi và dựng bia Tiến sĩ thể hiện',
    'triều đình chỉ chú trọng nghi lễ, không quan tâm đào tạo người tài', 'giáo dục chủ yếu dành cho thợ thủ công và thương nhân ở các đô thị lớn', 'việc học giao hoàn toàn cho làng xã, nhà nước không tổ chức thi cử', 'nhà Lê sơ coi trọng giáo dục, khoa cử và việc tuyển chọn, tôn vinh nhân tài',
    4, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là D: nhà Lê sơ coi trọng giáo dục, khoa cử và việc tuyển chọn, tôn vinh nhân tài'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS7_B17_21', '5cf5d0e7-2761-461e-8c23-7e1e23e59874', 'LS7_KNTT_B17', 'Từ bộ máy tập quyền, Quốc triều hình luật và việc xây dựng quân đội mạnh, nhận xét phù hợp',
    'nhà Lê sơ tăng cường năng lực quản lí, giữ kỉ cương và bảo vệ quốc gia', 'triều đình giảm quyền trung ương, để các thừa tuyên tự quyết mọi việc', 'pháp luật ban hành nhưng không gắn với chính quyền và bảo vệ đất nước', 'quân đội quản lí toàn bộ xã hội, thay thế bộ máy hành chính',
    1, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là A: nhà Lê sơ tăng cường năng lực quản lí, giữ kỉ cương và bảo vệ quốc gia'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS7_B17_22', '5cf5d0e7-2761-461e-8c23-7e1e23e59874', 'LS7_KNTT_B17', 'Kết hợp chính sách nông nghiệp, sự phát triển của làng nghề và hoạt động buôn bán, kết luận phù hợp',
    'kinh tế chỉ phục hồi nông nghiệp, các ngành khác hầu như đình trệ', 'kinh tế phục hồi, phát triển đa dạng, nông nghiệp đóng vai trò chính', 'ngoại thương là yếu tố duy nhất giúp kinh tế thời Lê sơ phát triển', 'thủ công nghiệp phát triển khiến triều đình bỏ bê ruộng đất, thủy lợi',
    2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: kinh tế có bước phục hồi và phát triển khá đa dạng, với nông nghiệp giữ vai trò quan trọng'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS7_B17_23', '5cf5d0e7-2761-461e-8c23-7e1e23e59874', 'LS7_KNTT_B17', 'Từ Đại Việt sử ký toàn thư, Dư địa chí, Hồng Đức bản đồ và các tác phẩm toán học, nhận xét phù hợp',
    'tri thức chỉ tập trung vào văn chương, chưa có thành tựu khoa học khác', 'học thuật chủ yếu sao chép bên ngoài, ít gắn với thực tiễn Đại Việt', 'học thuật phát triển nhiều lĩnh vực, góp phần hiểu và quản lí đất nước', 'các thành tựu sử học, địa lí, toán học chỉ xuất hiện sau thời Lê sơ',
    3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: đời sống học thuật phát triển trên nhiều lĩnh vực, góp phần hiểu và quản lí đất nước'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS7_B17_24', '5cf5d0e7-2761-461e-8c23-7e1e23e59874', 'LS7_KNTT_B17', 'Lời dạy "một thước núi, một tấc sông" và việc củng cố bộ máy, lãnh thổ của Lê Thánh Tông cho thấy',
