) VALUES (
    'Q_LS8_B04_15', '3f91b22e-7ccc-487a-8622-9f5abc92b901', 'LS8_KNTT_B04', 'Việc xây dựng đường giao thông ở thuộc địa cho thấy đặc điểm chủ yếu của chính sách kinh tế thực dân',
    'đầu tư hạ tầng chủ yếu để nâng cao đời sống cư dân và cân bằng vùng miền', 'ưu tiên kết nối các trung tâm văn hoá nhằm bảo tồn bản sắc truyền thống', 'phát triển giao thông độc lập với hoạt động khai thác và mục tiêu quân sự', 'gắn hạ tầng với khai thác kinh tế và khả năng kiểm soát, đàn áp thuộc địa',
    4, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là D: gắn hạ tầng với khai thác kinh tế và khả năng kiểm soát, đàn áp thuộc địa'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
