    'Q_LS9_B01_07', 'e94c2c8e-6887-41a5-948a-4fcc029feb96', 'LS9_KNTT_B01', 'Trong quá trình xây dựng chủ nghĩa xã hội (1925-1941), Liên Xô đã đặt trọng tâm phát triển lĩnh vực nào?',
    'Thương nghiệp.', 'Công nghiệp nặng.', 'Công nghiệp nhẹ.', 'Thủ công nghiệp.',
    2, 20, 'WARM_UP', 'EASY', 'Đáp án đúng là B: Công nghiệp nặng.'
);
INSERT INTO lesson_question (
