) VALUES (
    'Q_LS9_B01_11', 'e94c2c8e-6887-41a5-948a-4fcc029feb96', 'LS9_KNTT_B01', 'Liên Xô bước vào quá trình xây dựng chủ nghĩa xã hội trong bối cảnh nào?',
    'Là nước nông nghiệp, bị các nước bao vây, cấm vận.', 'Bình thường hóa quan hệ ngoại giao với Mỹ và Tây Âu.', 'Chịu tác động sâu sắc của khủng hoảng kinh tế 1929-1933.', 'Hệ thống xã hội chủ nghĩa đã hình thành và phát triển.',
    1, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là A: Là nước nông nghiệp, bị các nước bao vây, cấm vận.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B01_12', 'e94c2c8e-6887-41a5-948a-4fcc029feb96', 'LS9_KNTT_B01', 'Nội dung nào phản ánh đúng tình hình đất nước Liên Xô từ năm 1925 đến năm 1945?',
    'Công cuộc tập thể hóa nông nghiệp đã hoàn thành.', 'Cơ cấu giai cấp trong xã hội không thay đổi lớn.', 'Phổ cập trung học cơ sở ở các vùng nông thôn.', 'Quá trình công nghiệp hóa, đô thị hóa đã tạm dừng.',
    1, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là A: Công cuộc tập thể hóa nông nghiệp đã hoàn thành.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B01_13', 'e94c2c8e-6887-41a5-948a-4fcc029feb96', 'LS9_KNTT_B01', 'Chính sách Cộng sản thời chiến (1918 – 1921) và chính sách Kinh tế mới (1921 – 1925) ở Nga đều nhằm mục đích',
    'bảo vệ và xây dựng nước Nga Xô Viết.', 'phục hồi và phát triển nền kinh tế của Nga.', 'huy động mọi nguồn lực để chống thù trong, giặc ngoài.', 'xây dựng cơ sở vật chất của chủ nghĩa xã hội.',
    2, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là B: phục hồi và phát triển nền kinh tế của Nga.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B01_17', 'e94c2c8e-6887-41a5-948a-4fcc029feb96', 'LS9_KNTT_B01', 'Chính sách kinh tế mới của nước Nga không có tác động nào sau đây?',
    'Nền kinh tế Nga từng bước được phục hồi.', 'Đời sống nhân dân Nga được cải thiện.', 'Huy động lực lượng chống ngoại xâm.', 'Đất nước từng bước vượt qua khủng hoảng.',
    3, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là C: Huy động lực lượng chống ngoại xâm.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B01_18', 'e94c2c8e-6887-41a5-948a-4fcc029feb96', 'LS9_KNTT_B01', 'Đến năm 1940, ở nước Nga không còn tồn tại giai tầng nào?',
    'Giai cấp công nhân.', 'Giai cấp nông dân.', 'Giai cấp tư sản.', 'Tầng lớp trí thức',
    3, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là C: Giai cấp tư sản.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B01_19', 'e94c2c8e-6887-41a5-948a-4fcc029feb96', 'LS9_KNTT_B01', 'Năm 1920, những thắng lợi của Hồng quân trong việc đánh tan giặc ngoại xâm và nội phản đã',
    'bảo vệ thành quả của Cách mạng tháng Mười.', 'bảo vệ thành quả của Chính sách kinh tế mới.', 'ngăn chặn được nguy cơ chiến tranh trên thế giới.', 'góp phần kết thúc chiến tranh thế giới thứ nhất.',
    1, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là A: bảo vệ thành quả của Cách mạng tháng Mười.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B01_20', 'e94c2c8e-6887-41a5-948a-4fcc029feb96', 'LS9_KNTT_B01', 'Nhận xét nào đúng về tình hình nước Nga và các nước Cộng hòa Xô viết đồng minh trước khi thống nhất?',
    'Tăng cường sức mạnh để xây dựng thành công chủ nghĩa xã hội.', 'Xác định hướng đi mới cho các nước Cộng hoà Xô viết ở Nga.', 'Xác lập hệ thống xã hội chủ nghĩa làm đối trọng với chủ nghĩa tư bản.', 'Hình thành một quốc gia rộng lớn, có uy tín ở châu Âu và châu Á.',
    1, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là A: Tăng cường sức mạnh để xây dựng thành công chủ nghĩa xã hội.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B01_21', 'e94c2c8e-6887-41a5-948a-4fcc029feb96', 'LS9_KNTT_B01', 'Nước Nga đấu tranh chống thù trong, giặc ngoài (1918-1920) trong bối cảnh lịch sử nào?',
    'Chiến tranh thế giới thứ nhất chưa kết thúc.', 'Đất nước vô cùng khó khăn, gian khổ.', 'Chính quyền Xô viết chưa được xác lập.', 'Quyền lực của đế quốc Nga còn mạnh.',
    2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: Đất nước vô cùng khó khăn, gian khổ.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B01_22', 'e94c2c8e-6887-41a5-948a-4fcc029feb96', 'LS9_KNTT_B01', 'Nước Nga đã đạt được kết quả nào sau đây trong quá trình thực hiện nhiệm vụ trọng tâm giai đoạn (1918 - 1920)?',
    'Khắc phục được hậu quả của chiến tranh', 'Xóa bỏ hoàn toàn các tổ chức phản động.', 'Ký hòa ước với các nước đế quốc.', 'Bảo vệ được chính quyền cách mạng.',
    4, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là D: Bảo vệ được chính quyền cách mạng.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B01_23', 'e94c2c8e-6887-41a5-948a-4fcc029feb96', 'LS9_KNTT_B01', 'Tình hình nước Nga (1917 - 1920) và tình hình Việt Nam (1945 - 1946) có điểm tương đồng nào sau đây?',
    'Tiến hành trưng thu lương thực thừa.', 'Đấu tranh chống thù trong giặc ngoài.', 'Phát động phong trào bình dân học vụ.', 'Ban hành và thực thi “Sắc lệnh ruộng đất”.',
    2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: Đấu tranh chống thù trong giặc ngoài.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B01_25', 'e94c2c8e-6887-41a5-948a-4fcc029feb96', 'LS9_KNTT_B01', 'Từ năm 1922 đến năm 1941, công cuộc xây dựng chủ nghĩa xã hội ở Liên Xô đạt được kết quả tiêu biểu nào?',
    'Đạt được thế cân bằng về sức mạnh quân sự với Mỹ.', 'Phá vỡ thế độc quyền về vũ khí nguyên tử của Mỹ.', 'Mở rộng được không gian của chủ nghĩa xã hội.', 'Trở thành một trong những cường quốc của thế giới.',
    4, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là D: Trở thành một trong những cường quốc của thế giới.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B01_26', 'e94c2c8e-6887-41a5-948a-4fcc029feb96', 'LS9_KNTT_B01', 'Chính sách kinh tế mới của nước Nga năm 1921 được ban hành trong bối cảnh nào?',
    'Liên quân 14 nước tấn công vào nước Nga Xô viết.', 'Độc lập dân tộc bị đe dạo rất nghiêm trọng.', 'Nước Nga Xô viết đã vượt qua được khủng hoảng.', 'Chính sách Cộng sản thời chiến không còn phù hợp.',
    4, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là D: Chính sách Cộng sản thời chiến không còn phù hợp.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B01_27', 'e94c2c8e-6887-41a5-948a-4fcc029feb96', 'LS9_KNTT_B01', 'Ý nào sau đây mô tả đúng tình hình nước Nga trước khi Liên Xô được thành lập?',
    'Tiến hành xây dựng chủ nghĩa xã hội, trọng tâm là công nghiệp hoá.', 'Đấu tranh chống thù trong giặc ngoài, bảo vệ chính quyền cách mạng.', 'Tiến hành tập thể hóa nông nghiệp, tiêu diệt bộ phận bóc lột ở nông thôn.', 'Thực hiện cách mạng văn hóá, xoá nạn mù chữ trong cả nước.',
    2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: Đấu tranh chống thù trong giặc ngoài, bảo vệ chính quyền cách mạng.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B01_28', 'e94c2c8e-6887-41a5-948a-4fcc029feb96', 'LS9_KNTT_B01', 'Liên Xô được thành lập bao gồm những nước nào sau đây?',
    'Nga, Ba Lan, U-crai-na, Ngoại Cáp-ca-dơ.', 'Nga, Bê-lô-rút-xi-a, U-crai-na, Ngoại Cáp-ca-dơ.', 'Nga, Ba Lan, Lát-vi-a, Bê-lô-rút-xi-a.', 'Nga, Bê-lô-rút-xi-a, Lát-vi-a, U-crai-na.',
    2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: Nga, Bê-lô-rút-xi-a, U-crai-na, Ngoại Cáp-ca-dơ.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B01_29', 'e94c2c8e-6887-41a5-948a-4fcc029feb96', 'LS9_KNTT_B01', 'Thành tựu quan trọng trên lĩnh vực kinh tế của Liên Xô trong công cuộc xây dựng chủ nghĩa xã hội là',
    'trở thành cường quốc công nghiệp đứng thứ hai thế giới.', 'tỉ trọng nông nghiệp chiếm đa số trong cơ cấu kinh tế.', 'trở thành cường quốc công nghiệp đứng thứ hai châu Âu.', 'trở thành cường quốc nông nghiệp đứng đầu châu Âu.',
    1, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là A: trở thành cường quốc công nghiệp đứng thứ hai thế giới.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B01_31', 'e94c2c8e-6887-41a5-948a-4fcc029feb96', 'LS9_KNTT_B01', 'Nội dung nào sau đây không phải là hạn chế của công cuộc xây dựng chủ nghĩa xã hội ở Liên Xô giai đoạn 1925 - 1941?',
    'Mất cân đối giữa công nghiệp nặng và công nghiệp nhẹ.', 'Mất cân đối giữa ngành công nghiệp và ngành nông nghiệp.', 'Vi phạm nguyên tắc tự chủ trong công nghiệp hoá.', 'Vi phạm nguyên tắc tự nguyện trong tập thể hóa nông nghiệp.',
    3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: Vi phạm nguyên tắc tự chủ trong công nghiệp hoá.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B02_01', '580544ae-5a62-4fa1-9c27-bc26318c0bf3', 'LS9_KNTT_B02', 'Từ năm 1918 đến năm 1923, phong trào cách mạng ở các nước tư bản châu Âu không diễn ra mạnh mẽ ở nước nào sau đây?',
    'Đức.', 'Pháp.', 'Anh.', 'Liên Xô.',
    4, 20, 'WARM_UP', 'EASY', 'Đáp án đúng là D: Liên Xô.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B02_02', '580544ae-5a62-4fa1-9c27-bc26318c0bf3', 'LS9_KNTT_B02', 'Cuộc khủng hoảng kinh tế của nước Mỹ trong những năm 30 của thế kỷ XX bắt đầu từ lĩnh vực nào?',
    'Công nghiệp.', 'Nông nghiệp.', 'Thương nghiệp.', 'Tài chính.',
    4, 20, 'WARM_UP', 'EASY', 'Đáp án đúng là D: Tài chính.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B02_03', '580544ae-5a62-4fa1-9c27-bc26318c0bf3', 'LS9_KNTT_B02', 'Từ năm 1920, phong trào bãi công của công nhân Pháp đặt dưới sự lãnh đạo trực tiếp của',
    'Đảng Xã hội Pháp.', 'Quốc tế Cộng sản.', 'Mặt trận Nhân dân Pháp.', 'Đảng Cộng sản Pháp.',
    4, 20, 'WARM_UP', 'EASY', 'Đáp án đúng là D: Đảng Cộng sản Pháp.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B02_04', '580544ae-5a62-4fa1-9c27-bc26318c0bf3', 'LS9_KNTT_B02', 'Nội dung nào sau đây phản áng đúng phạm vi ảnh hưởng của cuộc khủng hoảng kinh tế thế giới 1929-1933?',
    'Chỉ ảnh hưởng ở các nước tư bản phát triển trên thế giới.', 'Chỉ có ở các nước tư bản phát triển và thuộc địa của chúng.', 'Bùng nổ đầu tiên ở châu Âu, sau đó lan rộng ra châu Mỹ.', 'Chỉ xuất hiện các nước phát xít và các nước phụ thuộc.',
    2, 20, 'WARM_UP', 'EASY', 'Đáp án đúng là B: Chỉ có ở các nước tư bản phát triển và thuộc địa của chúng.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B02_05', '580544ae-5a62-4fa1-9c27-bc26318c0bf3', 'LS9_KNTT_B02', 'Nhân tố nào sau đây đã cản trở hoạt động của Quốc tế Cộng sản?',
    'Chiến tranh thế giới thứ hai bùng nổ ra và lan rộng.', 'Sự thoái trào của các Đảng Cộng sản trên thế giới.', 'Chiến tranh lạnh bùng nổ và ngày càng quyết liệt.', 'Sự hình thành trật tự thế giới hai cực Ianta.',
    1, 20, 'WARM_UP', 'EASY', 'Đáp án đúng là A: Chiến tranh thế giới thứ hai bùng nổ ra và lan rộng.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B02_06', '580544ae-5a62-4fa1-9c27-bc26318c0bf3', 'LS9_KNTT_B02', 'Quốc gia nào sau đây bước vào giai đoạn phát triển hoàng kim trong những năm 20 của thế kỷ XX?',
    'Trung Quốc.', 'Anh.', 'Mỹ.', 'Pháp.',
    3, 20, 'WARM_UP', 'EASY', 'Đáp án đúng là C: Mỹ.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B02_07', '580544ae-5a62-4fa1-9c27-bc26318c0bf3', 'LS9_KNTT_B02', 'Cuộc khủng hoảng kinh tế thế giới 1929 - 1933 diễn ra đầu tiên ở Mỹ vì',
    'Mỹ thiếu một thị trường và hệ thống thuộc địa rộng lớn.', 'Mỹ đã đạt đến sự phồn vinh trong phát triển kinh tế.', 'những cuộc đình công, bãi công của công nhân ngày càng nhiều.', 'Mỹ bước vào quá trình công nghiệp tương đối muộn.',
    2, 20, 'WARM_UP', 'EASY', 'Đáp án đúng là B: Mỹ đã đạt đến sự phồn vinh trong phát triển kinh tế.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B02_08', '580544ae-5a62-4fa1-9c27-bc26318c0bf3', 'LS9_KNTT_B02', 'Nội dung nào sau đây phản ánh khuynh hướng phát triển của Quốc tế Cộng sản?',
    'Tạm dừng hoạt động trong Chiến tranh thế giới thứ hai.', 'Hoàn thành sứ mệnh của mình và tuyên bố giải tán.', 'Phân hóa thành các tổ chức cộng sản khác nhau.', 'Dẫn tới sự ra đời của tổ chức Liên hợp quốc.',
    2, 20, 'WARM_UP', 'EASY', 'Đáp án đúng là B: Hoàn thành sứ mệnh của mình và tuyên bố giải tán.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B02_09', '580544ae-5a62-4fa1-9c27-bc26318c0bf3', 'LS9_KNTT_B02', 'Sự phát triển của phong trào cách mạng ở châu Âu (1918-1923) đặt ra yêu cầu nào sau đây?',
    'Tăng cường đoàn kết với cách mạng thuộc địa để xóa bỏ tư sản.', 'Cần có một tổ chức quốc tế lãnh đạo đúng đắn và phù hợp.', 'Thay đổi mục tiêu đấu tranh kinh tế và mục tiêu chính trị.', 'Chấm dứt xung đột trong Chiến trnah thế giới thứ nhất.',
    2, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là B: Cần có một tổ chức quốc tế lãnh đạo đúng đắn và phù hợp.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B02_10', '580544ae-5a62-4fa1-9c27-bc26318c0bf3', 'LS9_KNTT_B02', 'Giai cấp nào sau đây giữ vai trò quan trọng trong phong trào cách mạng ở các nước tư bản châu Âu (1918-1923)',
    'Tiểu tư sản.', 'Công nhân.', 'Phú nông.', 'Tư sản.',
    2, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là B: Công nhân.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B02_12', '580544ae-5a62-4fa1-9c27-bc26318c0bf3', 'LS9_KNTT_B02', 'Cuộc khủng hoảng kinh tế thế giới 1929 - 1933 không để lại hậu quả trên lĩnh vực nào?',
    'Chính trị - xã hội.', 'Kinh tế thương mại.', 'Quan hệ quốc tế.', 'Chinh phục vũ trụ.',
    3, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là C: Quan hệ quốc tế.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B02_14', '580544ae-5a62-4fa1-9c27-bc26318c0bf3', 'LS9_KNTT_B02', 'Nội dung nào phản ánh đặc điểm chung của các nước tư bản Âu - Mỹ trong những năm 20 của thế kỷ XX?',
    'Lâm vào nhiều đợt suy thoái trầm trọng, kéo dài.', 'Từng bước hình thành nên phương thức sản xuất mới.', 'Phát triển mạnh mẽ, sản xuất tăng lên nhanh chóng.', 'Đã hình thành được khối thị trường chung ở châu Âu.',
    3, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là C: Phát triển mạnh mẽ, sản xuất tăng lên nhanh chóng.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B02_15', '580544ae-5a62-4fa1-9c27-bc26318c0bf3', 'LS9_KNTT_B02', 'Cuộc khủng hoảng kinh tế thế giới 1929 - 1933 diễn ra đầu tiên ở quốc gia nào sau đây?',
    'Anh.', 'Pháp.', 'Đức.', 'Mỹ.',
    4, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là D: Mỹ.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B02_16', '580544ae-5a62-4fa1-9c27-bc26318c0bf3', 'LS9_KNTT_B02', 'Nhận xét nào sau đây là đúng về phong trào đấu tranh của nhân dân Đức từ năm 1918 đến năm 1923?',
    'Có sự thay đổi về mục tiêu đấu tranh.', 'Ngăn cả quá trình phát xít hóa của Đức.', 'Thành lập được chính quyền Xô viết.', 'Làm sụp đổ hệ thống thuộc địa của Đức.',
    1, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là A: Có sự thay đổi về mục tiêu đấu tranh.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
