    'Q_LS9_B02_17', '580544ae-5a62-4fa1-9c27-bc26318c0bf3', 'LS9_KNTT_B02', 'Tổ chức nào được thành lập năm 1919 có vai trò quan trọng đối với phong trào cách mạng thế giới?',
    'Đảng Cộng sản Pháp.', 'Hội Quốc liên.', 'Liên hợp quốc.', 'Quốc tế Cộng sản.',
    4, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là D: Quốc tế Cộng sản.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
