) VALUES (
    'Q_LS9_B02_18', '580544ae-5a62-4fa1-9c27-bc26318c0bf3', 'LS9_KNTT_B02', 'Sự ra đời của Quốc tế Cộng sản năm 1919 nhờ vai trò tích cực của',
    'Hội Quốc liên.', 'Chiến tranh thế giới thứ nhất.', 'Quốc tế II.', 'Đảng Bônsêvích Nga.',
