);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B02_19', '580544ae-5a62-4fa1-9c27-bc26318c0bf3', 'LS9_KNTT_B02', 'Trong thời gian tồn tại (1919-1943), Quốc tế Cộng sản đã',
    'tạo cơ sở về mặt tổ chức và lý luận cho sự ra đời của Liên hợp quốc.', 'làm cho chủ nghĩa tư bản châu Âu bước vào thời kỳ khủng hoảng kéo dài.', 'đề ra đường lối cho từng thời kì phát triển của cách mạng thế giới.', 'hoàn thành sứ mệnh lịch sử trong việc bảo vệ hòa bình, an ninh thế giới.',
    3, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là C: đề ra đường lối cho từng thời kì phát triển của cách mạng thế giới.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B02_20', '580544ae-5a62-4fa1-9c27-bc26318c0bf3', 'LS9_KNTT_B02', 'Nhân tố nào sau đây thúc đẩy mạnh mẽ phong trào đấu tranh của nhân dân Đức giai đoạn 1918-1923?',
    'Chế độ quân chủ chuyên chế suy yếu.', 'Lãnh thổ bị chia cắt thành hai miền.', 'Sự ra đời của Đảng Cộng sản Đức.', 'Giai cấp công nhân Đức bị thất nghiệp.',
    3, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là C: Sự ra đời của Đảng Cộng sản Đức.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B02_22', '580544ae-5a62-4fa1-9c27-bc26318c0bf3', 'LS9_KNTT_B02', 'Ý nào sau đây không phải là nguyên nhân dẫn đến sự bùng nổ và phát triển của phong trào cách mạng 1918 - 1923 ở châu Âu?',
    'Ảnh hưởng của thắng lợi Cách mạng tháng Mười Nga.', 'Sự hình thành và phát triển của chủ nghĩa phát xít.', 'Sự thành lập chính quyền Xô viết ở nước Nga.', 'Tinh thần đấu tranh của công nhân, nhân dân lao động.',
    2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: Sự hình thành và phát triển của chủ nghĩa phát xít.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B02_23', '580544ae-5a62-4fa1-9c27-bc26318c0bf3', 'LS9_KNTT_B02', 'Ý nào sau đây là mục tiêu của phong trào cách mạng 1918 - 1923 ở châu Âu?',
    'Thành lập chính quyền do giai cấp tư sản tiến bộ lãnh đạo.', 'Xây dựng mô hình nhà nước mới theo kiểu nước Nga Xô viết.', 'Yêu cầu chính phủ kết thúc Chiến tranh thế giới thứ nhất.', 'Thành lập tổ chức quốc tế lãnh đạo phong trào công nhân.',
    2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: Xây dựng mô hình nhà nước mới theo kiểu nước Nga Xô viết.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B02_24', '580544ae-5a62-4fa1-9c27-bc26318c0bf3', 'LS9_KNTT_B02', 'Ý nghĩa của sự thành lập Quốc tế Cộng sản đối với phong trào cách mạng ở châu Âu là',
    'thúc đẩy sự phát triển của phong trào công nhân.', 'thúc đẩy sự hình thành nhiều nhà nước vô sản.', 'định hướng sự phát triển của phong trào nông dân.', 'giành ruộng đất và quyền lợi cho bộ phận tiểu nông.',
    1, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là A: thúc đẩy sự phát triển của phong trào công nhân.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B02_25', '580544ae-5a62-4fa1-9c27-bc26318c0bf3', 'LS9_KNTT_B02', 'Một trong những nguyên nhân dẫn đến sự hình thành của chủ nghĩa phát xít Đức là',
    'sự ủng hộ về vũ khí chiến tranh của I-ta-li-a.', 'sự phát triển kinh tế của Đức giai đoạn 1924 - 1929.', 'chính sách dung dưỡng, thoả hiệp của Anh, Pháp và Ba Lan.', 'hậu quả nặng nề của cuộc đại suy thoái kinh tế 1929 - 1933.',
    4, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là D: hậu quả nặng nề của cuộc đại suy thoái kinh tế 1929 - 1933.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B02_26', '580544ae-5a62-4fa1-9c27-bc26318c0bf3', 'LS9_KNTT_B02', 'Một trong những chính sách đối ngoại của Mỹ trong giai đoạn giữa hai cuộc chiến tranh thế giới (1918 - 1939) là',
    'tham gia tích cực vào hoạt động của Hội Quốc liên.', 'liên kết với Liên Xô chống chủ nghĩa phát xít.', 'thực hiện và đề cao chủ nghĩa biệt lập truyền thống.', 'viện trợ cho Anh, Pháp chống lại sự xâm lược của Đức.',
    3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: thực hiện và đề cao chủ nghĩa biệt lập truyền thống.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B02_27', '580544ae-5a62-4fa1-9c27-bc26318c0bf3', 'LS9_KNTT_B02', 'Ý nào sau đây phản ánh đúng sự phát triển của kinh tế Mỹ giai đoạn 1924-1929?',
    'Lâm vào đại suy thoái khiến sản lượng công nghiệp sụt giảm.', 'Phát triển nhanh chóng, xen kẽ với khủng hoảng nhẹ.', 'Trở thành trung tâm công nghiệp, thương mại, tài chính quốc tế.', 'Tiến hành công cuộc công nghiệp hoa xã hội chủ nghĩa.',
    3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: Trở thành trung tâm công nghiệp, thương mại, tài chính quốc tế.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B03_01', '338543d8-5d1b-4674-9c7e-aec9417752fe', 'LS9_KNTT_B03', 'Năm 1940, tình hình các nước Đông Nam Á có đặc điểm nổi bật nào sau đây?',
    'Liên minh khu vực được hình thành.', 'Các nước giành được độc lập.', 'Đảng Cộng sản ra đời ở các nước.', 'Phát xít Nhật tiến hành xâm lược.',
    4, 20, 'WARM_UP', 'EASY', 'Đáp án đúng là D: Phát xít Nhật tiến hành xâm lược.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B03_02', '338543d8-5d1b-4674-9c7e-aec9417752fe', 'LS9_KNTT_B03', 'Nhận xét vào đúng về phong trào đấu tranh giải phóng dân tộc ở Đông Nam Á từ năm 1920 đến năm 1940?',
    'Chủ yếu đấu tranh chống thực dân bằng phương pháp hoà bình.', 'Chuyển từ đấu tranh đòi độc lập sang đòi quyền lợi kinh tế.', 'Có sự chuyển biến từ khởi nghĩa vũ trang sang đấu tranh ôn hoà.', 'Phát triển đồng thời theo hai khuynh hướng: tư sản và vô sản.',
    4, 20, 'WARM_UP', 'EASY', 'Đáp án đúng là D: Phát triển đồng thời theo hai khuynh hướng: tư sản và vô sản.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B03_03', '338543d8-5d1b-4674-9c7e-aec9417752fe', 'LS9_KNTT_B03', 'Từ năm 1922, lãnh đạo phong trào đấu tranh của giai cấp công nhân Nhật Bản là',
    'Đảng Dân chủ.', 'Đảng Quốc đại.', 'Quốc dân Đảng.', 'Đảng Cộng sản.',
    4, 20, 'WARM_UP', 'EASY', 'Đáp án đúng là D: Đảng Cộng sản.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B03_04', '338543d8-5d1b-4674-9c7e-aec9417752fe', 'LS9_KNTT_B03', 'Năm 1927, ở Nhật Bản diễn ra sự kiện nào sau đây tác động tiêu cực đến nền kinh tế?',
    'Quân phiệt nắm giữ mọi quyền lực.', 'Động đất và sóng thần ở Nagasaki.', 'Thủ tướng Tanaca lên nắm quyền.', 'Cuộc khủng hoảng tài chính ở Tôkiô.',
    4, 20, 'WARM_UP', 'EASY', 'Đáp án đúng là D: Cuộc khủng hoảng tài chính ở Tôkiô.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B03_07', '338543d8-5d1b-4674-9c7e-aec9417752fe', 'LS9_KNTT_B03', 'Nhận xét nào đúng về cuộc đấu tranh giành độc lập ở Đông Nam Á từ năm 1920 đến năm 1945?',
    'Nhân dân đẩy mạnh đấu tranh chống xâm lược.', 'Khởi đầu cuộc đấu tranh giành độc lập dân tộc.', 'Giai cấp tư sản bước đầu tham gia đấu tranh.', 'Giai cấp vô sản bước lên vũ đài chính trị.',
    4, 20, 'WARM_UP', 'EASY', 'Đáp án đúng là D: Giai cấp vô sản bước lên vũ đài chính trị.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B03_08', '338543d8-5d1b-4674-9c7e-aec9417752fe', 'LS9_KNTT_B03', 'Sau khi ra đời, nước Cộng hòa nhân dân Mông Cổ đã',
    'từng bước tiến lên con đường xây dựng chủ nghĩa xã hội.', 'phát triển theo đường lối hòa bình, trung lập và tích cực.', 'tích cực viện trợ cho các nước châu Á đấu tranh giành độc lập.', 'đấu tranh kiên cường chống lại chính sách cấm vận của Mỹ.',
    1, 20, 'WARM_UP', 'EASY', 'Đáp án đúng là A: từng bước tiến lên con đường xây dựng chủ nghĩa xã hội.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B03_09', '338543d8-5d1b-4674-9c7e-aec9417752fe', 'LS9_KNTT_B03', 'Sự kiện nào đánh dấu bước ngoặt quan trọng trong lịch sử Trung Quốc từ năm 1918 đến năm 1945?',
    'Đảng Cộng sản Trung Quốc được thành lập.', 'Đảng Cộng sản đánh bại Quốc dân đảng.', 'Phong trào Ngũ Tứ bùng nổ và lan rộng.', 'Cuộc nội chiến giữa Quốc - Cộng lần thứ nhất.',
    1, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là A: Đảng Cộng sản Trung Quốc được thành lập.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B03_10', '338543d8-5d1b-4674-9c7e-aec9417752fe', 'LS9_KNTT_B03', 'Từ năm 1937 đến năm 1945, Quốc Dân đảng và Đảng Cộng sản có mối quan hệ nào sau đây?',
    'Đoàn kết chống lại sự xâu xé của đế quốc.', 'Diễn ra quá trình xung đột quân sự sâu sắc.', 'Đối đầu căng thẳng, chạy đua vũ trang.', 'Hợp tác để cùng kháng chiến chống Nhật.',
    4, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là D: Hợp tác để cùng kháng chiến chống Nhật.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B03_11', '338543d8-5d1b-4674-9c7e-aec9417752fe', 'LS9_KNTT_B03', 'Từ Năm 1937, nhân dân Trung Quốc đã phải thực hiện nhiệm vụ nào sau đây?',
    'Quốc hữu hóa các xí nghiệp để hạn chế ảnh hưởng của đế quốc.', 'Chống lại cuộc chiến tranh xâm lược của quân phiệt Nhật.', 'Tiến hành cuộc thập tự chinh để giải quyết nhiệm vụ dân chủ.', 'Chống lại chế độ phong kiến giành ruộng đất cho nhân dân.',
    2, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là B: Chống lại cuộc chiến tranh xâm lược của quân phiệt Nhật.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B03_12', '338543d8-5d1b-4674-9c7e-aec9417752fe', 'LS9_KNTT_B03', 'Quốc gia nào ở Đông Nam Á không bị Nhật Bản xâm lược và thống trị một cách lâu dài trong chiến tranh thế giới thứ hai?',
    'Thái Lan.', 'Xingapo.', 'Campuchia.', 'Inđônêxia.',
    1, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là A: Thái Lan.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B03_13', '338543d8-5d1b-4674-9c7e-aec9417752fe', 'LS9_KNTT_B03', 'Tháng 7/1921, Đảng Cộng sản Trung Quốc được thành lập dưới sự giúp đỡ của tổ chức nào sau đây?',
    'Hội Liên hiệp thuộc địa.', 'Hội Quốc liên.', 'Liên hợp quốc.', 'Quốc tế Cộng sản.',
    4, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là D: Quốc tế Cộng sản.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B03_14', '338543d8-5d1b-4674-9c7e-aec9417752fe', 'LS9_KNTT_B03', 'Nội dung nào sau đây phản ánh đúng đặc điểm của Nhật Bản ngay sau Chiến tranh thế giới thứ nhất?',
    'Nội bộ giới quân phiệt và tài phiệt Nhật có sự phân hóa sâu sắc.', 'Nền kinh tế Nhật Bản phát triển nhanh chóng sau chiến tranh.', 'Chính quyền Nhật Bản tiến hành quân sự hóa bộ máy nhà nước.', 'Cuộc khủng hoảng tài chính trầm trọng đã diễn ra ở Tôkiô.',
    2, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là B: Nền kinh tế Nhật Bản phát triển nhanh chóng sau chiến tranh.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B03_15', '338543d8-5d1b-4674-9c7e-aec9417752fe', 'LS9_KNTT_B03', 'Quốc gia nào sau đây không tiến hành xâm lược châu Á từ thế kỷ XIX đến thế kỷ XX?',
    'Nhật Bản.', 'Pháp.', 'Italia.', 'Mỹ.',
    3, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là C: Italia.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B03_16', '338543d8-5d1b-4674-9c7e-aec9417752fe', 'LS9_KNTT_B03', 'Ý nào sau đây là tình hình của Nhật Bản sau cuộc đại suy thoái kinh tế?',
    'Chủ nghĩa quân phiệt phục hồi, tiến hành đẩy mạnh chiến tranh xâm lược.', 'Đảng phát xít nắm quyền lãnh đạo, tiến hành quân sự hóa đất nước.', 'Chính phủ tìm cách khắc phục ảnh hưởng của cuộc khủng hoảng năng lượng.', 'Đảng Cộng sản lên nắm quyền, thực hiện các quyền tự do, dân chủ.',
    1, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là A: Chủ nghĩa quân phiệt phục hồi, tiến hành đẩy mạnh chiến tranh xâm lược.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B03_17', '338543d8-5d1b-4674-9c7e-aec9417752fe', 'LS9_KNTT_B03', 'Trong Chiến tranh thế giới thứ hai, Nhật Bản đẩy mạnh xâm lược khu vực nào sau đây?',
    'Mỹ La-tinh.', 'Đông Nam Á.', 'Tây Nam Á.', 'Đông Nam Âu.',
    2, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là B: Đông Nam Á.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B03_18', '338543d8-5d1b-4674-9c7e-aec9417752fe', 'LS9_KNTT_B03', 'Phong trào đấu tranh nào sau đây đã tạo điều kiện cho sự truyền bá của chủ nghĩa Mác – Lênin vào Trung Quốc?',
    'Phong trào Bách nhật Duy tân.', 'Phong trào Thái Bình Thiên Quốc.', 'Phong trào Nghĩa Hoà đoàn.', 'Phong trào Ngũ Tứ.',
    4, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là D: Phong trào Ngũ Tứ.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B03_20', '338543d8-5d1b-4674-9c7e-aec9417752fe', 'LS9_KNTT_B03', 'Tháng 8-1945, các quốc gia nào sau đây ở Đông Nam Á giành được chính quyền thành công?',
    'Việt Nam và Phi-lip-pin.', 'Xiêm và Mã Lai.', 'Việt Nam và In-dô-nê-xi-a.', 'In-dô-nê-xi-a và Lào.',
    3, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là C: Việt Nam và In-dô-nê-xi-a.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B04_01', '68ea07ba-94c0-4e5d-a997-d0b9272ea818', 'LS9_KNTT_B04', 'Giai đoạn 1939 - 1941, cuộc chiến tranh thế giới thứ hai mang tính chất phi nghĩa đối với cả hai bên tham chiến vì',
    'phát xít sử dụng lực lượng quân sự lớn, nhanh chóng đánh chiếm các nước.', 'các nước Anh, Pháp không thành thực ngăn cản chiến tranh phát xít.', 'Pháp bị quân Đức chiếm đóng và phải chịu mọi phí tổn của chiến tranh.', 'mặt trận Đồng minh chưa được thành lập để đoàn kết các dân tộc đấu tranh.',
    2, 20, 'WARM_UP', 'EASY', 'Đáp án đúng là B: các nước Anh, Pháp không thành thực ngăn cản chiến tranh phát xít.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B04_02', '68ea07ba-94c0-4e5d-a997-d0b9272ea818', 'LS9_KNTT_B04', 'Trước âm mưu và hành động của phe phát xít, nước nào đã ban hành đạo luật trung lập?',
    'Liên Xô.', 'Pháp.', 'Anh.', 'Mỹ.',
    4, 20, 'WARM_UP', 'EASY', 'Đáp án đúng là D: Mỹ.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B04_03', '68ea07ba-94c0-4e5d-a997-d0b9272ea818', 'LS9_KNTT_B04', 'Nội dung nào sau đây không phản ánh đúng về hậu quả của Chiến tranh thế giới thứ hai (1939 -1945)',
    'Chiến tranh đã lôi cuốn hơn 76 quốc gia tham gia vào vòng chiến.', 'Phá hủy hàng triệu làng mạc, thành phố, nhà máy, xí nghiệp.', 'Các nước thắng trận không bị thiệt hại và giành được nhiều lợi nhuận.', 'Liên Xô là quốc gia chịu nhiều tổn thất về người nhất trong chiến tranh.',
    3, 20, 'WARM_UP', 'EASY', 'Đáp án đúng là C: Các nước thắng trận không bị thiệt hại và giành được nhiều lợi nhuận.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B04_04', '68ea07ba-94c0-4e5d-a997-d0b9272ea818', 'LS9_KNTT_B04', 'Tháng 8 năm 1945, Nhật tuyên bố đầu hàng quân Đồng minh vô điều kiện vì',
    'Nhật muốn bảo tồn những thành quả của quá trình phát triển đất nước.', 'Ở Nhật diễn ra cuộc cách mạng, lật đổ sự thống trị của Nhật hoàng.', 'Những thiệt hại nặng nề của quân Nhật ở trên chiến trường.', 'Quân đội Nhật trên các chiến trường đã bị đánh bại hoàn toàn.',
    3, 20, 'WARM_UP', 'EASY', 'Đáp án đúng là C: Những thiệt hại nặng nề của quân Nhật ở trên chiến trường.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B04_06', '68ea07ba-94c0-4e5d-a997-d0b9272ea818', 'LS9_KNTT_B04', 'Các cường quốc tư bản dân chủ và Liên Xô không thể ngăn chặn được cuộc chiến tranh phát xít vì',
    'chưa có sự đoàn kết thống nhất ngay từ đầu cuộc chiến.', 'chưa có một trật thế giới để điều phối quan hệ quốc tế.', 'các nước quá tự tin vào sức mạnh quân sự của mỗi nước.', 'sức mạnh áp đảo hoàn toàn của Đức và đồng minh.',
    1, 20, 'WARM_UP', 'EASY', 'Đáp án đúng là A: chưa có sự đoàn kết thống nhất ngay từ đầu cuộc chiến.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B04_07', '68ea07ba-94c0-4e5d-a997-d0b9272ea818', 'LS9_KNTT_B04', 'Chiến tranh thế giới thứ hai (1939-1945) đã không có tác động nào đến tình hình thế giới?',
    'Dẫn tới sự ra đời của các nước xã hội chủ nghĩa trên thế giới.', 'Ảnh hưởng tích cực đến phong trào giải phóng dân tộc trên thế giới.', 'Dẫn tới những mâu thuẫn của các nước thắng trận về vấn đề thuộc địa.', 'Làm thay đổi tương quan lực lượng giữa các nước tư bản chủ nghĩa.',
    3, 20, 'WARM_UP', 'EASY', 'Đáp án đúng là C: Dẫn tới những mâu thuẫn của các nước thắng trận về vấn đề thuộc địa.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B04_09', '68ea07ba-94c0-4e5d-a997-d0b9272ea818', 'LS9_KNTT_B04', 'Nguyên nhân sâu xa dẫn tới sự bùng nổ của các cuộc chiến tranh thế giới trong thế kỉ XX là do',
    'sự ra đời của Liên Xô và các nước xã hội chủ nghĩa.', 'sự mâu thuẫn giữa các nước đế quốc về vấn đề thuộc địa.', 'sự dung dưỡng, thỏa hiệp của các nước tư bản châu Âu.', 'sự bùng nổ mạnh mẽ của phong trào cách mạng thế giới.',
    2, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là B: sự mâu thuẫn giữa các nước đế quốc về vấn đề thuộc địa.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B04_10', '68ea07ba-94c0-4e5d-a997-d0b9272ea818', 'LS9_KNTT_B04', 'Sự kiện quân đội Nhật tấn công hạm đội Thái Bình Dương của Mỹ tại Trân Châu Cảng ngày 7/12/1941 có tác động nào sau đây?',
    'Chấm dứt mối quan hệ đồng minh giữa Mỹ và Nhật.', 'Mỹ buộc phải tham gia vào cuộc chiến tranh.', 'Làm suy giảm nghiêm trọng sức mạnh của quân Mỹ.', 'Bảo vệ hệ thống thuộc địa của Nhật ở châu Á.',
    2, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là B: Mỹ buộc phải tham gia vào cuộc chiến tranh.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B04_11', '68ea07ba-94c0-4e5d-a997-d0b9272ea818', 'LS9_KNTT_B04', 'Nguyên nhân sâu sa nào sau đây dẫn đến sự bùng nổ của Chiến tranh thế giới thứ hai?',
    'Chính sách dung dưỡng, thoả hiệp của các cường quốc phương Tây.', 'Sự hình thành các lò lửa chiến tranh của chủ nghĩa phát xít.', 'Mâu thuẫn giữa các nước về thị trường và thuộc địa.', 'Các nước Anh, Pháp, Mỹ bao vây, tiêu diệt Liên Xô.',
    3, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là C: Mâu thuẫn giữa các nước về thị trường và thuộc địa.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B04_12', '68ea07ba-94c0-4e5d-a997-d0b9272ea818', 'LS9_KNTT_B04', 'Sự kiện nào sau đây thúc đẩy mâu thuẫn giữa các nước đế quốc trở nên sâu sắc?',
    'Nhật Bản xâm lược Trung Quốc (1931).', 'Hít-le trở thành Thủ tướng Đức (1933).', 'Liên Xô hoàn thành công cuộc công nghiệp hóa (1937).', 'Cuộc đại suy thoái kinh tế bùng nổ và kéo dài (1929 -1933).',
    4, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là D: Cuộc đại suy thoái kinh tế bùng nổ và kéo dài (1929 -1933).'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B04_13', '68ea07ba-94c0-4e5d-a997-d0b9272ea818', 'LS9_KNTT_B04', 'Sự kiện châm ngòi cho sự bùng nổ của cuộc Chiến tranh thế giới thứ hai là',
    'cuộc đại suy thoái kinh tế (1929 - 1933).', 'Đức tấn công Ba Lan (1-9-1939).', 'Nhật tấn công Mỹ (7-12-1941).', 'chiến dịch Xta-lin-grát (11-1942).',
    2, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là B: Đức tấn công Ba Lan (1-9-1939).'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B04_15', '68ea07ba-94c0-4e5d-a997-d0b9272ea818', 'LS9_KNTT_B04', 'Quốc gia nào trong phe Đồng minh giữ vai trò đi đầu trong chiến thắng chủ nghĩa phát xít?',
    'Trung Quốc. Anh', 'Hà Lan. Pháp', 'Tây Ban Nha. Mĩ', 'Liên Xô.',
    4, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là D: Liên Xô.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B05_01', '91b07302-3263-40a3-9d04-1c0148f51ff1', 'LS9_KNTT_B05', 'Ngoài mục tiêu kinh tế, cuộc bãi công của công nhân Ba Son còn nhằm mục đích nào sau đây?',
    'Thực hiện khẩu hiệu đấu tranh “Nhà máy về tay thợ thuyền”.', 'Ngăn cản tàu chiến Pháp sang đàn áp cách mạng Trung Quốc.', 'Đấu tranh chống Pháp và phong kiến để giành độc lập dân tộc.', 'Phá bỏ những giao kèo đã ký kết trước đó với chủ xưởng..',
    2, 20, 'WARM_UP', 'EASY', 'Đáp án đúng là B: Ngăn cản tàu chiến Pháp sang đàn áp cách mạng Trung Quốc.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B05_02', '91b07302-3263-40a3-9d04-1c0148f51ff1', 'LS9_KNTT_B05', 'Nội dung nào sau đây không phản ánh mục tiêu đấu tranh của giai cấp tư sản Việt Nam sau Chiến tranh thế giới thứ nhất?',
    'chống lại sự canh tranh, chèn ép của tư sản Pháp và tư sản Hoa kiều.', 'đòi được tham gia vào bộ máy chính quyền, đòi quyền lợi về kinh tế.', 'tố cáo tội ác của chế độ quân chủ, đòi các quyền độc lập, tự do, dân chủ.', 'yêu cầu chính quyền thuộc địa trao cho một số quyền tự do, dân chủ.',
    3, 20, 'WARM_UP', 'EASY', 'Đáp án đúng là C: tố cáo tội ác của chế độ quân chủ, đòi các quyền độc lập, tự do, dân chủ.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B05_03', '91b07302-3263-40a3-9d04-1c0148f51ff1', 'LS9_KNTT_B05', 'Cuộc khởi nghĩa Yên Bái (1930) thất bại là do nguyên nhân khách quan nào?',
    'Khởi nghĩa nổ ra hoàn toàn bị động.', 'Đường lối đấu tranh không rõ ràng.', 'Tổ chức Việt Nam Quốc dân đảng còn non yếu.', 'Thực dân Pháp còn mạnh, đủ sức đàn áp.',
    4, 20, 'WARM_UP', 'EASY', 'Đáp án đúng là D: Thực dân Pháp còn mạnh, đủ sức đàn áp.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B05_04', '91b07302-3263-40a3-9d04-1c0148f51ff1', 'LS9_KNTT_B05', 'Cuộc bãi công Ba Son năm 1925 có điểm khác biệt chủ yếu so với phong trào công nhân trước đó về',
    'mục tiêu đấu tranh.', 'quy mô phong trào.', 'thành phần tham gia.', 'hình thức đấu tranh.',
    1, 20, 'WARM_UP', 'EASY', 'Đáp án đúng là A: mục tiêu đấu tranh.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B05_05', '91b07302-3263-40a3-9d04-1c0148f51ff1', 'LS9_KNTT_B05', 'Trong những năm 20 của thế kỷ XX, giai cấp công nhân Việt Nam không có hình thức đấu tranh nào sau đây?',
    'Bãi công.', 'Khởi nghĩa từng phần.', 'Phá bỏ giao kèo.', 'Bỏ trốn.',
    2, 20, 'WARM_UP', 'EASY', 'Đáp án đúng là B: Khởi nghĩa từng phần.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B05_07', '91b07302-3263-40a3-9d04-1c0148f51ff1', 'LS9_KNTT_B05', 'Sự chuyển biến về chất của phong trào công nhân Việt Nam trong những năm 1926 - 1927 đã chứng tỏ điều gì?',
    'Công nhân trở thành giai cấp lãnh đạo cách mạng Việt Nam.', 'Trình độ giác ngộ của công nhân được nâng lên rõ rệt.', 'Phong trào công nhân hoàn toàn chuyển sang đấu tranh tự giác.', 'Khuynh hướng vô sản thắng thế hoàn toàn ở Việt Nam.',
    2, 20, 'WARM_UP', 'EASY', 'Đáp án đúng là B: Trình độ giác ngộ của công nhân được nâng lên rõ rệt.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B05_08', '91b07302-3263-40a3-9d04-1c0148f51ff1', 'LS9_KNTT_B05', 'Cộng sản đoàn là nòng cốt cho sự ra đời của tổ chức cách mạng nào ở sau đây?',
    'Tân Việt Cách mạng đảng.', 'Hội Việt Nam Cách mạng Thanh niên.', 'Đông Dương Cộng sản đảng.', 'Việt Nam Quốc dân đảng.',
    2, 20, 'WARM_UP', 'EASY', 'Đáp án đúng là B: Hội Việt Nam Cách mạng Thanh niên.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B05_09', '91b07302-3263-40a3-9d04-1c0148f51ff1', 'LS9_KNTT_B05', 'Cơ sở hạt nhân đầu tiên của Việt Nam Quốc dân đảng là tổ chức nào sau đây?',
    'Cộng sản đoàn.', 'Nam đồng thư xã.', 'Tâm tâm xã.', 'Việt Nam nghĩa đoàn.',
    2, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là B: Nam đồng thư xã.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B05_11', '91b07302-3263-40a3-9d04-1c0148f51ff1', 'LS9_KNTT_B05', 'Phong trào đấu tranh của công nhân Việt Nam trong giai đoạn 1926 - 1929 có điểm gì khác so với giai đoạn 1919 - 1925?',
    'Bãi công với khẩu hiệu đấu tranh chính “tăng lương giảm giờ làm”.', 'Mang tính chất chính trị rõ rệt, có sự liên kết thành các phong trào chung.', 'Diễn ra quyết liệt đòi các mục tiêu về kinh tế, mang tính tự phát.', 'Phong trào đã giành được mục tiêu chiến lược cho cách mạng Việt Nam.',
    2, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là B: Mang tính chất chính trị rõ rệt, có sự liên kết thành các phong trào chung.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B05_12', '91b07302-3263-40a3-9d04-1c0148f51ff1', 'LS9_KNTT_B05', 'Một trong những hoạt động tiêu biểu của tầng lớp tiểu tư sản Việt Nam giai đoạn 1919-1925 là',
    'Mít tinh kỷ niệm ngày Quốc tế Lao động.', 'đòi nhà cầm quyền thả Nguyễn An Ninh.', 'chống độc quyền kinh doanh cảng Sài Gòn.', 'ám sát trùm mộ phu Badanh ở Hà Nội.',
    2, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là B: đòi nhà cầm quyền thả Nguyễn An Ninh.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B05_14', '91b07302-3263-40a3-9d04-1c0148f51ff1', 'LS9_KNTT_B05', 'Nội dung nào phản ánh mục tiêu đấu tranh trong phong trào dân tộc dân chủ ở Việt Nam những năm 1919 - 1925?',
    'Chống bọn tư bản Pháp nắm độc qưyền xuất cảng lúa gạo.', 'Đấu tranh chống Pháp, giành độc lập hoàn toàn cho dân tộc.', 'Chống phong kiến, giành quyền tự do dân chủ.', 'Đòi một số quyền lợi về kinh tế và các quyền tự do dân chủ.',
    4, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là D: Đòi một số quyền lợi về kinh tế và các quyền tự do dân chủ.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B05_15', '91b07302-3263-40a3-9d04-1c0148f51ff1', 'LS9_KNTT_B05', 'Năm 1919, Phan Châu Trinh và một số người Việt Nam yêu nước tại Pháp đã sáng lập tổ chức nào sau đây?',
    'Hội liên hiệp các dân tộc thuộc địa.', 'Hội liên hiệp các dân tộc bị áp bức Á Đông.', 'Hội những người Việt Nam yêu nước.', 'Hội Việt Nam Cách mạng Thanh niên.',
    3, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là C: Hội những người Việt Nam yêu nước.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B05_16', '91b07302-3263-40a3-9d04-1c0148f51ff1', 'LS9_KNTT_B05', 'Trong thời gian hoạt động ở Pháp, Phan Châu Trinh đã viết nhiều tác phẩm nhằm mục tiêu chủ yếu nào sau đây?',
    'Truyền bá chủ nghĩa Mác Lê-nin về nước.', 'Lên án chế độ quân chủ ở trong nước.', 'Hình thành khuynh hướng cứu nước mới.', 'Cổ vũ phong trào chống thuế ở Trung Kì.',
    2, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là B: Lên án chế độ quân chủ ở trong nước.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B05_18', '91b07302-3263-40a3-9d04-1c0148f51ff1', 'LS9_KNTT_B05', 'Nội dung nào phản ánh đặc điểm của phong trào dân tộc dân chủ ở Việt Nam (1918-1929)?',
    'Phong trào diễn ra sôi nổi nhưng vẫn chưa thành công.', 'Có sự chuyển biến từ lập trường vô sản sang tư sản.', 'Có sự mâu thuẫn giữa các khuynh hướng cách mạng.', 'Đáp ứng được yêu cầu khách quan của lịch sử Việt Nam.',
    1, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là A: Phong trào diễn ra sôi nổi nhưng vẫn chưa thành công.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B05_19', '91b07302-3263-40a3-9d04-1c0148f51ff1', 'LS9_KNTT_B05', 'Hoạt động tiêu biểu nhất của Hội Việt Nam Cách mạng Thanh niên nhằm phát triển cơ sở của Hội là',
    'mở lớp huấn luyện chính trị ở Quảng Châu.', 'ra báo Thanh niên làm cơ quan ngôn luận.', 'xuất bản tác phẩm Đường Kách mệnh.', 'phong trào “Vô sản hóa”.',
    4, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là D: phong trào “Vô sản hóa”.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B05_20', '91b07302-3263-40a3-9d04-1c0148f51ff1', 'LS9_KNTT_B05', 'Nguyên nhân chủ quan dẫn tới thất bại của cuộc khởi nghĩa Yên Bái là',
    'khởi nghĩa nổ ra chậm so với yêu cầu.', 'sự lỗi thời của tư tưởng dân chủ tư sản.', 'khởi nghĩa nổ ra trong thế bị động.', 'thực dân Pháp còn mạnh, tăng cường đàn áp.',
    3, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là C: khởi nghĩa nổ ra trong thế bị động.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B05_22', '91b07302-3263-40a3-9d04-1c0148f51ff1', 'LS9_KNTT_B05', 'Việt Nam Quốc dân đảng chủ trương đấu tranh chống Pháp bằng phương pháp chủ yếu nào sau đây?',
    'Tiến hành khởi nghĩa từng phần.', 'Cổ động bãi công đánh đuổi giặc Pháp.', 'Chống Pháp bằng biện pháp ôn hòa.', 'Tiến hành bạo lực cách mạng.',
    4, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là D: Tiến hành bạo lực cách mạng.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B05_23', '91b07302-3263-40a3-9d04-1c0148f51ff1', 'LS9_KNTT_B05', 'Hội Việt Nam Cách mạng Thanh niên và Việt Nam Quốc dân đảng có điểm tương đồng nào sau đây?',
    'Chú trọng gây dựng cơ sở cách mạng trong công nhân.', 'Mục tiêu đánh đổ Pháp, thiết lập nền quân chủ lập hiến.', 'Có sự phân hoá mạnh mẽ thành các tổ chức cộng sản.', 'Thể hiện tinh thần yêu nước, đấu tranh giải phóng dân tộc.',
    4, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là D: Thể hiện tinh thần yêu nước, đấu tranh giải phóng dân tộc.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B05_24', '91b07302-3263-40a3-9d04-1c0148f51ff1', 'LS9_KNTT_B05', 'Trong quá trình đấu tranh, giai cấp tư sản đã lập một số tờ báo nhằm mục đích chủ yếu nào sau đây?',
    'Làm công cụ tuyên truyền và đòi quyền lợi cho mình.', 'Truyền bá khuynh hướng cách mạng tư sản và vô sản.', 'Buộc Pháp phải trao trả các quyền dân tộc cơ bản.', 'Lên án chế độ quân chủ và giai cấp địa chủ phong kiến.',
    1, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là A: Làm công cụ tuyên truyền và đòi quyền lợi cho mình.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B05_25', '91b07302-3263-40a3-9d04-1c0148f51ff1', 'LS9_KNTT_B05', 'Lực lượng tham gia vào tổ chức Việt Nam Quốc dân đảng là',
    'thân hào, thân sĩ ở nông thôn.', 'công nhân đồn điền cao su.', 'Việt kiều ở châu Âu và châu Á.', 'tầng lớp quý tộc tư sản hóa.',
    1, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là A: thân hào, thân sĩ ở nông thôn.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B05_27', '91b07302-3263-40a3-9d04-1c0148f51ff1', 'LS9_KNTT_B05', 'Sau Chiến tranh thế giới thứ nhất, phong trào dân tộc dân chủ ở Việt Nam có đặc điểm nổi bật nào sau đây?',
    'Thu hút nhiều giai tầng lớp tham gia, hình thức phong phú và sôi nổi.', 'Xây dựng được khuynh hướng cứu nước khác biệt với thế giới.', 'Các khuynh hướng cách mạng mâu thuẫn và đối lập nhau.', 'Bị thực dân Pháp đàn áp, khủng bố trắng nên tạm thời lắng xuống.',
    1, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là A: Thu hút nhiều giai tầng lớp tham gia, hình thức phong phú và sôi nổi.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B05_28', '91b07302-3263-40a3-9d04-1c0148f51ff1', 'LS9_KNTT_B05', 'Tân Việt Cách mạng Đảng có hoạt động chính nào sau đây ?',
    'Thường xuyên tổ chức ám sát cá nhân.', 'Phát triển mạnh hoạt động ở hải ngoại.', 'Giới thiệu các sách báo yêu nước tiến bộ.', 'Tổ chức cuộc đấu tranh nghị trường.',
    3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: Giới thiệu các sách báo yêu nước tiến bộ.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B05_29', '91b07302-3263-40a3-9d04-1c0148f51ff1', 'LS9_KNTT_B05', 'Cuộc đấu tranh của giai cấp tư sản Việt Nam sau Chiến tranh thế giới thứ nhất mang tính chất nào sau đây?',
    'Triệt để.', 'Bạo lực.', 'Cải lương.', 'Tự giác.',
    3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: Cải lương.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B05_31', '91b07302-3263-40a3-9d04-1c0148f51ff1', 'LS9_KNTT_B05', 'Nội dung nào sau đây không phải là hoạt động chủ yếu của Hội Việt Nam Cách mạng Thanh niên?',
    'Ra báo Thanh niên, cử hội viên đi học ở Trung Quốc và Liên Xô.', 'Cử cán bộ học tập kinh nghiệm của Tân Việt Cách mạng đảng.', 'Thực hiện chủ trương “Vô sản hóa”, truyền bá lí luận giải phóng dân tộc.', 'Huấn luyện chính trị, đào tạo cán bộ, xây dựng cơ sở của Hội.',
    2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: Cử cán bộ học tập kinh nghiệm của Tân Việt Cách mạng đảng.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
