);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B05_33', '91b07302-3263-40a3-9d04-1c0148f51ff1', 'LS9_KNTT_B05', 'Tổ chức Tâm tâm xã (1923) ra đời và hoạt động nhằm mục tiêu chủ yếu nào sau đây?',
    'Đưa đất nước phát triển theo con đường tư bản chủ nghĩa.', 'Khôi phục quyền làm người của người Việt Nam.', 'Thành lập liên minh quốc tế để đấu tranh chống Pháp.', 'Nhờ sự giúp đỡ của Trung Quốc để đánh đuổi Pháp.',
    2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: Khôi phục quyền làm người của người Việt Nam.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
