);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B05_35', '91b07302-3263-40a3-9d04-1c0148f51ff1', 'LS9_KNTT_B05', 'Nội dung nào sau đây phản ánh đúng về quy mô phong trào đấu tranh của giai cấp công nhân giai đoạn (1928 - 1929)?',
    'Diễn ra khắp cả nước, thúc đẩy phong trào của giai cấp tư sản phát triển.', 'Diễn ra trên phạm vi cả nước nhưng sôi nổi và mạnh mẽ nhất ở Trung Kì.', 'Ngày càng được mở rộng và dần có sự liên kết thành phong trào chung.', 'Diễn ra trong phạm vi nhỏ hẹp nhưng sôi nổi, có nhiều thành phần tham gia.',
    3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: Ngày càng được mở rộng và dần có sự liên kết thành phong trào chung.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
