) VALUES (
    'Q_LS9_B05_36', '91b07302-3263-40a3-9d04-1c0148f51ff1', 'LS9_KNTT_B05', 'Năm 1929, tổ chức Việt Nam Quốc dân đảng có hoạt động tiêu biểu nào sau đây?',
    'Ám sát toàn quyền Đông Dương Méc-lanh.', 'Khởi nghĩa Yên Bái.', 'Ám sát trùm mộ phu Ba-danh.', 'Đấu tranh đòi thả Nguyễn An Ninh.',
    3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: Ám sát trùm mộ phu Ba-danh.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B05_37', '91b07302-3263-40a3-9d04-1c0148f51ff1', 'LS9_KNTT_B05', 'Các tổ chức yêu nước cách mạng ở Việt Nam ra đời trong bối cảnh nào sau đây?',
    'Các tổ chức cộng sản lần lượt ra đời.', 'Phong trào công nhân mang tính tự giác.', 'Sự tăng cường đàn áp của thực dân Pháp.', 'Nền kinh tế thế giới lâm vào khủng hoảng.',
    3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: Sự tăng cường đàn áp của thực dân Pháp.'
);
