    'Q_LS9_B05_38', '91b07302-3263-40a3-9d04-1c0148f51ff1', 'LS9_KNTT_B05', 'Hoạt động yêu nước của người Việt Nam ở nước ngoài trong những năm 20 của thế kỷ XX diễn ra chủ yếu ở nước nào sau đây?',
    'Anh và Hà Lan.', 'Trung Quốc và Ấn Độ.', 'Trung Quốc và Pháp.', 'Liên Xô và Angiêri.',
    3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: Trung Quốc và Pháp.'
);
INSERT INTO lesson_question (
