    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B05_39', '91b07302-3263-40a3-9d04-1c0148f51ff1', 'LS9_KNTT_B05', 'Cuộc đấu tranh của công nhân thợ máy xưởng Ba Son (Sài Gòn) tháng 8/1925 đã chứng tỏ điều gì?',
    'Giai cấp công nhân đã trưởng thành, đủ sức lãnh đạo cách mạng.', 'Phong trào công nhân chủ yếu hướng tới mục tiêu kinh tế.', 'Phong trào công nhân còn mang tính tự phát, quy mô nhỏ.', 'Phong trào công nhân bước đầu đi vào đấu tranh tự giác.',
    4, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là D: Phong trào công nhân bước đầu đi vào đấu tranh tự giác.'
);
INSERT INTO lesson_question (
