INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B06_14', '09a6b158-79a1-4b81-828f-c5764872ecbd', 'LS9_KNTT_B06', 'Nội dung nào sau đây không phản ánh vai trò của Nguyễn Ái Quốc đối với lịch sử dân tộc trong 30 năm đầu thế kỉ XX?',
    'Xác định con đường cách mạng giải phóng dân tộc đúng đắn, sáng tạo.', 'Chuẩn bị những điều kiện quan trọng cho sự ra đời của Đảng Cộng sản.', 'Hợp nhất các tổ chức cộng sản thành Đảng Cộng sản Việt Nam.', 'Trực tiếp chuẩn bị những điều kiện cho thắng lợi của Cách mạng tháng Tám.',
    4, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là D: Trực tiếp chuẩn bị những điều kiện cho thắng lợi của Cách mạng tháng Tám.'
