    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B07_58', 'e0c61f8a-84db-488b-8368-e8c2ab952f58', 'LS9_KNTT_B07', 'Thực dân Pháp đã thực hiện chính sách nào sau đây ở Việt Nam những năm 1929 – 1931 là gì?',
    '“Dùng người Việt đánh người Việt”.', 'Tăng cường dàn áp, “khủng bố trắng”.', '“Lấy chiến tranh nuôi chiến tranh”.', 'Ban hành một số chính sách tích cực.',
    2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: Tăng cường dàn áp, “khủng bố trắng”.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B07_59', 'e0c61f8a-84db-488b-8368-e8c2ab952f58', 'LS9_KNTT_B07', 'Cuộc mít tinh lớn của 2,5 vạn người tại Khu Đấu Xảo - Hà Nội năm 1938 diễn ra nhân dịp',
    'Kỉ niệm Xô viết Nghệ - Tĩnh (12/9/1938).', 'Kỉ niệm ngày Quốc tế Lao động (1/5/1938).', 'Kỉ niệm ngày thành lập Đảng (3/2/1938).', 'Kỉ niệm Cách mạng tháng Mười Nga (25/10/1938).',
    2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: Kỉ niệm ngày Quốc tế Lao động (1/5/1938).'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B07_60', 'e0c61f8a-84db-488b-8368-e8c2ab952f58', 'LS9_KNTT_B07', 'Phong trào cách mạng 1930 - 1931 ở Việt Nam phát triển tới đỉnh cao với sự ra đời của',
    'khối liên minh công - nông.', 'Xô viết Nghệ - Tĩnh.', 'Đảng Cộng sản Đông Dương.', 'Hội phản đế đồng minh.',
    2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: Xô viết Nghệ - Tĩnh.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B07_61', 'e0c61f8a-84db-488b-8368-e8c2ab952f58', 'LS9_KNTT_B07', 'Đại hội lần thứ VII của Quốc tế Cộng sản họp ở Mát-xcơ-va (7/1935) chủ trương thành lập ở mỗi nước một',
    'Quốc hội mới.', 'chính đảng mới.', 'Chính phủ mới.', 'Mặt trận nhân dân.',
    4, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là D: Mặt trận nhân dân.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B07_62', 'e0c61f8a-84db-488b-8368-e8c2ab952f58', 'LS9_KNTT_B07', 'Sự ra đời của các Xô viết ở Nghệ An và Hà Tĩnh là đỉnh cao của phong trào cách mạng 1930 - 1931 vì',
    'đã sử dụng hình thức đấu tranh đa dạng, phong phú, quyết liệt.', 'đã khẳng định trên thực tế vai trò lãnh đạo của Đảng Cộng sản.', 'đây là hình thức chính quyền nhà nước giống các Xô viết ở nước Nga.', 'đã giải quyết được vấn đề cơ bản của một cuộc cách mạng xã hội.',
    4, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là D: đã giải quyết được vấn đề cơ bản của một cuộc cách mạng xã hội.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B08_01', '6e0f8c53-9919-4099-81ab-7f7d5645a37b', 'LS9_KNTT_B08', 'Ngày 22/12/1944, tại Cao Bằng, lực lượng vũ trang nào sau đây đã được thành lập?',
    'Đội du kích Ba Tơ.', 'Việt Nam Giải phóng quân.', 'Việt Nam Tuyên truyền Giải phóng quân.', 'Cứu quốc quân.',
    3, 20, 'WARM_UP', 'EASY', 'Đáp án đúng là C: Việt Nam Tuyên truyền Giải phóng quân.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B08_03', '6e0f8c53-9919-4099-81ab-7f7d5645a37b', 'LS9_KNTT_B08', 'Cách mạng tháng Tám 1945 ở Việt Nam đã góp phần vào chiến thắng chống chủ nghĩa phát xít trên thế giới vì đã',
    'phối hợp với quân Đồng minh giải giáp quân đội Nhật.', 'giúp nhân dân Lào và Cam-pu-chia lật đổ quân phiệt Nhật.', 'tiêu diệt được quân phiệt Nhật ở châu Á - Thái Bình Dương.', 'lật đổ nền thống trị của quân phiệt Nhật ở Việt Nam.',
    4, 20, 'WARM_UP', 'EASY', 'Đáp án đúng là D: lật đổ nền thống trị của quân phiệt Nhật ở Việt Nam.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B08_06', '6e0f8c53-9919-4099-81ab-7f7d5645a37b', 'LS9_KNTT_B08', 'Các tổ chức quần chúng của Mặt trận Việt Minh tồn tại dưới tên gọi',
    'Hội Cứu quốc.', 'Hội Dân chủ.', 'Hội Đồng minh.', 'Hội Phản đế.',
    1, 20, 'WARM_UP', 'EASY', 'Đáp án đúng là A: Hội Cứu quốc.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B08_07', '6e0f8c53-9919-4099-81ab-7f7d5645a37b', 'LS9_KNTT_B08', 'Thắng lợi của Cách mạng tháng Tám năm 1945 ở Việt Nam có ý nghĩa quốc tế nổi bật nào sau đây?',
    'Làm sụp đổ hệ thống thuộc địa của chủ nghĩa thực dân.', 'Góp phần làm chấm dứt sự tồn tại của chủ nghĩa tư bản.', 'Làm chủ nghĩa xã hội trở thành hệ thống thế giới.', 'Góp phần làm suy yếu chủ nghĩa thực dân.',
    4, 20, 'WARM_UP', 'EASY', 'Đáp án đúng là D: Góp phần làm suy yếu chủ nghĩa thực dân.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B08_08', '6e0f8c53-9919-4099-81ab-7f7d5645a37b', 'LS9_KNTT_B08', 'Căn cứ địa lớn nhất chuẩn bị cho Tổng khởi nghĩa tháng Tám năm 1945 ở Việt Nam là',
    'Pác Pó (Cao Bằng).', 'Bắc Sơn - Võ Nhai.', 'Khu Giải phóng Việt Bắc.', 'Ba Tơ (Quảng Ngãi).',
    3, 20, 'WARM_UP', 'EASY', 'Đáp án đúng là C: Khu Giải phóng Việt Bắc.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B08_09', '6e0f8c53-9919-4099-81ab-7f7d5645a37b', 'LS9_KNTT_B08', 'Ngày 9/3/1945, ở Đông Dương diễn ra sự kiện nào tạo thuận lợi cho cách mạng Việt Nam?',
    'Quân Nhật đảo chính lật đổ Pháp.', 'Quân Đồng minh tiến vào Đông Dương.', 'Quân Nhật đầu hàng quân Đồng minh.', 'Quân Nhật xâm lược Đông Dương.',
    1, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là A: Quân Nhật đảo chính lật đổ Pháp.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B08_10', '6e0f8c53-9919-4099-81ab-7f7d5645a37b', 'LS9_KNTT_B08', 'Địa phương cuối cùng giành được chính quyền trong Tổng khởi nghĩa tháng Tám năm 1945 là',
    'Hải Dương, Bắc Giang.', 'Kiên Giang, Đồng Nai.', 'Hà Tiên, Đồng Nai Thượng.', 'Hà Tiên, Đồng Tháp.',
    3, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là C: Hà Tiên, Đồng Nai Thượng.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B08_14', '6e0f8c53-9919-4099-81ab-7f7d5645a37b', 'LS9_KNTT_B08', 'Khi Chiến tranh thế giới thứ hai bùng nổ, thực Pháp ở Đông Dương đứng trước nguy cơ nào?',
    'Quân phiệt Nhật chuẩn bị tấn công Đông Dương.', 'Nhân dân Pháp phản đối chiến tranh thế giới.', 'Phát xít Đức chuẩn bị tấn công xâm lược Pháp.', 'Phát xít sẽ lên nắm chính quyền ở Pháp.',
    4, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là D: Phát xít sẽ lên nắm chính quyền ở Pháp.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B08_16', '6e0f8c53-9919-4099-81ab-7f7d5645a37b', 'LS9_KNTT_B08', 'Hội nghị Trung ương 8 của Đảng (5/1941) khẳng định phương thức kết thúc của cách mạng Việt Nam phải là',
    'một cuộc tổng tiến công và nổi dậy.', 'cuộc tiến công của lực lượng vũ trang.', 'cuộc đấu tranh hoà bình, không đổ máu.', 'một cuộc khởi nghĩa vũ trang.',
    4, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là D: một cuộc khởi nghĩa vũ trang.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B08_17', '6e0f8c53-9919-4099-81ab-7f7d5645a37b', 'LS9_KNTT_B08', 'Nhận định nào là đúng về lực lượng vũ trang trong Cách mạng tháng Tám năm 1945?',
    'Hạn chế về số lượng và vũ khí nhưng hoạt động tích cực.', 'Là lực lượng xung phong, lãnh đạo lực lượng chính trị.', 'Không ngừng lớn mạnh về binh lực, hỏa lực và vũ khí.', 'Giữ vai trò quyết định đến thắng lợi của cách mạng.',
    1, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là A: Hạn chế về số lượng và vũ khí nhưng hoạt động tích cực.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B08_18', '6e0f8c53-9919-4099-81ab-7f7d5645a37b', 'LS9_KNTT_B08', 'Tháng 5 năm 1945, các lực lượng vũ trang trong cả nước thống nhất thành',
    'Quân đội nhân dân Việt Nam.', 'Việt Nam Giải phóng quân.', 'Việt Nam Tuyên truyền Giải phóng quân.', 'Vệ quốc đoàn.',
    3, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là C: Việt Nam Tuyên truyền Giải phóng quân.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B08_19', '6e0f8c53-9919-4099-81ab-7f7d5645a37b', 'LS9_KNTT_B08', 'Nội dung nào phản ánh vai trò của lực lượng vũ trang trong Tổng khởi nghĩa tháng Tám năm 1945?',
    'Lực lượng đông đảo nhất tham gia giành chính quyền.', 'Quyết định trong việc giành chính quyền ở đô thị.', 'Giữ vai trò quan trọng nhất, quyết định thắng lợi.', 'Là lực lượng xung kích, hỗ trợ quần chúng khởi nghĩa.',
    4, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là D: Là lực lượng xung kích, hỗ trợ quần chúng khởi nghĩa.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B08_20', '6e0f8c53-9919-4099-81ab-7f7d5645a37b', 'LS9_KNTT_B08', 'Khi Chiến tranh thế giới thứ hai bùng nổ, thực dân Pháp đã thực hiện chính sách nào ở Việt Nam?',
    'Kinh tế thời chiến.', 'Kinh tế mới.', 'Cộng sản thời chiến.', 'Kinh tế chỉ huy.',
    4, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là D: Kinh tế chỉ huy.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B08_21', '6e0f8c53-9919-4099-81ab-7f7d5645a37b', 'LS9_KNTT_B08', 'Để chuẩn bị cho sự thành lập nước Việt Nam mới, Hồ Chí Minh đã đề nghị cải tổ Ủy ban Dân tộc giải phóng Việt Nam thành',
    'Chính phủ Liên hiệp kháng chiến Việt Nam.', 'Chính phủ Cộng hòa xã hội chủ nghĩa Việt Nam.', 'Chính phủ lâm thời nước Việt Nam Dân chủ Cộng hòa.', 'Chính phủ nước Việt Nam Dân chủ Cộng hòa.',
    3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: Chính phủ lâm thời nước Việt Nam Dân chủ Cộng hòa.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B08_22', '6e0f8c53-9919-4099-81ab-7f7d5645a37b', 'LS9_KNTT_B08', 'Ủy ban Quân sự cách mạng Bắc Kì được thành lập năm 1945 với nhiệm vụ trọng tâm nào sau đây?',
    'Tập hợp lực lượng quân sự cho Tổng khởi nghĩa tháng Tám.', 'Phát triển mạnh mẽ chiến tranh du kích ở vùng sau lưng địch.', 'Chỉ huy các chiến khu miền Bắc và giúp đỡ toàn quốc về quân sự.', 'Lãnh đạo cao trào kháng Nhật cứu nước ở Bắc Kì.',
    3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: Chỉ huy các chiến khu miền Bắc và giúp đỡ toàn quốc về quân sự.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B08_23', '6e0f8c53-9919-4099-81ab-7f7d5645a37b', 'LS9_KNTT_B08', 'Nạn đói nghiêm trọng ở Việt Nam cuối 1944 đầu 1945 xuất phát từ nguyên nhân chủ yếu nào sau đây?',
    'Nhân dân dùng gạo, ngô, khoai, sắn để nấu rượu.', 'Chính sách áp bức, bóc lột tàn bạo của Pháp - Nhật.', 'Thiên tai lũ lụt, hạn hán diễn ra gây mất mùa triền miền.', 'Nền nông nghiệp độc canh lúa ở Việt Nam đã bị xóa bỏ.',
    2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: Chính sách áp bức, bóc lột tàn bạo của Pháp - Nhật.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B08_24', '6e0f8c53-9919-4099-81ab-7f7d5645a37b', 'LS9_KNTT_B08', 'Sau khi Nhật đảo chính Pháp (3/1945), Ban Thường vụ Trung ương Đảng Cộng sản Đông Dương họp và ra chỉ thị nào sau đây?',
    'Đánh đuổi quân Nhật ra khỏi Đông Dương.', 'Phá kho thóc của Nhật để giải quyết nạn đói.', 'Đẩy mạnh cao trào kháng Nhật cứu nước.', 'Nhật - Pháp bắn nhau và hành động của chúng ta.',
    4, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là D: Nhật - Pháp bắn nhau và hành động của chúng ta.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B08_25', '6e0f8c53-9919-4099-81ab-7f7d5645a37b', 'LS9_KNTT_B08', 'Đầu năm 1945, khi Chiến tranh thế giới thứ hai bước vào giai đoạn kết thúc, thực dân Pháp ở Đông Dương có hành động nào?',
    'Tiếp tục câu kết với Nhật để áp bức bóc lột nhân dân Việt Nam.', 'Kí với Nhật Bản bản Hiệp định phòng thủ chung Đông Dương.', 'Quy thuận hoàn toàn quân Nhật, chấp nhận làm tay sai lâu dài.', 'Ráo riết chuẩn bị lực lượng để lật đổ Nhật, giành lại địa vị thống trị.',
    4, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là D: Ráo riết chuẩn bị lực lượng để lật đổ Nhật, giành lại địa vị thống trị.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B08_28', '6e0f8c53-9919-4099-81ab-7f7d5645a37b', 'LS9_KNTT_B08', 'Nội dung nào không phải là điều kiện bùng nổ cuộc Tổng khởi nghĩa tháng Tám năm 1945 ở Việt Nam?',
    'Đảng đã sẵn sàng lãnh đạo quần chúng khởi nghĩa giành chính quyền.', 'Quân phiệt Nhật đã đầu hàng quân Đồng minh không điều kiện.', 'Vua Bảo Đại - vị vua cuối cùng của triều Nguyên tuyên bố thoái vị.', 'Nhân dân được rèn luyện đã sẵn sàng đứng lên Tổng khởi nghĩa.',
    3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: Vua Bảo Đại - vị vua cuối cùng của triều Nguyên tuyên bố thoái vị.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B08_29', '6e0f8c53-9919-4099-81ab-7f7d5645a37b', 'LS9_KNTT_B08', 'Cách mạng tháng Tám năm 1945 ở Việt Nam nổ ra và giành được thắng lợi nhanh chóng, ít đổ máu là do',
    'lực lượng chính trị không ngừng trưởng thành.', 'điều kiện khách quan, chủ quan thuận lợi.', 'lực lượng vũ trang được xây dựng mạnh.', 'tinh thần yêu nước của nhân dân Việt Nam.',
    2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: điều kiện khách quan, chủ quan thuận lợi.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B08_30', '6e0f8c53-9919-4099-81ab-7f7d5645a37b', 'LS9_KNTT_B08', 'Nội dung nào sau đây không có trong bản chỉ thị “Nhật - Pháp bắn nhau và hành động của chúng ta”?',
    'Việt Nam cần tiến hành tổng khởi nghĩa để đánh đuổi quân phiệt Nhật.', 'Xác định quân phiệt Nhật trở thành kẻ thù chính của nhân dân Việt Nam.', 'Thay khẩu hiệu “Đánh đuổi phát xít Nhật” bằng “Đánh đuổi Pháp - Nhật”.', 'Nhận định cuộc đảo chính đã tạo nên sự khủng hoảng chính trị sâu sắc.',
    1, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là A: Việt Nam cần tiến hành tổng khởi nghĩa để đánh đuổi quân phiệt Nhật.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B08_31', '6e0f8c53-9919-4099-81ab-7f7d5645a37b', 'LS9_KNTT_B08', 'Khởi nghĩa giành chính quyền của nhân dân Việt Nam trong năm 1945 diễn ra theo hình thái nào?',
    'Giành chính quyền từng phần tiến lên giành chính quyền toàn quốc.', 'Giành chính quyền ở các vùng nông thôn rồi tiến vào thành thị.', 'Giành chính quyền đồng thời ở cả vùng nông thôn và thành thị.', 'Giành chính quyền ở các đô thị lớn rồi tỏa về các vùng nông thôn.',
    3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: Giành chính quyền đồng thời ở cả vùng nông thôn và thành thị.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B08_32', '6e0f8c53-9919-4099-81ab-7f7d5645a37b', 'LS9_KNTT_B08', 'Năm 1945, các lực lượng vũ trang thống nhất thành Việt Nam Giải phóng quân theo chỉ thị của',
    'Hội nghị Quân sự cách mạng Bắc Kì (4/1945).', 'Hội nghị Trung ương Đảng (14 - 15/8/1945).', 'Hội nghị Ban Thường vụ Trung ương Đảng (3/1945).', 'Đại hội Quốc dân Tân Trào (17/8/1945).',
    1, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là A: Hội nghị Quân sự cách mạng Bắc Kì (4/1945).'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B08_33', '6e0f8c53-9919-4099-81ab-7f7d5645a37b', 'LS9_KNTT_B08', 'Căn cứ địa trung ương được thành lập theo chỉ thị của Nguyễn Ái Quốc năm 1941 là',
    'Bắc Sơn (Lạng Sơn).', 'Định Hóa (Thái Nguyên).', 'Pác Pó (Cao Bằng).', 'Tân Trào (Tuyên Quang).',
    3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: Pác Pó (Cao Bằng).'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B08_34', '6e0f8c53-9919-4099-81ab-7f7d5645a37b', 'LS9_KNTT_B08', 'Tháng 5/1941, sự kiện nào sau đây đã khẳng định vai trò to lớn của Nguyễn Ái Quốc đối với cách mạng Việt Nam?',
    'Nguyễn Ái Quốc thành lập Mặt trận Việt Nam độc lập đồng minh.', 'Nguyễn Ái Quốc bắt đầu viết đường lối kháng chiến chống Pháp.', 'Nguyễn Ái Quốc bắt đầu về nước để trực tiếp chỉ đạo cách mạng.', 'Nguyễn Ái Quốc triệu tập và chủ trì Hội nghị Trung ương Đảng lần thứ 8.',
    4, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là D: Nguyễn Ái Quốc triệu tập và chủ trì Hội nghị Trung ương Đảng lần thứ 8.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B08_37', '6e0f8c53-9919-4099-81ab-7f7d5645a37b', 'LS9_KNTT_B08', 'Cao trào kháng Nhật cứu nước (3 - 8/1945) của nhân dân Việt Nam đã',
    'làm cho lực lượng cách mạng được tăng cường ở trong và ngoài nước.', 'tạo ra thời cơ để Tổng khởi nghĩa diễn ra nhanh chóng, ít đổ máu.', 'thúc đẩy sự sụp đổ nhanh chóng của chủ nghĩa phát xít trên thế giới.', 'tạo ra những điều kiện chủ quan cho một cuộc tổng khởi nghĩa.',
    4, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là D: tạo ra những điều kiện chủ quan cho một cuộc tổng khởi nghĩa.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B08_38', '6e0f8c53-9919-4099-81ab-7f7d5645a37b', 'LS9_KNTT_B08', 'Nhà nước được thành lập trong Cách mạng tháng Tám ở Việt Nam theo chính thể',
    'Quân chủ chuyên chế.', 'Dân chủ chủ nô.', 'Cộng hòa dân chủ.', 'Quân chủ lập hiến.',
    3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: Cộng hòa dân chủ.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B08_40', '6e0f8c53-9919-4099-81ab-7f7d5645a37b', 'LS9_KNTT_B08', 'Trong Cách mạng tháng Tám năm 1945, “Pháp chạy, Nhật hàng, vua Bảo Đại thoái vị” chứng tỏ',
    'cách mạng đã xóa bỏ những tàn dư của phong kiến.', 'những kẻ thù chính của cách mạng đã bị loại bỏ.', 'cách mạng mang tính dân tộc dân chủ điển hình.', 'nền độc lập của Việt Nam không còn bị đe dọa.',
    2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: những kẻ thù chính của cách mạng đã bị loại bỏ.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B08_41', '6e0f8c53-9919-4099-81ab-7f7d5645a37b', 'LS9_KNTT_B08', 'Lực lượng vũ trang nào giữ vai trò quan trọng đối với thắng lợi của Tổng khởi nghĩa tháng Tám năm 1945?',
    'Đội Việt Nam Tuyên truyền Giải phóng quân.', 'Việt Nam Giải phóng quân.', 'Cứu quốc quân.', 'Lực lượng tự vệ chiến đấu.',
    2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: Việt Nam Giải phóng quân.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B08_42', '6e0f8c53-9919-4099-81ab-7f7d5645a37b', 'LS9_KNTT_B08', 'Sự kiện lịch sử nào sau đây đã đánh dấu sự sụp đổ hoàn toàn của chế độ phong kiến ở Việt Nam?',
    'Vua Bảo Đại của triều Nguyễn tuyên bố thoái vị (30/8/1945).', 'Thành lập nước Việt Nam Dân chủ Cộng hòa (2/9/1945).', 'Cuộc khởi nghĩa giành chính quyền ở Huế (23/8/1945).', 'Tổng khởi nghĩa tháng Tám thắng lợi trên cả nước (28/8/1945).',
    1, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là A: Vua Bảo Đại của triều Nguyễn tuyên bố thoái vị (30/8/1945).'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B08_44', '6e0f8c53-9919-4099-81ab-7f7d5645a37b', 'LS9_KNTT_B08', 'Hội nghị Ban Chấp hành Trung ương Đảng lần thứ 8 (5/1941) đã chủ trương tạm gác nhiệm vụ nào?',
    'Cách mạng ruộng đất.', 'Đánh đuổi đế quốc, phát xít.', 'Giải phóng dân tộc.', 'Dân tộc dân chủ.',
    1, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là A: Cách mạng ruộng đất.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B08_45', '6e0f8c53-9919-4099-81ab-7f7d5645a37b', 'LS9_KNTT_B08', 'Mặt trận nào giữ vai trò chuẩn bị trực tiếp cho Cách mạng tháng Tám năm 1945?',
    'Mặt trận Nhân dân phản đế Đông Dương.', 'Mặt trận Việt Nam độc lập đồng minh.', 'Mặt trận Dân tộc phản đế Đông Dương.', 'Mặt trận Liên hiệp quốc dân Việt Nam.',
    2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: Mặt trận Việt Nam độc lập đồng minh.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B08_46', '6e0f8c53-9919-4099-81ab-7f7d5645a37b', 'LS9_KNTT_B08', 'Sự kiện nào chứng tỏ cuộc Cách mạng tháng Tám đã giành thắng lợi tương đối trọn vẹn trong cả nước?',
    'Cuộc tổng tuyển cử bầu đai biểu Quốc hội và Hội đồng nhân dân các cấp.', 'Quần chúng nhân dân ở Hà Nội Tổng khởi nghĩa giành chính quyền.', 'Vua Bảo Đại tuyên bố thoái vị, chấm dứt sự tồn tại của chế độ phong kiến.', 'Hà Tiên và Đồng Nai Thượng là hai tỉnh cuối cùng giành chính quyền.',
    4, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là D: Hà Tiên và Đồng Nai Thượng là hai tỉnh cuối cùng giành chính quyền.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B08_48', '6e0f8c53-9919-4099-81ab-7f7d5645a37b', 'LS9_KNTT_B08', 'Phương pháp đấu tranh cơ bản nào sau đây được thực hiện trong Tổng khởi nghĩa tháng Tám năm 1945?',
    'Đấu tranh chính trị kết hợp với đấu tranh báo chí.', 'Đấu tranh chính trị kết hợp với đấu tranh nghị trường.', 'Đấu tranh vũ trang kết hợp với đấu tranh ngoại giao.', 'Đấu tranh chính trị kết hợp với đấu tranh vũ trang.',
    4, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là D: Đấu tranh chính trị kết hợp với đấu tranh vũ trang.'
);
