    'Đức xâm lược Pháp.', 'Đức tấn công Liên Xô.', 'Nhật đánh chiếm Trung Quốc.', 'Nhật xâm lược Đông Dương.',
    1, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là A: Đức xâm lược Pháp.'
);
INSERT INTO lesson_question (
