INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B08_61', '6e0f8c53-9919-4099-81ab-7f7d5645a37b', 'LS9_KNTT_B08', 'Lực lượng nào giữ vai trò nòng cốt, quyết định thắng lợi của Tổng khởi nghĩa tháng Tám năm 1945?',
    'Lực lượng bán vũ trang.', 'Lực lượng du kích.', 'Lực lượng vũ trang.', 'Lực lượng chính trị.',
    4, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là D: Lực lượng chính trị.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B08_62', '6e0f8c53-9919-4099-81ab-7f7d5645a37b', 'LS9_KNTT_B08', 'Hội nghị lần thứ 8 Ban Chấp hành Trung ương Đảng (5/1941) đã đề cập đến kẻ thù chính của cách mạng Việt Nam là',
    'quân phiệt Nhật.', 'Pháp - Nhật.', 'thực dân Pháp.', 'phong kiến triều Nguyễn.',
    2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: Pháp - Nhật.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B08_63', '6e0f8c53-9919-4099-81ab-7f7d5645a37b', 'LS9_KNTT_B08', 'Những địa phương nào giành được chính quyền ở tỉnh lị đầu tiên trong Tổng khởi nghĩa tháng Tám 1945?',
    'Hà Tĩnh, Tuyên Quang, Hà Giang, Hải Dương.', 'Thái Nguyên, Tuyên Quang, Lạng Sơn.', 'Bắc Giang, Hải Dương, Hà Tĩnh, Quảng Nam.', 'Bắc Giang, Vĩnh Phúc, Quảng Nam, Hà Tiên.',
    3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: Bắc Giang, Hải Dương, Hà Tĩnh, Quảng Nam.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B08_64', '6e0f8c53-9919-4099-81ab-7f7d5645a37b', 'LS9_KNTT_B08', 'Trong những năm 1930 - 1945, Việt Nam đã thành lập Mặt trận thống nhất dân tộc riêng đầu tiên là',
    'Mặt trận Dân tộc phản đế Đông Dương.', 'Mặt trận Dân chủ Đông Dương.', 'Mặt trận Nhân dân phản đế Đông Dương.', 'Mặt trận Việt Nam độc lập đồng minh.',
    4, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là D: Mặt trận Việt Nam độc lập đồng minh.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B08_65', '6e0f8c53-9919-4099-81ab-7f7d5645a37b', 'LS9_KNTT_B08', 'Lực lượng nào giữ vai trò quan trọng trong cao trào kháng Nhật cứu nước (3 - 8/1945) ở nông thôn và thành thị Việt Nam?',
    'Bộ đội địa phương.', 'Quân đội chính quy.', 'Quần chúng cách mạng.', 'Lực lượng vũ trang.',
    3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: Quần chúng cách mạng.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B08_66', '6e0f8c53-9919-4099-81ab-7f7d5645a37b', 'LS9_KNTT_B08', 'Nhà nước Việt Nam Dân chủ Cộng hoà được thành lập năm 1945 là nhà nước của',
    'Xô viết đại biểu của công - nông.', 'công nhân, nông dân, binh lính.', 'toàn thể nhân dân Việt Nam.', 'liên hiệp kháng chiến chống Pháp.',
    3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: toàn thể nhân dân Việt Nam.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B08_67', '6e0f8c53-9919-4099-81ab-7f7d5645a37b', 'LS9_KNTT_B08', 'Nội dung nào sau đây không phải là quyết dịnh của Hội nghị Ban Chấp hành Trung ương Đảng lần thứ 8 (5/1941)?',
    'Xác định kẻ thù của cách mạng là Pháp - Nhật.', 'Xác định hình thái của cuộc cách mạng.', 'Nhiệm vụ chủ yếu là giải phóng dân tộc.', 'Thông qua chính sách đối nội và đối ngoại.',
    4, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là D: Thông qua chính sách đối nội và đối ngoại.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B08_68', '6e0f8c53-9919-4099-81ab-7f7d5645a37b', 'LS9_KNTT_B08', 'Sự kiện nào tạo nên cuộc khủng hoảng chính trị sâu sắc ở Đông Dương tháng 3 năm 1945?',
    'Nhật đảo chính Pháp độc chiếm Đông Dương.', 'Ba nước ở Đông Nam Á giành độc lập dân tộc.', 'Pháp ráo riết chuẩn bị lực lượng phản công Nhật.', 'Nhật đầu hàng quân Đồng minh vô điều kiện.',
    1, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là A: Nhật đảo chính Pháp độc chiếm Đông Dương.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B08_70', '6e0f8c53-9919-4099-81ab-7f7d5645a37b', 'LS9_KNTT_B08', 'Trong Cách mạng tháng Tám năm 1945, khởi nghĩa tại các đô thị thắng lợi có ý nghĩa quyết định nhất vì đây là nơi',
    'có nhiều căn cứ địa cách mạng của Việt Nam.', 'có đông đảo quần chúng giác ngộ cách mạng.', 'đặt cơ quan đầu não chỉ huy của lực lượng cách mạng.', 'tập trung các trung tâm kinh tế, chính trị của kẻ thù.',
    4, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là D: tập trung các trung tâm kinh tế, chính trị của kẻ thù.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B08_74', '6e0f8c53-9919-4099-81ab-7f7d5645a37b', 'LS9_KNTT_B08', 'Tháng 12/1944, Đội Việt Nam Tuyên truyền Giải phóng quân đã giành thắng lợi đầu tiên ở',
    'Phay Khắt và Nà Ngần.', 'Phay Khắt và Pác Pó.', 'Pắc Nặm và Na Rì.', 'Nà Ngần và Ngân Sơn.',
    4, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là D: Nà Ngần và Ngân Sơn.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B08_76', '6e0f8c53-9919-4099-81ab-7f7d5645a37b', 'LS9_KNTT_B08', 'Đội Việt Nam Tuyên truyền Giải phóng quân được thành lập năm 1944 với nhiệm vụ trọng tâm nào sau đây?',
    'Tiến hành khởi nghĩa từng phần ở các căn cứ địa.', 'Tuyên truyền, chính trị kết hợp với đấu tranh quân sự.', 'Xây dựng lực lượng chính trị đông đảo ở Việt Bắc.', 'Khởi nghĩa vũ trang giành chính quyền trong cả nước.',
    2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: Tuyên truyền, chính trị kết hợp với đấu tranh quân sự.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B08_77', '6e0f8c53-9919-4099-81ab-7f7d5645a37b', 'LS9_KNTT_B08', 'Hội nghị Trung ương Đảng (11/1939) đã đánh dấu sự chuyển hướng đúng đắn về chiến lược cách mạng vì',
    'đặt vấn đề dân tộc cho ba nước Đông Dương.', 'giải quyết kịp thời vấn đề ruộng đất cho nông dân.', 'xác định kẻ thù chủ yếu trước mắt là quân phiệt Nhật.', 'đã giương cao ngọn cờ giải phóng dân tộc.',
    4, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là D: đã giương cao ngọn cờ giải phóng dân tộc.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B08_78', '6e0f8c53-9919-4099-81ab-7f7d5645a37b', 'LS9_KNTT_B08', 'Nguyễn Ái Quốc chọn địa phương nào sau đây là nơi thí điểm xây dựng các đoàn thể quần chúng trong Mặt trận Việt Minh?',
    'Thái Nguyên.', 'Tuyên Quang.', 'Lạng Sơn.', 'Cao Bằng.',
    4, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là D: Cao Bằng.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B08_79', '6e0f8c53-9919-4099-81ab-7f7d5645a37b', 'LS9_KNTT_B08', 'Nội dung nào là căn cứ để xác định tính chất dân tộc của Cách mạng tháng Tám năm 1945 ở Việt Nam?',
    'Đi từ khởi nghĩa từng phần tiến tới tổng khởi nghĩa.', 'Thành lập chính quyền nhà nước của toàn thể nhân dân.', 'Diễn ra có sự kết hợp hài hoà giữa nông thôn và thành thị.', 'Giải quyết một phần quyền lợi về ruộng đất của nông dân.',
    2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: Thành lập chính quyền nhà nước của toàn thể nhân dân.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B08_80', '6e0f8c53-9919-4099-81ab-7f7d5645a37b', 'LS9_KNTT_B08', 'Pháp chấp nhận làm tay sai cho Nhật, cùng Nhật thống trị Đông Dương (9/1940 - 3/1945) vì',
    'Phe phát xít đang mở rộng chiến tranh ra toàn thế giới.', 'thực dân Pháp đã suy yếu, không đủ sức chống lại Nhật.', 'Pháp muốn mượn tay Nhật đàn áp cách mạng Việt Nam.', 'Tránh mũi nhọn đấu tranh của nhân dân Đông Dương.',
    2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: thực dân Pháp đã suy yếu, không đủ sức chống lại Nhật.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B08_81', '6e0f8c53-9919-4099-81ab-7f7d5645a37b', 'LS9_KNTT_B08', 'Thủ đô của Khu Giải phóng Việt Bắc thành lập tháng 6 năm 1945 là',
    'Chiêm Hóa (Tuyên Quang).', 'Tân Trào (Tuyên Quang).', 'Pác Pó (Cao Bằng).', 'Định Hóa (Thái Nguyên).',
    2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: Tân Trào (Tuyên Quang).'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B08_82', '6e0f8c53-9919-4099-81ab-7f7d5645a37b', 'LS9_KNTT_B08', 'Trong Chiến tranh thế giới thứ hai, Nhật xâm lược Đông Dương (9/1940) nhằm mục đích cơ bản nào sau đây?',
    'Biến Đông Dương thành thuộc địa và căn cứ quân sự.', 'Đặt Đông Dương dưới ô bảo trợ hạt nhân của Nhật.', 'Độc chiếm Đông Dương và các nước Đông Nam Á.', 'Chia đôi hệ thống thuộc địa của đế quốc Âu - Mỹ.',
    1, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là A: Biến Đông Dương thành thuộc địa và căn cứ quân sự.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B09_01', '542964d7-d96f-42ee-a561-829f2aaba8c8', 'LS9_KNTT_B09', 'Nội dung nào sau đây phản ánh tác động của Chiến tranh lạnh đến quan hệ quốc tế sau Chiến tranh thế giới thứ hai?',
    'Dẫn tới sự hình thành trật tự thế giới đa cực.', 'Đưa các quốc gia khu vực xích lại gần nhau hơn.', 'Làm cho quan hệ quốc tế căng thẳng, phức tạp.', 'Làm cho kinh tế của cả Mĩ và Liên Xô suy giảm.',
    3, 20, 'WARM_UP', 'EASY', 'Đáp án đúng là C: Làm cho quan hệ quốc tế căng thẳng, phức tạp.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B09_02', '542964d7-d96f-42ee-a561-829f2aaba8c8', 'LS9_KNTT_B09', 'Hội đồng tương trợ kinh tế (SEV) ra đời năm 1949 nhằm thực hiện mục tiêu nào sau đây?',
    'Đẩy mạnh chương trình tư nhân hóa xí nghiệp nhà nước', 'Thúc đẩy sự phát triển xu thế toàn cầu hóa trên thế giới.', 'Tăng cường sự hợp tác giữa các nước xã hội chủ nghĩa.', 'Thúc đẩy sự tiến bộ vượt bậc về quân sự của các nước.',
    3, 20, 'WARM_UP', 'EASY', 'Đáp án đúng là C: Tăng cường sự hợp tác giữa các nước xã hội chủ nghĩa.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B09_03', '542964d7-d96f-42ee-a561-829f2aaba8c8', 'LS9_KNTT_B09', 'Chiến tranh lạnh chấm dứt năm 1989 đã có tác động nào sau đây đến tình hình thế giới?',
    'Phạm vi ảnh hưởng của Mỹ và Liên Xô ngày càng bị thu hẹp.', 'Chấm dứt hoàn toàn các cuộc nội chiến xung đột trên toàn thế giới.', 'Nhiều tranh chấp, xung đột được giải quyết bằng biện pháp hòa bình.', 'Nền kinh tế Tây Âu và Nhật Bản không ngừng phát triển.',
    3, 20, 'WARM_UP', 'EASY', 'Đáp án đúng là C: Nhiều tranh chấp, xung đột được giải quyết bằng biện pháp hòa bình.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B09_05', '542964d7-d96f-42ee-a561-829f2aaba8c8', 'LS9_KNTT_B09', 'Nhân tố chủ yếu nào chi phối quan hệ quốc tế trong phần lớn nửa sau thế kỉ XX?',
    'Liên minh châu Âu (EU).', 'Xu thế toàn cầu hóa.', 'Sự ra đời của NATO và Vác-sa-va.', 'Cục diện “Chiến tranh lạnh”.',
    4, 20, 'WARM_UP', 'EASY', 'Đáp án đúng là D: Cục diện “Chiến tranh lạnh”.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B09_06', '542964d7-d96f-42ee-a561-829f2aaba8c8', 'LS9_KNTT_B09', 'Sự kiện nào là “sản phẩm” của Chiến tranh lạnh và là cuộc đụng đầu trực tiếp đầu tiên giữa hai phe?',
    'Cuộc chiến tranh Triều Tiên (1950 - 1953).', 'Cuộc chiến tranh xâm lược Đông Dương của Pháp (1945 - 1954).', 'Cuộc chiến tranh xâm lược Việt Nam của Mỹ (1954 - 1975).', 'Cuộc nội chiến ở Campuchia (1979 - 1991).',
    1, 20, 'WARM_UP', 'EASY', 'Đáp án đúng là A: Cuộc chiến tranh Triều Tiên (1950 - 1953).'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B09_07', '542964d7-d96f-42ee-a561-829f2aaba8c8', 'LS9_KNTT_B09', 'Để thực hiện Chiến tranh lạnh, Mỹ và Liên Xô đều',
    'thiết lập được chủ quyền trên Mặt trăng.', 'chế tạo thành công bom nguyên tử.', 'tham gia vào chiến tranh ở khu vực châu Mỹ.', 'ban hành hiệp ước cấm vũ khí hạt nhân.',
    2, 20, 'WARM_UP', 'EASY', 'Đáp án đúng là B: chế tạo thành công bom nguyên tử.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B09_08', '542964d7-d96f-42ee-a561-829f2aaba8c8', 'LS9_KNTT_B09', 'Sự ra đời của tổ chức NATO và Vác-sa-va có tác động nào đến quan hệ quốc tế sau Chiến tranh thế giới thứ hai?',
    'Đánh dấu sự phát triển vượt bậc của Mỹ và Liên Xô về quân sự.', 'Đánh dấu sự xác lập của cục diện hai cực, hai phe.', 'Mở màn cho sự xác lập của các tổ chức quân sự trên thế giới.', 'Chấm dứt mối quan hệ Đồng minh giữa Liên Xô và Mỹ.',
    2, 20, 'WARM_UP', 'EASY', 'Đáp án đúng là B: Đánh dấu sự xác lập của cục diện hai cực, hai phe.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B09_09', '542964d7-d96f-42ee-a561-829f2aaba8c8', 'LS9_KNTT_B09', 'Nội dung nào sau đây phản ánh sự thay đổi quan hệ giữa Mỹ và Liên Xô Sau Chiến tranh thế giới thứ hai?',
    'Từ liên minh chống phát xít chuyển sang đối đầu gay gắt.', 'Hợp tác chặt chẽ để tiêu diệt chủ nghĩa khủng bố trên thế giới.', 'Chuyển từ đối đầu căng thẳng sang đối thoại, hoà hoãn.', 'Hợp tác cùng nhau giải quyết nhiều vấn đề quốc tế lớn.',
    1, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là A: Từ liên minh chống phát xít chuyển sang đối đầu gay gắt.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B09_10', '542964d7-d96f-42ee-a561-829f2aaba8c8', 'LS9_KNTT_B09', 'Nội dung nào sau đây phản ánh đúng hành động của Liên Xô đối với bán đảo Triều Tiên trong thời kỳ Chiến tranh lạnh?',
    'Viện trợ và trực tiếp tham gia vào cuộc chiến tranh với Hàn Quốc.', 'Xây dựng chính quyền mới thân Liên Xô ở miền Bắc Triều Tiên.', 'Đưa tên lửa hạt nhân và bom nguyên tử vào sử dụng ở Hàn Quốc.', 'Phản đối quá trình phi hạt nhân hóa trên bán đảo Triều Tiên.',
    1, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là A: Viện trợ và trực tiếp tham gia vào cuộc chiến tranh với Hàn Quốc.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B09_11', '542964d7-d96f-42ee-a561-829f2aaba8c8', 'LS9_KNTT_B09', 'Nội dung nào sau đây phản ánh đúng chính sách của Liên Xô đối với Cuba trong thời kỳ Chiến tranh lạnh?',
    'Thiết lập các căn cứ quân sự và căn cứ hải quân ở Cuba.', 'Giúp Cuba chế tạo tên lửa hạt nhân để đối trọng với Mỹ.', 'Tiến hành phi quân sự hóa để tập trung phát triển kinh tế.', 'Đưa quân đội thường trực và tên lửa hạt nhân vào Cuba.',
    4, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là D: Đưa quân đội thường trực và tên lửa hạt nhân vào Cuba.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B09_12', '542964d7-d96f-42ee-a561-829f2aaba8c8', 'LS9_KNTT_B09', 'Tháng 6 năm 1947, Mỹ đề ra kế hoạch Mácsan không nhằm mục đích nào?',
    'Tạo nên sự đối lập về kinh tế và chính trị giữa các nước Tây Âu và Đông Âu.', 'Khống chế và nô dịch các nước đồng minh của Mỹ ở Tây Âu.', 'Thành lập liên minh quân sự chống lại Liên Xô và các nước Đông Âu.', 'Giúp các nước Tây Âu phục hồi nền kinh tế bị tàn phá sau chiến tranh.',
    1, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là A: Tạo nên sự đối lập về kinh tế và chính trị giữa các nước Tây Âu và Đông Âu.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B09_13', '542964d7-d96f-42ee-a561-829f2aaba8c8', 'LS9_KNTT_B09', 'Nội dung nào sau đây phản ánh chính sách của Mỹ đối với Cuba trong thời kỳ Chiến tranh lạnh?',
    'Thực hiện phong tỏa hải quân đối với Cuba.', 'Yêu cầu Cuba phải tiến hành cải cách dân chủ.', 'Cấm Cuba được phổ biến vũ khí hạt nhân.', 'Cấm Cuba tham gia vào tổ chức Liên hợp quốc.',
    1, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là A: Thực hiện phong tỏa hải quân đối với Cuba.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B09_14', '542964d7-d96f-42ee-a561-829f2aaba8c8', 'LS9_KNTT_B09', 'Năm 1949, Liên Xô chế tạo thành công bom nguyên tử là biểu hiện của',
    'xu thế toàn cầu hóa trên thế giới.', 'cuộc chạy đua vũ trang đối với Mỹ.', 'việc phổ biến vũ khí hạt nhân trên thế giới.', 'cuộc cách mạng xanh trong quân sự.',
    2, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là B: cuộc chạy đua vũ trang đối với Mỹ.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B09_15', '542964d7-d96f-42ee-a561-829f2aaba8c8', 'LS9_KNTT_B09', 'Trong thời kỳ Chiến tranh lạnh, nước Đức trở thành một tâm điểm đối đầu ở châu Âu giữa hai cực Xô - Mỹ?',
    'Đức là thành trì của chủ nghĩa phát xít trước Chiến tranh thế giới thứ hai.', 'Nước Đức có chung đường biên giới với Liên Xô và các nước Bắc Âu.', 'Nước Đức đã hình thành hai nhà nước đối lập ở hai miền Đông -Tây.', 'Đức là nơi đặt trụ sở của khối Hiệp ước Bắc Đại Tây Dương (NATO).',
    3, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là C: Nước Đức đã hình thành hai nhà nước đối lập ở hai miền Đông -Tây.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B09_16', '542964d7-d96f-42ee-a561-829f2aaba8c8', 'LS9_KNTT_B09', 'Sự kiện nào sau đây đánh dấu Chiến tranh lạnh chấm dứt sau hơn 40 tồn tại?',
    'Tổ chức Vác-sa-va và SEV lần lượt giải thể.', 'Xô - Mĩ kí Hiệp ước về việc hạn chế vũ khí chiến lược.', 'Cuộc gặp gỡ Xô - Mỹ tại đảo Man- ta (12/1989).', 'Xô - Mỹ kí Hiệp ước về hạn chế phòng chống tên lửa.',
    3, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là C: Cuộc gặp gỡ Xô - Mỹ tại đảo Man- ta (12/1989).'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B09_17', '542964d7-d96f-42ee-a561-829f2aaba8c8', 'LS9_KNTT_B09', 'Thông điệp của Tổng thống Truman tại Quốc hội Mỹ (3/1947) đã',
    'tạo nên sự đối lập giữa các nước Đông Âu và Tây Âu.', 'ngăn chặn quá trình mở rộng của chủ nghĩa xã hội.', 'mở đầu việc xác lập trật tự hai cực trên thế giới.', 'củng cố hơn nữa mối quan hệ giữa Mỹ và Tây Âu.',
    4, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là D: củng cố hơn nữa mối quan hệ giữa Mỹ và Tây Âu.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B09_18', '542964d7-d96f-42ee-a561-829f2aaba8c8', 'LS9_KNTT_B09', 'Chiến tranh lạnh chấm dứt tác động như thế nào đến tình hình các nước Đông Nam Á cuối thế kỉ XX?',
    'Tạo điều kiện cho sự ra đời và phát triển của tổ chức ASEAN.', 'Làm hòa dịu quan hệ giữa ASEAN và các nước Đông Dương.', 'Làn sóng xã hội chủ nghĩa lan rộng ở Đông Nam Á.', 'Thúc đẩy phong trào giải phóng dân tộc phát triển mạnh.',
    2, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là B: Làm hòa dịu quan hệ giữa ASEAN và các nước Đông Dương.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B09_19', '542964d7-d96f-42ee-a561-829f2aaba8c8', 'LS9_KNTT_B09', 'Nội dung nào phản ánh đúng kết quả sự đối đầu căng thẳng giữa Mỹ và Liên Xô sau Chiến tranh thế giới thứ hai?',
    'Dẫn đến những cuộc xung đột quân sự trực tiếp.', 'Dẫn đến cuộc chiến tranh thế giới mới.', 'Chuyển dần sang hòa bình, đối thoại, cùng phát triển.', 'Trở thành Đồng minh thân cận với nhau.',
    3, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là C: Chuyển dần sang hòa bình, đối thoại, cùng phát triển.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B09_20', '542964d7-d96f-42ee-a561-829f2aaba8c8', 'LS9_KNTT_B09', 'Mâu thuẫn gay gắt, quyết liệt giữa các nước lớn sau Chiến tranh thế giới thứ hai thực chất là sự mâu thuẫn về',
    'tham vọng bá chủ thế giới.', 'những quyền lợi kinh tế khác nhau.', 'hệ tư tưởng chính trị khác nhau.', 'thành quả thắng lợi sau chiến tranh.',
    3, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là C: hệ tư tưởng chính trị khác nhau.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B10_01', '1fd255a5-c6ba-49fe-932a-3e3a7ccc8761', 'LS9_KNTT_B10', 'Nội dung nào sau đây không phản ánh đúng tình hình xã hội của Đông Âu những năm 70,80 của thế kỷ XX?',
    'Nhân dân phản đối chế độ đa nguyên, đa đảng.', 'Niềm tin của nhân dân vào chủ nghĩa xã hội giảm sút.', 'Tình trạng bất bình trong xã hội có sự gia tăng.', 'Đời sống của các tầng lớp nhân dân khó khăn.',
    1, 20, 'WARM_UP', 'EASY', 'Đáp án đúng là A: Nhân dân phản đối chế độ đa nguyên, đa đảng.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B10_03', '1fd255a5-c6ba-49fe-932a-3e3a7ccc8761', 'LS9_KNTT_B10', 'Chủ nghĩa xã hội ở Liên Xô và Đông Âu sụp đổ hoàn toàn năm 1991 chứng tỏ',
    'hệ thống xã hội chủ nghĩa thế giới không còn tồn tại.', 'chiến lược toàn cầu bá chủ thế giới của Mĩ đã thành công.', 'hệ thống xã hội chủ nghĩa chỉ còn lại ở châu Á và châu Mĩ.', 'Liên Xô không đứng đầu phe xã hội chủ nghĩa ở châu Âu.',
    1, 20, 'WARM_UP', 'EASY', 'Đáp án đúng là A: hệ thống xã hội chủ nghĩa thế giới không còn tồn tại.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B10_04', '1fd255a5-c6ba-49fe-932a-3e3a7ccc8761', 'LS9_KNTT_B10', 'Bài học kinh nghiệm cho Việt Nam từ sự sụp đổ của chủ nghĩa xã hội ở Liên Xô và Đông Âu là',
    'tăng cường cải cách dân chủ trên mọi lĩnh vực.', 'tăng cường sự viện trợ và giúp đỡ của nước ngoài.', 'phải duy trì được mối liên hệ với các cường quốc.', 'phải giữ vững vai trò lãnh đạo của Đảng Cộng sản.',
    4, 20, 'WARM_UP', 'EASY', 'Đáp án đúng là D: phải giữ vững vai trò lãnh đạo của Đảng Cộng sản.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B10_05', '1fd255a5-c6ba-49fe-932a-3e3a7ccc8761', 'LS9_KNTT_B10', 'Nội dung nào sau đây phản ánh chính sách tích cực về giáo dục của Liên Xô sau Chiến tranh thế giới thứ hai?',
    'Thực hiện chế độ giáo dục miễn phí.', 'Thành lập cơ sở giáo dục ở thuộc địa.', 'Tiến hành phổ cập giáo dục đại học.', 'Phát động phong trào Bình dân học vụ.',
    1, 20, 'WARM_UP', 'EASY', 'Đáp án đúng là A: Thực hiện chế độ giáo dục miễn phí.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B10_06', '1fd255a5-c6ba-49fe-932a-3e3a7ccc8761', 'LS9_KNTT_B10', 'Sau khi Nhà nước dân chủ nhân dân ra đời, ở các nước Đông Âu, công nhân, nông dân, trí thức đã',
    'thống trị các giai cấp trong xã hội.', 'quốc hữu hóa xí nghiệp của tư sản.', 'không được hưởng các quyền lợi.', 'trở thành người làm chủ đất nước.',
    4, 20, 'WARM_UP', 'EASY', 'Đáp án đúng là D: trở thành người làm chủ đất nước.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B10_07', '1fd255a5-c6ba-49fe-932a-3e3a7ccc8761', 'LS9_KNTT_B10', 'Ngày 21/12/1991, ở châu Âu, 11 nước cộng hòa kí hiệp định thành lập các quốc gia độc lập (SNG) chứng tỏ điều gì?',
    'Sự đoàn kết giữa Liên Xô và Đông Âu có chuyển biến mới', 'Nhà nước Liên bang Cộng hòa XHCN không còn tồn tại.', 'Hiến pháp mới của Liên bang Nga là đúng đắn, phù hợp.', 'Sự đối đầu giữa Mỹ và Liên Xô đã sụp đổ hoàn toàn.',
    2, 20, 'WARM_UP', 'EASY', 'Đáp án đúng là B: Nhà nước Liên bang Cộng hòa XHCN không còn tồn tại.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B10_08', '1fd255a5-c6ba-49fe-932a-3e3a7ccc8761', 'LS9_KNTT_B10', 'Trong công cuộc xây dựng chủ nghĩa xã hội, lĩnh vực kinh tế phát triển mạnh mẽ nhất của Liên Xô là',
    'thủ công nghiệp.', 'công nghiệp.', 'thương nghiệp.', 'nông nghiệp.',
    2, 20, 'WARM_UP', 'EASY', 'Đáp án đúng là B: công nghiệp.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B10_09', '1fd255a5-c6ba-49fe-932a-3e3a7ccc8761', 'LS9_KNTT_B10', 'Nội dung nào thể hiện vị thế công nghiệp của Liên Xô từ những năm 1950 đến nửa đầu những năm 70 của thế kỉ XX?',
    'Cường quốc nông nghiệp thứ hai thế giới sau Mỹ.', 'Cường quốc công nghiệp thứ hai thế giới sau Mỹ.', 'Siêu cường kinh tế - tài chính lớn nhất thế giới.', 'Trở thành trung tâm kinh tế - tài chính lớn của thế giới.',
    2, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là B: Cường quốc công nghiệp thứ hai thế giới sau Mỹ.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B10_10', '1fd255a5-c6ba-49fe-932a-3e3a7ccc8761', 'LS9_KNTT_B10', 'Nội dung nào là thành tựu lớn nhất về mặt quân sự của Liên Xô từ những năm 50 đến những năm 70 của thế kỉ XX?',
    'Đạt thế cân bằng về sức mạnh quân sự với Mĩ.', 'Làm tan rã các liên minh quân sự của Mĩ trên thế giới.', 'Ký hiệp ước hạn chế vũ khí tiến công chiến lược.', 'Phá vỡ thế độc quyền về vũ khí nguyên tử của Mĩ.',
    1, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là A: Đạt thế cân bằng về sức mạnh quân sự với Mĩ.'
);
