    'Q_LS9_B10_22', '1fd255a5-c6ba-49fe-932a-3e3a7ccc8761', 'LS9_KNTT_B10', 'Sự sụp đổ của chủ nghĩa xã hội ở Liên Xô và Đông Âu có tác động nào sau đây?',
    'Chủ nghĩa tư bản nắm quyền thống trị thế giới.', 'Làm cho trật tự hai cực Ianta hoàn toàn sụp đổ.', 'Chủ nghĩa xã hội sụp đổ hoàn toàn trên thế giới.', 'Mĩ và Liên Xô tuyên bố chấm dứt Chiến tranh lạnh.',
    2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: Làm cho trật tự hai cực Ianta hoàn toàn sụp đổ.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B10_23', '1fd255a5-c6ba-49fe-932a-3e3a7ccc8761', 'LS9_KNTT_B10', 'Nguyên nhân khách quan nào sau đây làm cho chế độ xã hội chủ nghĩa ở Liên Xô và Đông Âu khủng hoảng và sụp đổ?',
    'Phong trào li khai diễn ra mạnh mẽ gây nhiều bất ổn chính trị.', 'Tổ chức Hiệp ước Vác-sa-va không phát huy được vai trò.', 'Đảng Cộng sản ở Liên Xô và Đông Âu bị đình chỉ hoạt động.', 'Hoạt động chống phá của các thế lực thù địch trong và ngoài nước.',
    4, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là D: Hoạt động chống phá của các thế lực thù địch trong và ngoài nước.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
