    'Q_LS9_B10_25', '1fd255a5-c6ba-49fe-932a-3e3a7ccc8761', 'LS9_KNTT_B10', 'Với chiến thắng chủ nghĩa phát xít và các lực lượng phản động, Liên Xô đã',
    'hoàn thành phong trào cách mạng trên thế giới.', 'bảo vệ được cơ sở vật chất của chủ nghĩa xã hội.', 'bảo vệ được chế độ chính trị xã hội tiến bộ của mình.', 'xóa bỏ được những bất bình đẳng trong xã hội.',
    3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: bảo vệ được chế độ chính trị xã hội tiến bộ của mình.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
