    'Q_LS9_B10_27', '1fd255a5-c6ba-49fe-932a-3e3a7ccc8761', 'LS9_KNTT_B10', 'Những ấn phẩm văn hóa của Liên Xô và Đông Âu trong những năm 80 của thế kỷ XX có nội dung nào sau đây?',
    'Tuyên truyền lý tưởng của chủ nghĩa Mác - Lênin.', 'Chống việc hình thành chế độ đa nguyên, đa đảng.', 'Phổ biến lý luận của cách mạng xã hội chủ nghĩa.', 'Chống chủ nghĩa xã hội, tuyên truyền chế độ đa nguyên.',
    4, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là D: Chống chủ nghĩa xã hội, tuyên truyền chế độ đa nguyên.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B10_28', '1fd255a5-c6ba-49fe-932a-3e3a7ccc8761', 'LS9_KNTT_B10', 'Trong những năm chủ nghĩa xã hội ở Liên Xô và Đông Âu lâm vào khủng hoảng, Đảng và Nhà nước Việt Nam khẳng định',
    'Việt Nam chịu tác động lớn nên cần phải đổi mới đất nước.', 'Việt Nam không chịu tác động từ cuộc khủng hoảng ở Liên Xô.', 'Việt Nam cần tăng cường viện trợ cho Liên Xô và Đông Âu.', 'mô hình chủ nghĩa xã hội chỉ phù hợp ở châu Á và Mĩ La-tinh.',
    1, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là A: Việt Nam chịu tác động lớn nên cần phải đổi mới đất nước.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
