    'Q_LS9_B10_29', '1fd255a5-c6ba-49fe-932a-3e3a7ccc8761', 'LS9_KNTT_B10', 'Nội dung nào sau đây thể hiện tính ưu việt của chủ nghĩa xã hội ở Liên Xô từ năm 1945 đến năm 1973?',
    'Đô thị hóa tất cả các vùng nông thôn.', 'Thực hiện chế độ giáo dục miễn phí.', 'Thực hiện cơ chế tập trung bao cấp.', 'Thực hiện chế độ khám bệnh miễn phí.',
    2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: Thực hiện chế độ giáo dục miễn phí.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B10_30', '1fd255a5-c6ba-49fe-932a-3e3a7ccc8761', 'LS9_KNTT_B10', 'Trong những năm 80 của thế kỷ XX, cuộc cải tổ của Liên Xô đã',
    'giải quyết được xung đột sắc tộc, tôn giáo.', 'xóa bỏ được nền chính trị chuyên chế.', 'xác lập hệ thống chính quyền tổng thống.', 'hình thành chế độ đa đảng, nhất nguyên.',
    3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: xác lập hệ thống chính quyền tổng thống.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
