);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B10_32', '1fd255a5-c6ba-49fe-932a-3e3a7ccc8761', 'LS9_KNTT_B10', 'Sự hợp tác tương trợ về kinh tế giữa Liên Xô và Đông Âu được tăng cường sau sự kiện nào?',
    'Tổ chức Hiệp ước Vác-sa-va ra đời năm 1955.', 'Đông Âu trở thành Đồng minh thân cận của Liên Xô.', 'Hội đồng tương trợ kinh tế (SEV) thành lập năm 1949.', 'Liên Xô viện trợ không hoàn lại cho các nước Đông Âu.',
    3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: Hội đồng tương trợ kinh tế (SEV) thành lập năm 1949.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B10_34', '1fd255a5-c6ba-49fe-932a-3e3a7ccc8761', 'LS9_KNTT_B10', 'Nội dung nào sau đây phản ánh đúng tình hình kinh tế của Liên Xô trong những năm 1989 - 1991?',
    'Cuộc cải tổ đã xây dựng được nền kinh tế thị trường.', 'Khôi phục được thành tựu kinh tế trước khủng hoảng.', 'Khan hiếm lương thực, thực phẩm và hàng tiêu dùng.', 'Thành phần kinh tế nhà nước giữa vai trò độc quyền.',
    3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: Khan hiếm lương thực, thực phẩm và hàng tiêu dùng.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B10_35', '1fd255a5-c6ba-49fe-932a-3e3a7ccc8761', 'LS9_KNTT_B10', 'Nguyên nhân chủ yếu nào dẫn đến sự sụp đổ CNXH ở Liên Xô và Đông Âu cuối thế kỉ XX?',
    'Sự chống phá của các thế lực thù địch ở trong và ngoài nước.', 'Khi cải tổ phạm phải nhiều sai lầm, làm cho khủng hoảng trầm trọng.', 'Đường lối lãnh đạo mang tính chủ quan, quan liêu, bao cấp.', 'Không bắt kịp bước phát triển của khoa học kĩ thuật tiên tiến.',
    2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: Khi cải tổ phạm phải nhiều sai lầm, làm cho khủng hoảng trầm trọng.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B10_37', '1fd255a5-c6ba-49fe-932a-3e3a7ccc8761', 'LS9_KNTT_B10', 'Chính sách đối ngoại của Liên Xô từ năm 1950 đến đầu những năm 70 của thế kỉ XX không có nội dung nào dưới đây?',
    'Bảo vệ hòa bình an ninh thế giới.', 'Ngả về các nước tư bản phương Tây.', 'Giúp đỡ các nước xã hội chủ nghĩa.', 'Ủng hộ phong trào giải phóng dân tộc.',
    2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: Ngả về các nước tư bản phương Tây.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
