INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B10_40', '1fd255a5-c6ba-49fe-932a-3e3a7ccc8761', 'LS9_KNTT_B10', 'Sau Chiến tranh thế giới thứ hai, Liên Xô vượt Mỹ trong các lĩnh vực nào sau đây?',
    'Công nghiệp dân dụng và ứng dụng.', 'Chế tạo vũ khí hiện đại.', 'Công nghiệp nặng.', 'Công nghiệp vũ trụ và điện hạt nhân.',
    4, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là D: Công nghiệp vũ trụ và điện hạt nhân.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B10_41', '1fd255a5-c6ba-49fe-932a-3e3a7ccc8761', 'LS9_KNTT_B10', 'Năm năm đầu sau Chiến tranh thế giới thứ hai, nội dung nào sau đây là nhiệm vụ trọng tâm của Liên Xô?',
    'Khôi phục kinh tế, hàn gắn vết thương sau chiến tranh.', 'Xây dựng cơ sở vật chất kĩ thuật của chủ nghĩa xã hội.', 'Mở rộng quan hệ kinh tế đối ngoại với các nước lớn.', 'Tiêu diệt chủ nghĩa phát xít, bảo vệ hòa bình thế giới.',
    1, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là A: Khôi phục kinh tế, hàn gắn vết thương sau chiến tranh.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B11_01', 'b4f1f609-ebb6-44de-803f-7bf0ecd3bc77', 'LS9_KNTT_B11', 'Để thực hiện mục tiêu ngăn chặn đẩy lùi chủ nghĩa xã hội sau Chiến tranh thế giới thứ hai, Mỹ đã',
    'đưa ra khẩu hiệu “thúc đẩy dân chủ”.', 'can thiệp vào khu vực Trung Đông.', 'phát động cuộc Chiến tranh lạnh.', 'biến Mỹ Latinh thành sâu sau.',
    3, 20, 'WARM_UP', 'EASY', 'Đáp án đúng là C: phát động cuộc Chiến tranh lạnh.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B11_02', 'b4f1f609-ebb6-44de-803f-7bf0ecd3bc77', 'LS9_KNTT_B11', 'Theo quy định của Hiến pháp Mỹ, hai đảng nào thay nhau lên nắm chính quyền?',
    'Đảng Tự do và Đảng Bảo thủ.', 'Đảng Cộng sản và Đảng Xã hội.', 'Đảng Cộng hòa và Đảng Xã hội.', 'Đảng Dân chủ và Đảng Cộng hòa.',
    4, 20, 'WARM_UP', 'EASY', 'Đáp án đúng là D: Đảng Dân chủ và Đảng Cộng hòa.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B11_03', 'b4f1f609-ebb6-44de-803f-7bf0ecd3bc77', 'LS9_KNTT_B11', 'Từ những năm 1950 đến năm 1991, nền kinh tế Mỹ không còn chiếm ưu thế tuyệt đối vì',
    'sự vươn lên của các nước Tây Âu và Nhật Bản.', 'những cuộc đấu tranh của giai cấp công nhân.', 'đồng Đôla ngày càng có sự suy giảm về giá trị.', 'chính quyền không tổ chức cải cách, đổi mới.',
    1, 20, 'WARM_UP', 'EASY', 'Đáp án đúng là A: sự vươn lên của các nước Tây Âu và Nhật Bản.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B11_04', 'b4f1f609-ebb6-44de-803f-7bf0ecd3bc77', 'LS9_KNTT_B11', 'Sau Chiến tranh thế giới thứ hai, về chính trị, Mỹ đã',
    'cải tổ hệ thống chính trị.', 'dân chủ hóa hệ thống chính trị.', 'duy trì nền dân chủ tư sản.', 'ban hành một bản hiến pháp mới.',
    3, 20, 'WARM_UP', 'EASY', 'Đáp án đúng là C: duy trì nền dân chủ tư sản.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B11_05', 'b4f1f609-ebb6-44de-803f-7bf0ecd3bc77', 'LS9_KNTT_B11', 'Sau Chiến tranh thế giới thứ hai, quan hệ giữa Mỹ và Liên Xô là',
    'quan hệ hợp tác hữu nghị.', 'quan hệ đối đầu căng thẳng.', 'quan hệ Đồng minh.', 'quan hệ láng giềng thân thiện.',
    2, 20, 'WARM_UP', 'EASY', 'Đáp án đúng là B: quan hệ đối đầu căng thẳng.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B11_06', 'b4f1f609-ebb6-44de-803f-7bf0ecd3bc77', 'LS9_KNTT_B11', 'Chính quyền Mĩ sau Chiến tranh thế giới thứ hai không thực hiện chính sách đối nội nào sau đây?',
    'Ban hành đạo luật phục hưng công nghiệp.', 'Cấm Đảng Cộng sản Mĩ hoạt động.', 'Phân biệt chủng tộc với người da màu.', 'Đàn áp phong trào công nhân trong nước.',
    1, 20, 'WARM_UP', 'EASY', 'Đáp án đúng là A: Ban hành đạo luật phục hưng công nghiệp.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B11_09', 'b4f1f609-ebb6-44de-803f-7bf0ecd3bc77', 'LS9_KNTT_B11', 'Quốc gia nào ở khu vực Tây Âu luôn liên minh chặt chẽ với Mĩ sau Chiến tranh thế gới thứ hai?',
    'Anh.', 'Italia.', 'Pháp.', 'Đức.',
    1, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là A: Anh.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B11_10', 'b4f1f609-ebb6-44de-803f-7bf0ecd3bc77', 'LS9_KNTT_B11', 'Sau Chiến tranh thế giới thứ hai, để thực hiện chiến lược toàn cầu, Mỹ đã',
    'lôi kéo các nước nhận viện trợ.', 'đầu tư cho khoa học - công nghệ.', 'giải quyết các vấn đề lớn của thế giới.', 'viện trợ vô điều kiện cho các nước.',
    1, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là A: lôi kéo các nước nhận viện trợ.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B11_11', 'b4f1f609-ebb6-44de-803f-7bf0ecd3bc77', 'LS9_KNTT_B11', 'Năm 1991, Liên minh châu Âu ra đời trên cơ sở đổi tên từ tổ chức nào sau đây?',
    'Cộng đồng năng lượng nguyên tử châu Âu.', 'Cộng đồng than-thép châu Âu.', 'Cộng đồng kinh tế châu Âu.', 'Cộng đồng châu Âu.',
    4, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là D: Cộng đồng châu Âu.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B11_12', 'b4f1f609-ebb6-44de-803f-7bf0ecd3bc77', 'LS9_KNTT_B11', 'Sau Chiến tranh thế giới thứ hai, nhờ áp dụng cuộc Cách mạng xanh, nền kinh tế nào sau đây của Mỹ phát triển mạnh mẽ?',
    'Thương nghiệp.', 'Nông nghiệp.', 'Thủ công nghiệp.', 'Công nghiệp.',
    2, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là B: Nông nghiệp.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B11_14', 'b4f1f609-ebb6-44de-803f-7bf0ecd3bc77', 'LS9_KNTT_B11', 'Sau Chiến tranh thế giới thứ hai, để can thiệp vào tình hình ở Đông Nam Á, Mỹ đã',
    'thành lập khối SEATO.', 'đề ra chiến lược toàn cầu.', 'viện trợ kinh tế cho các bước.', 'chạy đua vũ trang với các nước.',
    1, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là A: thành lập khối SEATO.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B11_15', 'b4f1f609-ebb6-44de-803f-7bf0ecd3bc77', 'LS9_KNTT_B11', 'Sau Chiến tranh thế giới thứ hai, chính sách đối ngoại của Mĩ thể hiện tham vọng nào sau đây?',
    'Nhất thể hóa trên phạm vi toàn thế giới.', 'Khôi phục lại sự huy hoàng của chủ nghĩa tư bản.', 'Xác lập nền thống trị của chủ nghĩa tư bản.', 'Xác lập vai trò lãnh đạo của Mỹ trên thế giới.',
    4, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là D: Xác lập vai trò lãnh đạo của Mỹ trên thế giới.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B11_16', 'b4f1f609-ebb6-44de-803f-7bf0ecd3bc77', 'LS9_KNTT_B11', 'Nội dung nào sau đây phản ánh đúng vị thế kinh tế công nghiệp của Mỹ trong những năm 1945 - 1950?',
    'Chi phối các tổ chức kinh tế - tài chính thế giới.', 'Có sự suy giảm so với mức trước chiến tranh.', 'Có sản lượng công nghiệp đứng đầu thế giới.', 'Sản xuất đã phục hồi so với trước chiến tranh.',
    3, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là C: Có sản lượng công nghiệp đứng đầu thế giới.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B11_17', 'b4f1f609-ebb6-44de-803f-7bf0ecd3bc77', 'LS9_KNTT_B11', 'Theo Hiến pháp Mỹ, từ khi thành lập đến nay, nước Mỹ theo chế độ',
    'Quân chủ lập hiến.', 'Tổng thống độc tài.', 'Tổng thống Liên bang.', 'Liên bang quân phiệt.',
    3, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là C: Tổng thống Liên bang.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B11_18', 'b4f1f609-ebb6-44de-803f-7bf0ecd3bc77', 'LS9_KNTT_B11', 'Nhận xét sau đây phản ánh đúng về kinh tế Mỹ từ năm 1950 đến năm 1973?',
    'Tăng trưởng cao.', 'Suy giảm so với trước.', 'Phục hồi trước chiến tranh.', 'Tăng trưởng thấp.',
    1, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là A: Tăng trưởng cao.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B11_19', 'b4f1f609-ebb6-44de-803f-7bf0ecd3bc77', 'LS9_KNTT_B11', 'Nhân tố khách quan nào sau đây đã giúp kinh tế các nước Tây Âu hồi phục sau Chiến tranh thế giới thứ hai?',
    'Tiền bồi thường chiến phí từ các nước bại trận.', 'Viện trợ của Liên Xô qua tổ chức SEV.', 'Sự nỗ lực của toàn thể nhân dân trong nước.', 'Viện trợ của Mỹ theo kế hoạch Mácsan.',
    4, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là D: Viện trợ của Mỹ theo kế hoạch Mácsan.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B11_20', 'b4f1f609-ebb6-44de-803f-7bf0ecd3bc77', 'LS9_KNTT_B11', 'Sau Chiến tranh thế giới thứ hai, Mỹ đã thành lập khối quân sự ở khu vực nào sau đây?',
    'Đông Âu.', 'Đông Nam Á.', 'Đông Bắc Á.', 'Bắc Phi.',
    2, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là B: Đông Nam Á.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B11_21', 'b4f1f609-ebb6-44de-803f-7bf0ecd3bc77', 'LS9_KNTT_B11', 'Từ những năm 70 của thế kỷ XX, thông qua việc hạn chế chạy đua vũ trang, Mỹ đã',
    'cải thiện quan hệ với Liên Xô.', 'xóa bỏ vũ khí hủy diệt hàng loạt.', 'bảo vệ hòa bình, an ninh thế giới.', 'chấm dứt những xung đột với Liên Xô.',
    1, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là A: cải thiện quan hệ với Liên Xô.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B11_24', 'b4f1f609-ebb6-44de-803f-7bf0ecd3bc77', 'LS9_KNTT_B11', 'Sau Chiến tranh thế giới, quá trình liên kết khu vực Tây Âu diễn ra mạnh mẽ vì',
    'muốn vươn lên nắm quyền thống trị thế giới.', 'bị cạnh tranh quyết liệt bởi Mĩ và Nhật Bản.', 'phải tập hợp lực lượng, đối trọng với Đông Âu.', 'các nước muốn hợp tác để phát triển kinh tế.',
    4, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là D: các nước muốn hợp tác để phát triển kinh tế.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B11_25', 'b4f1f609-ebb6-44de-803f-7bf0ecd3bc77', 'LS9_KNTT_B11', 'Nội dung nào là đặc điểm của tình hình kinh tế Tây Âu trong những năm đầu sau Chiến tranh thế giới thứ hai?',
    'Bị chiến tranh làm thiệt hại hết sức nặng nề.', 'Vươn lên theo kịp sự phát triển của Mỹ.', 'Là trung tâm kinh tế tài chính lớn của thế giới.', 'Tốc độ tăng trường cao, vươn lên mạnh mẽ.',
    1, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là A: Bị chiến tranh làm thiệt hại hết sức nặng nề.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B11_26', 'b4f1f609-ebb6-44de-803f-7bf0ecd3bc77', 'LS9_KNTT_B11', 'Nhận xét nào sau đây phản ánh đúng về vị thế kinh tế của Mỹ từ năm 1945 đến năm 1991?',
    'Kinh tế Mỹ chiếm ưu thế tuyệt đối trong nền kinh tế thế giới.', 'Tỷ trọng kinh tế của Mỹ trong nền kinh tế thế giới giảm dần.', 'Mỹ luôn chiếm trên 50% tổng sản phẩm kinh tế thế giới.', 'Nền kinh tế Mỹ luôn có sự tăng trưởng cao nhất trên thế giới.',
    2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: Tỷ trọng kinh tế của Mỹ trong nền kinh tế thế giới giảm dần.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B11_27', 'b4f1f609-ebb6-44de-803f-7bf0ecd3bc77', 'LS9_KNTT_B11', 'Nhận xét nào sau đây phản ánh đúng về chính trị của nước Mỹ sau Chiến tranh thế giới hai?',
    'Thực hiện chế độ nhất nguyên, nhất đảng.', 'Xóa bỏ những giai cấp bóc lột trong xã hội.', 'Đảm bảo quyền lực thuộc về nhân dân.', 'Thực hiện chế độ đa nguyên đa đảng.',
    4, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là D: Thực hiện chế độ đa nguyên đa đảng.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B11_28', 'b4f1f609-ebb6-44de-803f-7bf0ecd3bc77', 'LS9_KNTT_B11', 'Nguyên nhân chung thúc đẩy kinh tế Mĩ và Tây Âu phát triển mạnh mẽ sau Chiến tranh thế giới thứ hai là',
    'coi giáo dục là nhân tố chìa khóa cho sự phát triển.', 'vai trò quản lí và điều tiết hợp lí, có hiệu quả của nhà nước.', 'lợi dụng chiến tranh thế giới thứ hai để làm giàu.', 'có lãnh thổ rộng lớn và tài nguyên thiên nhiên phong phú.',
    2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: vai trò quản lí và điều tiết hợp lí, có hiệu quả của nhà nước.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B11_29', 'b4f1f609-ebb6-44de-803f-7bf0ecd3bc77', 'LS9_KNTT_B11', 'Nhân tố khách quan nào tác động tới xu hướng liên kết kinh tế ở Tây Âu sau Chiến tranh thế giới thứ hai?',
    'Xu thế toàn cầu hóa.', 'Phong trào cách mạng thế giới.', 'Cuộc khủng hoảng kinh tế.', 'Cách mạng khoa học - kĩ thuật.',
    4, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là D: Cách mạng khoa học - kĩ thuật.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B11_30', 'b4f1f609-ebb6-44de-803f-7bf0ecd3bc77', 'LS9_KNTT_B11', 'Nhận xét sau đây phản ánh đúng về kinh tế Mỹ từ năm 1950 đến năm 1991?',
    'Tỷ trọng ngành công nghiệp trong nền kinh tế Mỹ bị suy giảm.', 'Tổng sản phẩm kinh tế của Mỹ trong nền kinh tế thế giới có xu hướng tăng.', 'Tỷ trọng GDP của Mỹ trong nền kinh tế thế giới có xu hướng giảm.', 'Dự trữ vàng của Mỹ ngày càng tăng, đồng Đôla có giá trị ngày càng tăng.',
    3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: Tỷ trọng GDP của Mỹ trong nền kinh tế thế giới có xu hướng giảm.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B11_31', 'b4f1f609-ebb6-44de-803f-7bf0ecd3bc77', 'LS9_KNTT_B11', 'Nội dung nào sau đây không phản ánh nguyên nhân thúc đẩy kinh tế Mỹ phát triển sau Chiến tranh thế giới thứ hai?',
    'Các tập đoàn tư bản lũng đoạn Mỹ có sức sản xuất, cạnh tranh lớn.', 'Tham gia sáng lập tổ chức Hiệp ước Bắc Đại Tây Dương (NATO).', 'Áp dụng những thành tựu khoa học - kĩ thuật vào sản xuất.', 'Vai trò của Nhà nước trong hoạch định chính sách và điều tiết kinh tế.',
    2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: Tham gia sáng lập tổ chức Hiệp ước Bắc Đại Tây Dương (NATO).'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B11_33', 'b4f1f609-ebb6-44de-803f-7bf0ecd3bc77', 'LS9_KNTT_B11', 'Đến những năm 50 của thế kỉ XX, các nước Tây Âu cơ bản khôi phục được kinh tế vì',
    'chi phí cho phát triển thuộc địa giảm, ngân sách quốc phòng giảm.', 'có sự giúp đỡ của Anh, sự liên kết kinh tế ở Tây Âu có hiệu quả cao.', 'tận dụng tốt những lợi thế giành được trong trật tự hai cực Ianta.', 'có sự cố gắng của từng nước, sự viện trợ của Mĩ qua “Kế hoạch Mácsan”.',
    4, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là D: có sự cố gắng của từng nước, sự viện trợ của Mĩ qua “Kế hoạch Mácsan”.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B12_01', '7db7679f-51db-4180-a7f4-35ee096ccb34', 'LS9_KNTT_B12', 'Trong quá trình xây dựng chủ nghĩa xã hội, đến năm 1957, Trung Quốc đã',
    'hoàn thành điện khí hóa trong cả nước.', 'thực hiện đường lối “Ba ngọn cờ hồng”.', 'tiến hành xong hiện đại hóa toàn diện đất nước', 'hoàn thành kế hoạch năm năm lần thứ nhất.',
    4, 20, 'WARM_UP', 'EASY', 'Đáp án đúng là D: hoàn thành kế hoạch năm năm lần thứ nhất.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B12_02', '7db7679f-51db-4180-a7f4-35ee096ccb34', 'LS9_KNTT_B12', 'Hiệp định Viêng Chăn (1973) được kí kết giữa Mỹ và Lào nhằm mục đích nào sau đây?',
    'Chấm dứt chiến tranh xâm lược của Mỹ.', 'Xây dựng đất nước theo xã hội chủ nghĩa.', 'Thành lập Cộng hòa Dân chủ Nhân dân Lào.', 'Lập lại hòa bình, hòa hợp dân tộc ở Lào.',
    4, 20, 'WARM_UP', 'EASY', 'Đáp án đúng là D: Lập lại hòa bình, hòa hợp dân tộc ở Lào.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B12_03', '7db7679f-51db-4180-a7f4-35ee096ccb34', 'LS9_KNTT_B12', 'Trong Chiến tranh thế giới thứ hai, các nước Đông Nam Á trở thành thuộc địa của',
    'phát xít I-ta-lia.', 'phát xít Đức.', 'phát xít Nhật.', 'đế quốc Mỹ.',
    3, 20, 'WARM_UP', 'EASY', 'Đáp án đúng là C: phát xít Nhật.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B12_04', '7db7679f-51db-4180-a7f4-35ee096ccb34', 'LS9_KNTT_B12', 'Nội dung nào là ý nghĩa quốc tế của sự ra đời nước Cộng hòa Cu-ba năm 1959?',
    'Buộc Mỹ phải công nhận độc lập và rút quân khỏi các nước Mỹ Latinh.', 'Mở đầu thời kì sụp đổ của chủ nghĩa thực dân trên toàn thế giới.', 'Tăng cường và mở rộng trận địa của chủ nghĩa xã hội trên thế giới.', 'Đánh bại hoàn toàn chủ nghĩa thực dân kiểu mới ở Mỹ Latinh.',
    3, 20, 'WARM_UP', 'EASY', 'Đáp án đúng là C: Tăng cường và mở rộng trận địa của chủ nghĩa xã hội trên thế giới.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B12_05', '7db7679f-51db-4180-a7f4-35ee096ccb34', 'LS9_KNTT_B12', 'Trong những năm 60 của thế kỉ XX, xu hướng nào trên thế giới tác động tới sự ra đời của tổ chức ASEAN?',
    'Hòa hoãn Đông - Tây.', 'Liên kết khu vực.', 'Toàn cầu hóa.', 'Đơn cực.',
    2, 20, 'WARM_UP', 'EASY', 'Đáp án đúng là B: Liên kết khu vực.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B12_06', '7db7679f-51db-4180-a7f4-35ee096ccb34', 'LS9_KNTT_B12', 'Cơ hội mới để Nhật Bản đạt được sự tăng trưởng thần kì trong những năm 60 của thế kỉ XX là',
    'chiến tranh của Mỹ ở Cu-ba.', 'cuộc nội chiến ở Trung Quốc.', 'chiến tranh của Mỹ ở Triều Tiên.', 'cuộc chiến của Mỹ ở Việt Nam.',
    4, 20, 'WARM_UP', 'EASY', 'Đáp án đúng là D: cuộc chiến của Mỹ ở Việt Nam.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B12_07', '7db7679f-51db-4180-a7f4-35ee096ccb34', 'LS9_KNTT_B12', 'Trong thời kì Chiến tranh lạnh, Nhật Bản chỉ dành 1% GDP cho những chi phí quân sự đã',
    'góp phần sản xuất vũ khí và phương tiện chiến tranh phù hợp.', 'xóa bỏ hoàn toàn lực lượng quân đội của chủ nghĩa phát xít', 'tạo điều kiện tập trung nguồn ngân sách phát triển kinh tế.', 'làm cho quân đội Nhật Bản được tổ chức đơn giản, quy củ hơn.',
    3, 20, 'WARM_UP', 'EASY', 'Đáp án đúng là C: tạo điều kiện tập trung nguồn ngân sách phát triển kinh tế.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B12_10', '7db7679f-51db-4180-a7f4-35ee096ccb34', 'LS9_KNTT_B12', 'Nguyên tắc hoạt động cơ bản của tổ chức ASEAN được xác định đầu tiên trong văn kiện nào sau đây?',
    'Tuyên bố Ba-li năm 1976.', 'Tuyên bố Băng-Cốc năm 1967.', 'Hiến chương ASEAN năm 2007.', 'Tầm nhìn ASEAN 2020.',
    1, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là A: Tuyên bố Ba-li năm 1976.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B12_11', '7db7679f-51db-4180-a7f4-35ee096ccb34', 'LS9_KNTT_B12', 'Với việc ký Hiệp ước an ninh Mỹ - Nhật, từ năm 1951, Mỹ đã',
    'kết nạp Nhật vào tổ chức Hiệp ước Bắc Đại Tây Dương.', 'sử dụng quân đội Nhật Bản trong chiến tranh Việt Nam.', 'xây dựng căn cứ quân sự trên lãnh thổ Nhật Bản.', 'rút quân đội viễn chinh đóng ở Nhật Bản về nước.',
    3, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là C: xây dựng căn cứ quân sự trên lãnh thổ Nhật Bản.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B12_12', '7db7679f-51db-4180-a7f4-35ee096ccb34', 'LS9_KNTT_B12', 'Sau Chiến tranh thế giới thứ 2, Nhật Bản coi khoa học - công nghệ là',
    'đòn bẩy để phát triển kinh tế - xã hội.', 'cơ sở cho Nhật Bản hội nhập quốc tế.', 'nhân tố thứ yếu cho sự phát triển kinh tế.', 'cơ sở cho sự công bằng của xã hội.',
    1, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là A: đòn bẩy để phát triển kinh tế - xã hội.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B12_13', '7db7679f-51db-4180-a7f4-35ee096ccb34', 'LS9_KNTT_B12', 'Nội dung nào phản ánh chính sách của chính quyền Mỹ trước sự ra đời của nước Cộng hòa Cuba năm 1959?',
    'Ủng hộ, giúp đỡ.', 'Bao vây, cấm vận.', 'Hợp tác cùng, phát triển.', 'Đẩy mạnh xâm lược.',
    2, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là B: Bao vây, cấm vận.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
