) VALUES (
    'Q_LS9_B12_14', '7db7679f-51db-4180-a7f4-35ee096ccb34', 'LS9_KNTT_B12', 'Nước nào giành thắng lợi trong cuộc đấu tranh chống chế độ độc tài thân Mỹ năm 1959?',
    'Bra-zin.', 'Cu-ba.', 'Hai-ti.', 'Vê-nê-xuê-la.',
    2, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là B: Cu-ba.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B12_15', '7db7679f-51db-4180-a7f4-35ee096ccb34', 'LS9_KNTT_B12', 'Từ năm 1950 đến năm 1952, Trung Quốc đã thực hiện thành công nhiệm vụ',
    'cải cách ruộng đất.', 'đổi mới toàn diện đất nước.', 'xây dựng chủ nghĩa xã hội.', 'giải phóng dân tộc.',
    1, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là A: cải cách ruộng đất.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B12_16', '7db7679f-51db-4180-a7f4-35ee096ccb34', 'LS9_KNTT_B12', 'Năm 1953, sự kiện nào mở đầu cuộc đấu tranh chống chế độ độc tài thân Mỹ tại Cu-ba?',
    'Phi-đen Ca-xtơ-rô vượt biển trở về Cu-ba.', 'Mỹ và tay sai dựng lên sự kiện Hi-rôn.', 'Cuộc tấn công trại lính Môn-ca-đa.', 'Phi-đen Ca-xtơ-rô vượt biển sang Mê-hi-cô.',
    3, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là C: Cuộc tấn công trại lính Môn-ca-đa.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B12_17', '7db7679f-51db-4180-a7f4-35ee096ccb34', 'LS9_KNTT_B12', 'Thực dân Anh thực hiện phương án Mao-bat-tơn nhằm mục đích cơ bản nào sau đây?',
    'Xoa dịu phong trào đấu tranh ở Ấn Độ.', 'Chỉ trao quyền tự trị cho Ấn Độ.', 'Công nhận quyền tự quyết của Ấn Độ.', 'Trao quyền độc lập cho Ấn Độ.',
    1, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là A: Xoa dịu phong trào đấu tranh ở Ấn Độ.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B12_18', '7db7679f-51db-4180-a7f4-35ee096ccb34', 'LS9_KNTT_B12', 'Cuộc đấu tranh giành độc lập của Việt Nam, Lào, Inđônêxia năm 1945 có ý nghĩa quốc tế như thế nào?',
    'Cổ vũ phong trào giải phóng dân tộc trên thế giới.', 'Làm chủ nghĩa xã hội trở thành hệ thống thế giới.', 'Làm xói mòn trật tự Ianta và Chiến tranh lạnh.', 'Góp phần giải trừ chủ nghĩa thực dân trên thế giới.',
    4, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là D: Góp phần giải trừ chủ nghĩa thực dân trên thế giới.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B12_19', '7db7679f-51db-4180-a7f4-35ee096ccb34', 'LS9_KNTT_B12', 'Tháng 9/1954, Mỹ cùng Anh, Pháp thành lập khối quân sự Đông Nam Á (SEATO) nhằm mục đích nào sau đây?',
    'Làm chậm quá trình liên kết khu vực ở Đông Nam Á.', 'Đặt Đông Nam Á dưới ô bảo trợ hạt nhân.', 'Đối trọng với liên minh quân sự của khu vực.', 'Ngăn chặn ảnh hưởng của chủ nghĩa xã hội.',
    4, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là D: Ngăn chặn ảnh hưởng của chủ nghĩa xã hội.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B12_20', '7db7679f-51db-4180-a7f4-35ee096ccb34', 'LS9_KNTT_B12', 'Trong quá trình xây dựng chủ nghĩa xã hội, Cuba đã',
    'xóa bỏ nền nông nghiệp đa canh.', 'chú trọng đến độc canh (cây mía).', 'xây dựng nền nông nghiệp đơn nhất.', 'xóa bỏ nền nông nghiệp độc canh.',
    4, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là D: xóa bỏ nền nông nghiệp độc canh.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B12_21', '7db7679f-51db-4180-a7f4-35ee096ccb34', 'LS9_KNTT_B12', 'Kinh tế hướng nội của 5 nước sáng lập ASEAN có mục tiêu nào sau đây?',
    'Thu hút vốn đầu tư xuất khẩu ra thị trường bên ngoài.', 'Phát triển công nghiệp tiêu dùng để hướng xuất khẩu.', 'Mở cửa kinh tế thu hút vốn đầu tư và kĩ thuật bên ngoài.', 'Xóa bỏ nghèo nàn, lạc hậu, xây dựng nền kinh tế tự chủ.',
    4, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là D: Xóa bỏ nghèo nàn, lạc hậu, xây dựng nền kinh tế tự chủ.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B12_22', '7db7679f-51db-4180-a7f4-35ee096ccb34', 'LS9_KNTT_B12', 'Nét nổi bật trong mối quan hệ của ba nước Đông Dương và ASEAN trong những năm 70-80 của thế kỷ XX là',
