    'Q_LS9_B13_69', '9167985d-f271-4d5c-8f73-1438194d5887', 'LS9_KNTT_B13', 'Sau Cách mạng tháng Tám năm 1945, kẻ thù nguy hiểm nhất mà nhân dân Việt Nam phải đối phó là',
    'Pháp.', 'Quân Trung Hoa Dân quốc.', 'Nhật.', 'Anh.',
    1, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là A: Pháp.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
