) VALUES (
    'Q_LS9_B13_70', '9167985d-f271-4d5c-8f73-1438194d5887', 'LS9_KNTT_B13', 'Cơ quan quyền lực cao nhất của nước Việt Nam Dân chủ Cộng hòa được thành lập năm 1946 là',
    'Tòa án.', 'Chính phủ.', 'Quốc hội.', 'Đảng Cộng sản.',
    3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: Quốc hội.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
