) VALUES (
    'Q_LS9_B13_71', '9167985d-f271-4d5c-8f73-1438194d5887', 'LS9_KNTT_B13', 'Sau thắng lợi của Cách mạng tháng Tám năm 1945, Chính phủ Việt Nam đã thành lập',
    'Ủy ban Khởi nghĩa.', 'các xưởng quân giới.', 'Nam kỳ tự trị.', 'Nhà máy dệt Nam Định.',
