) VALUES (
    'Q_LS9_B13_72', '9167985d-f271-4d5c-8f73-1438194d5887', 'LS9_KNTT_B13', 'Năm đầu sau Cách mạng tháng Tám năm 1945, Chính phủ Việt Nam đã kiện toàn',
    'Bộ Quốc phòng.', 'Bộ Canh tác.', 'Bộ Quân Nhu.', 'Bộ Quân y.',
