) VALUES (
    'Q_LS9_B15_63', 'ea6422ab-a860-4377-bab6-0a8df702711e', 'LS9_KNTT_B15', 'Chiến thắng lớn của quân dân Việt Nam ở Đông Khê gắn với chiến dịch nào trong kháng chiến chống Pháp?',
    'Chiến dịch Biên giới thu - đông 1950.', 'Chiến dịch Việt Bắc thu - đông 1947.', 'Chiến dịch Điện Biên Phủ năm 1954.', 'Chiến dịch Trung Lào năm 1953.',
    1, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là A: Chiến dịch Biên giới thu - đông 1950.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
