) VALUES (
    'Q_LS9_B15_65', 'ea6422ab-a860-4377-bab6-0a8df702711e', 'LS9_KNTT_B15', 'Tổng tư lệnh của quân đội quốc gia Việt Nam trong chiến dịch Điện Biên Phủ là',
    'Đại tướng Võ Nguyên Giáp.', 'Thủ tướng Phạm Văn Đồng.', 'Tổng Bí thư Trường Chinh.', 'Tổng Bí thư Lê Duẩn.',
    1, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là A: Đại tướng Võ Nguyên Giáp.'
);
INSERT INTO lesson_question (
