INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B15_69', 'ea6422ab-a860-4377-bab6-0a8df702711e', 'LS9_KNTT_B15', 'Nhận xét nào sau đây là đúng về mối quan hệ giữa hậu phương và tiền tuyến trong kháng chiến chống Pháp (1945 - 1954)?',
    'Hậu phương và tiền tuyến có mối quan hệ hữu cơ nhau.', 'Thắng lợi trên tiền tuyến sẽ thu hẹp phạm vi của hậu phương.', 'Tiền tuyến sẽ quyết định tới sự phát triển kinh tế của hậu phương.', 'Hậu phương tác động đến phương châm chiến đấu của tiền tuyến.',
    1, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là A: Hậu phương và tiền tuyến có mối quan hệ hữu cơ nhau.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B15_70', 'ea6422ab-a860-4377-bab6-0a8df702711e', 'LS9_KNTT_B15', 'Nhận định nào là đúng nhất về mối quan hệ giữa chiến thắng Điện Biên Phủ với Hiệp định Giơnevơ 1954 về Đông Dương?',
    'Thắng lợi ở Điện Biên Phủ buộc Pháp ký kết Hiệp định Giơnevơ.', 'Hiệp định Giơnevơ là điều kiện để giành thắng lợi ở Điện Biên Phủ.', 'Thắng lợi ở Điện Biên Phủ buộc các nước lớn mở hội nghị Giơnevơ.', 'Thắng lợi của Hiệp định Giơnevơ quyết định thắng lợi Điện Biên Phủ.',
    1, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là A: Thắng lợi ở Điện Biên Phủ buộc Pháp ký kết Hiệp định Giơnevơ.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B15_72', 'ea6422ab-a860-4377-bab6-0a8df702711e', 'LS9_KNTT_B15', 'Chủ tịch Hồ Chí Minh trực tiếp ra mặt trận chỉ đạo quân dân Việt Nam mở chiến dịch nào?',
    'Thượng Lào năm 1953.', 'Điện Biên Phủ năm 1954.', 'Biên giới thu - đông 1950.', 'Việt Bắc thu - đông 1947.',
    3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: Biên giới thu - đông 1950.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B15_74', 'ea6422ab-a860-4377-bab6-0a8df702711e', 'LS9_KNTT_B15', 'Nội dung nào sau đây phản ánh ý nghĩa quốc tế của chiến thắng Điện Biên Phủ năm 1954?',
    'Làm sụp đổ hệ thống thuộc địa của chủ nghĩa thực dân cũ và mới.', 'Cổ vũ phong trào giải phóng dân tộc trên thế giới, nhất là ở châu Phi.', 'Làm thất bại chiến lược toàn cầu của Mỹ sau Chiến tranh thế giới thứ hai.', 'Chấm dứt gần 100 năm xâm lược và thống trị của Pháp ở Đông Dương.',
    2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: Cổ vũ phong trào giải phóng dân tộc trên thế giới, nhất là ở châu Phi.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B15_75', 'ea6422ab-a860-4377-bab6-0a8df702711e', 'LS9_KNTT_B15', 'Với thắng lợi của cuộc kháng chiến chống Pháp (1945 - 1954), miền Bắc đã hoàn thành',
    'cách mạng ruộng đất.', 'cách mạng xã hội chủ nghĩa.', 'cách mạng dân chủ nhân dân.', 'cách mạng dân tộc dân chủ nhân dân.',
    3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: cách mạng dân chủ nhân dân.'
);
