    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B15_76', 'ea6422ab-a860-4377-bab6-0a8df702711e', 'LS9_KNTT_B15', 'Trận quyết chiến chiến lược trên mặt trận quân sự giữa Việt Nam với Pháp trong những năm 1945 - 1954 là',
    'chiến dịch Điện Biên Phủ năm 1954.', 'chiến dịch Việt Bắc thu - đông 1947.', 'chiến dịch Biên giới thu - đông 1950.', 'cuộc chiến đấu ở các đô thị (12/1946 - 2/1947).',
    1, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là A: chiến dịch Điện Biên Phủ năm 1954.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B15_77', 'ea6422ab-a860-4377-bab6-0a8df702711e', 'LS9_KNTT_B15', 'Nội dung nào không phải là nguyên nhân khách quan dẫn tới thắng lợi của cuộc kháng chiến chống Pháp (1945 - 1954)?',
    'Thắng lợi của phong trào giải phóng dân tộc ở châu Phi.', 'Sự đoàn kết liên minh chiến đấu của ba nước Đông Dương.', 'Sự ủng hộ của nhân dân Pháp và loài người tiến bộ trên thế giới.', 'Sự ủng hộ và giúp đỡ của các nước xã hội chủ nghĩa trên thế giới.',
    1, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là A: Thắng lợi của phong trào giải phóng dân tộc ở châu Phi.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B15_79', 'ea6422ab-a860-4377-bab6-0a8df702711e', 'LS9_KNTT_B15', 'Sau các cuộc tiến công trong Đông Xuân 1953 - 1954, quân dân Việt Nam đã giành được thế chủ động trên chiến trường nào?',
    'Chiến trường chính Bắc Bộ.', 'Chiến trường Bắc Đông Dương.', 'Chiến trường vùng rừng núi.', 'Chiến trường vùng Tây Bắc.',
    2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: Chiến trường Bắc Đông Dương.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B15_80', 'ea6422ab-a860-4377-bab6-0a8df702711e', 'LS9_KNTT_B15', 'Sau 8 năm tiến hành chiến trang xâm lược Việt Nam (1945 - 1953), Pháp không gặp phải khó khăn nào sau đây?',
    'Pháp lâm vào mâu thuẫn giữa tập trung và phân tán lực lượng.', 'Quâng Pháp lâm vào thế bị động trên chiến trường chính Bắc Bộ.', 'Vùng chiếm đóng của Pháp ở Đông Dương ngày càng bị thu hẹp.', 'Những giải pháp ngoại giao của Pháp đều không thu được kết quả.',
    4, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là D: Những giải pháp ngoại giao của Pháp đều không thu được kết quả.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B15_81', 'ea6422ab-a860-4377-bab6-0a8df702711e', 'LS9_KNTT_B15', 'Kế hoạch Na-va của Pháp khi mới ra đời năm 1953 đã hàm chứa yếu tố thất bại vì',
    'ra đời trong khó khăn bị động nhưng mục tiêu và tham vọng lớn.', 'ngân sách chiến tranh trống rỗng, quân đội Pháp không còn tinh thần.', 'bị mất quyền chủ động chiến lược trên toàn chiến trường Đông Dương.', 'phong trào phản đối chiến tranh xâm lược Việt Nam ở Pháp dâng cao.',
    1, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là A: ra đời trong khó khăn bị động nhưng mục tiêu và tham vọng lớn.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B15_83', 'ea6422ab-a860-4377-bab6-0a8df702711e', 'LS9_KNTT_B15', 'Chiến thắng nào của quân dân Việt Nam đã làm phá sản hoàn toàn kế hoạch Na-va?',
    'Chiến thắng Việt Bắc thu - đông 1947.', 'Chiến thắng Điện Biên Phủ năm 1954.', 'Chiến thắng Biên giới thu - đông 1950.', 'Chiến thắng Đông - Xuân 1953 - 1954.',
    2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: Chiến thắng Điện Biên Phủ năm 1954.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B15_85', 'ea6422ab-a860-4377-bab6-0a8df702711e', 'LS9_KNTT_B15', 'Cuộc đấu tranh trên bàn Hội nghị Giơ-ne-vơ Việt Nam thắng lợi chưa triệt để là do',
    'Liên Xô và các nước dân chủ chưa ủng hộ Việt Nam.', 'Mỹ can thiệp và dính líu vào cuộc chiến tranh của Pháp.', 'Việt Nam chưa có thắng lợi quyết chiến trên chiến trường.', 'Việt Nam chưa đánh bại hoàn toàn quân Pháp về quân sự.',
    4, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là D: Việt Nam chưa đánh bại hoàn toàn quân Pháp về quân sự.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B15_88', 'ea6422ab-a860-4377-bab6-0a8df702711e', 'LS9_KNTT_B15', '“Phải phá tan cuộc tấn công mùa đông của giặc Pháp” là chỉ thị của Đảng và Chính phủ Việt Nam trong chiến dịch nào?',
    'Chiến dịch Tây Bắc năm 1953.', 'Chiến dịch Việt Bắc thu - đông 1947.', 'Chiến dịch Điện Biên Phủ năm 1954.', 'Chiến dịch Biên giới thu - đông 1950.',
    2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: Chiến dịch Việt Bắc thu - đông 1947.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B15_91', 'ea6422ab-a860-4377-bab6-0a8df702711e', 'LS9_KNTT_B15', 'Cuộc kháng chiến chống thực dân Pháp xâm lược của nhân dân Đông Dương (1953 - 1954) kết thúc bằng giải pháp nào?',
