    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B16_14', 'e654f37b-fa2e-4b4c-ae15-f7d9cbb9e707', 'LS9_KNTT_B16', 'Sau khi được thành lập, Ủy ban Nhân dân tự quản ở Bến Tre đã thi hành chính sách tích cực nào sau đây?',
    'Phát triển kinh tế, cải tạo xã hội chủ nghĩa.', 'Mở những lớp dạy chữ Quốc ngữ, xóa bỏ giặc dốt.', 'Tiến hành tổng tuyển cử để xây dựng chính quyền.', 'Tịch thu ruộng đất của cường hào chia cho nông dân.',
    4, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là D: Tịch thu ruộng đất của cường hào chia cho nông dân.'
);
