) VALUES (
    'Q_LS9_B17_P_139', '0f3aa707-1d4f-43e2-9305-4d3f3bcb8037', 'LS9_KNTT_B17', 'Chiến dịch Tây Nguyên (3/1975) của quân dân Việt Nam được mở màn bằng cuộc tấn công vào',
    'Plây-ku.', 'Buôn Ma Thuột.', 'Kon Tum.', 'Đắc Lắc.',
    2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: Buôn Ma Thuột.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B17_P_143', '0f3aa707-1d4f-43e2-9305-4d3f3bcb8037', 'LS9_KNTT_B17', 'Trận đánh nào mang tính trinh sát chiến lược của quân dân miền Nam trong những năm 1974 - 1975?',
    'Chiến dịch Đường 14 - Phước Long.', 'Chiến dịch Tây Nguyên.', 'Chiến dịch Hồ Chí Minh.', 'Chiến dịch Huế - Đà Nẵng.',
    1, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là A: Chiến dịch Đường 14 - Phước Long.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B17_P_144', '0f3aa707-1d4f-43e2-9305-4d3f3bcb8037', 'LS9_KNTT_B17', 'Nội dung nào sau đây phản ánh điểm giống nhau giữa Chiến dịch Điên Biên Phủ (1954) và Chiến dịch Hồ Chí Minh (1975)?',
    'Cuộc tiến công chủ yếu của lực lượng vũ trang.', 'Đập tan hoàn toàn đầu não và sào huyệt cuối cùng của địch.', 'Cuộc tiến công của lực lượng vũ trang và nổi dậy của quần chúng.', 'Những thắng lợi có ý nghĩa quyết định kết thúc cuộc kháng chiến.',
    4, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là D: Những thắng lợi có ý nghĩa quyết định kết thúc cuộc kháng chiến.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B17_P_145', '0f3aa707-1d4f-43e2-9305-4d3f3bcb8037', 'LS9_KNTT_B17', 'Sự kiện nào báo hiệu sự toàn thắng của cuộc Tổng tiến công và nổi dậy Xuân 1975?',
    'Xe tăng và bộ binh của ta tiến vào dinh Độc Lập.', 'Lá cờ cách mạng tung bay trên nóc dinh Độc Lập.', 'Dương Văn Minh tuyên bố đầu hàng vô điều kiện.', 'Châu Đốc là tỉnh cuối cùng ở miền Nam được giải phóng.',
    4, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là D: Châu Đốc là tỉnh cuối cùng ở miền Nam được giải phóng.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B17_P_148', '0f3aa707-1d4f-43e2-9305-4d3f3bcb8037', 'LS9_KNTT_B17', 'Thắng lợi trong cuộc kháng chiến chống Mĩ, cứu nước (1954 - 1975) của nhân dân Việt Nam đã mở ra kỉ nguyên',
    'giải phóng dân tộc gắn liền với giải phóng xã hội.', 'giải phóng dân tộc gắn liền với giải phóng giai cấp.', 'đất nước độc lập, thống nhất, đi lên chủ nghĩa xã hội.', 'Nhân dân lao động nắm chính quyền, làm chủ đất nước.',
    3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: đất nước độc lập, thống nhất, đi lên chủ nghĩa xã hội.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B17_P_149', '0f3aa707-1d4f-43e2-9305-4d3f3bcb8037', 'LS9_KNTT_B17', 'Sự kiện nào đã mở ra quá trình “vừa đánh vừa đàm” của cách mạng Việt Nam trong kháng chiến chống Mĩ?',
    'Cuộc Tiến công chiến lược năm 1972.', 'Chiến thắng Điện Biên Phủ trên không năm 1972.', 'Cuộc Tổng tiến công và nổi dậy Xuân Mậu Thân 1968.', 'Chiến thắng trong hai mùa khô 1965 - 1966 và 1966 - 1967.',
    3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: Cuộc Tổng tiến công và nổi dậy Xuân Mậu Thân 1968.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B17_P_151', '0f3aa707-1d4f-43e2-9305-4d3f3bcb8037', 'LS9_KNTT_B17', 'Mĩ đẩy mạnh chiến tranh phá hoại miền Bắc lần thứ hai năm 1972 nhằm cứu vãn sự thất bại của chiến lược nào?',
    '“Chiến tranh đặc biệt”.', '“Chiến tranh cục bộ”.', '“Việt Nam hóa chiến tranh”.', '“Đông Dương hóa chiến tranh”.',
    3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: “Việt Nam hóa chiến tranh”.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B17_P_153', '0f3aa707-1d4f-43e2-9305-4d3f3bcb8037', 'LS9_KNTT_B17', 'Chiến dịch Hồ Chí Minh (1975) với Chiến dịch Điện Biên Phủ (1954) có điểm khác biệt cơ bản về',
    'sự huy động cao nhất lực lượng.', 'kết quả của chiến dịch.', 'phương châm tác chiến.', 'quyết tâm giành thắng lợi.',
    3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: phương châm tác chiến.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B17_P_156', '0f3aa707-1d4f-43e2-9305-4d3f3bcb8037', 'LS9_KNTT_B17', 'Từ năm 1954 đến năm 1975, những chiến lược chiến tranh Mĩ thực hiện ở miền Nam Việt Nam có điểm tương đồng về',
    'âm mưu chiến lược.', 'thủ đoạn của chiến tranh.', 'quy mô của chiến lược.', 'lực lượng tham chiến chính.',
    1, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là A: âm mưu chiến lược.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B17_P_159', '0f3aa707-1d4f-43e2-9305-4d3f3bcb8037', 'LS9_KNTT_B17', 'Quyết định để nhân dân miền Nam sử dụng bạo lực cách mạng đánh đổ chính quyền Mĩ - Diệm là nội dung quan trọng của',
    'Đại hội đại biểu của Đảng Lao động Việt Nam lần thứ III (9/1960).', 'Hội nghị lần thứ 21 Ban Chấp hành Trung ương Đảng (7/1973).', 'Hội nghị lần thứ 15 Ban Chấp hành Trung ương Đảng (1/1959).', 'Hội nghị lần thứ 24 Ban Chấp hành Trung ương Đảng (9/1975).',
    3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: Hội nghị lần thứ 15 Ban Chấp hành Trung ương Đảng (1/1959).'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B17_P_160', '0f3aa707-1d4f-43e2-9305-4d3f3bcb8037', 'LS9_KNTT_B17', 'Trong những năm 1965 - 1975, Mĩ phải chấm dứt tất cả các hành động chống phá miền Bắc Việt Nam sau sự kiện nào?',
    'Sau thắng lợi của chiến dịch Hồ Chí Minh.', 'Sau thắng lợi của trận “Điện Biên Phủ trên không”.', 'Sau khi Hiệp định Pa-ri về Việt Nam được kí kết.', 'Sau cuộc Tổng tiến công và nổi dậy Xuân 1975.',
    3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: Sau khi Hiệp định Pa-ri về Việt Nam được kí kết.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B17_P_164', '0f3aa707-1d4f-43e2-9305-4d3f3bcb8037', 'LS9_KNTT_B17', 'Nhân dân miền Bắc đạt được thành tự nào trong hơn 20 năm xây dựng CNXH (1954 - 1975)?',
    'Đưa Việt Nam trở thành nước nông nghiệp trong phe xã hội chủ nghĩa.', 'Bước đầu xây dựng được cơ sở vật chất - kĩ thuật của chủ nghĩa xã hội.', 'Đưa miền Bắc tiến nhanh, tiến mạnh, tiến vững chắc lên chủ nghĩa xã hội.', 'Đạt được thành tựu vượt bậc, trở thành một nước xã hội chủ nghĩa điển hình.',
    2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: Bước đầu xây dựng được cơ sở vật chất - kĩ thuật của chủ nghĩa xã hội.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B17_P_165', '0f3aa707-1d4f-43e2-9305-4d3f3bcb8037', 'LS9_KNTT_B17', 'Trong những năm 1974 - 1975, chiến dịch nào của quân dân Việt Nam thể hiện kế sách “điều địch để đánh địch”?',
    'Chiến dịch đường 14 - Phước Long.', 'Chiến dịch Tây Nguyên.', 'Chiến dịch Huế - Đà Nẵng.', 'Chiến dịch Sài Gòn - Gia Định.',
    2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: Chiến dịch Tây Nguyên.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B17_P_167', '0f3aa707-1d4f-43e2-9305-4d3f3bcb8037', 'LS9_KNTT_B17', 'Cuộc kháng chiến chống Mĩ của nhân dân Việt Nam (1954 - 1975) kết thúc thắng lợi hoàn toàn bằng giải pháp nào?',
    'Ngoại giao.', 'Quân sự.', 'Kinh tế.', 'Chính trị.',
    2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: Quân sự.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B17_P_169', '0f3aa707-1d4f-43e2-9305-4d3f3bcb8037', 'LS9_KNTT_B17', 'Phương thức “xã giải phóng xã, huyện giải phóng huyện, tỉnh giải phóng tỉnh” được nhân dân miền Nam sử dụng trong',
    'phong trào “Đồng khởi” ở Nam Bộ và Tây Nguyên.', 'chiến dịch Tây Nguyên và chiến dịch Huế - Đà Nẵng.', 'cuộc Tổng tiến công và nổi dậy Xuân Mậu Thân năm 1968.', 'giải phóng các tỉnh còn lại ở miền Nam sau khi giải phóng Sài Gòn.',
    2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: chiến dịch Tây Nguyên và chiến dịch Huế - Đà Nẵng.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B17_P_171', '0f3aa707-1d4f-43e2-9305-4d3f3bcb8037', 'LS9_KNTT_B17', 'Mĩ thực hiện chủ trương “phi Mĩ hóa” chiến tranh xâm lược Việt Nam trong chiến lược nào?',
    '“Chiến tranh đơn phương”.', '“Chiến tranh đặc biệt”.', '“Việt Nam hóa chiến tranh”.', '“Chiến tranh cục bộ”.',
    3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: “Việt Nam hóa chiến tranh”.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B17_P_172', '0f3aa707-1d4f-43e2-9305-4d3f3bcb8037', 'LS9_KNTT_B17', 'Năm 1965, Mĩ ồ ạt đưa quân viễn chinh, quân đồng minh vào chiến trường miền Nam Việt Nam vì',
    'muốn nhanh chóng kết thúc chiến tranh ở Việt Nam.', 'quân đội Sài Gòn không có khả năng tự đứng vững.', 'muốn tiến hành cuộc đảo chính lật đổ Ngô Đình Diệm.', 'muốn đẩy mạnh chiến tranh ra cả ba nước Đông Dương.',
    2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: quân đội Sài Gòn không có khả năng tự đứng vững.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B17_P_173', '0f3aa707-1d4f-43e2-9305-4d3f3bcb8037', 'LS9_KNTT_B17', 'Chiến dịch Điện Biên Phủ năm 1954 và Chiến dịch Hồ Chí Minh năm 1975 có điểm tương đồng nào sau đây?',
    'Sử dụng lối đánh du kích là chủ yếu.', 'Là trận quyết chiến chiến lược với kẻ thù.', 'Có sự điều chỉnh về phương châm tác chiến.', 'Có sự kết hợp chiến trường Lào và Campuchia.',
    2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: Là trận quyết chiến chiến lược với kẻ thù.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B17_P_174', '0f3aa707-1d4f-43e2-9305-4d3f3bcb8037', 'LS9_KNTT_B17', 'Mĩ tiến hành chiến tranh xâm lược Việt Nam (1954 - 1975) nhằm thực hiện mục tiêu nào trong chiến lược toàn cầu?',
    'Khống chế và nô dịch các nước đồng minh.', 'Can thiệp vào công việc nội bộ của các nước.', 'Ngăn chặn tiến tới tiêu diệt chủ nghĩa xã hội.', 'Đảo bảo an ninh Mĩ với lực lượng quân sự mạnh.',
    3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: Ngăn chặn tiến tới tiêu diệt chủ nghĩa xã hội.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B17_P_175', '0f3aa707-1d4f-43e2-9305-4d3f3bcb8037', 'LS9_KNTT_B17', 'Việc ký với Hoa Kỳ Hiệp định Pari năm 1973, Việt Nam',
    'chưa hoàn thành cách mạng dân tộc dân chủ nhân dân.', 'chỉ phải đối phó với một kẻ thù là chính quyền Sài Gòn.', 'đánh bại hoàn toàn các chiến lược chiến tranh của Mỹ.', 'hoàn thành kế hoạch thống nhất đất nước về lãnh thổ.',
    2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: chỉ phải đối phó với một kẻ thù là chính quyền Sài Gòn.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
