) VALUES (
    'Q_LS9_B17_P_176', '0f3aa707-1d4f-43e2-9305-4d3f3bcb8037', 'LS9_KNTT_B17', 'Chủ trương của Đảng trong Tổng tiến công và nổi dậy Xuân năm 1975 đã',
    'có sự điều chỉnh linh hoạt về thời gian giải phóng.', 'có sự thay đổi liên tục về phương châm tác chiến.', 'chuyển hướng tiến công từ đô thị về nông thôn.', 'chuyển hướng từ tổng tiến công sang nổi dậy.',
    1, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là A: có sự điều chỉnh linh hoạt về thời gian giải phóng.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
