    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B19_P_45', 'ed37275c-787b-4801-af9f-fb311c5960df', 'LS9_KNTT_B19', 'Những năm 90 của thế kỷ XX, tổ chức ASEAN kết nạp đủ thành viên trong khu vực, đẩy mạnh hợp tác đã',
    'hoàn tất quá trình nhất thể hóa về chính trị ở khu vực Đông Nam Á.', 'chấm dứt được tình trạng cạnh tranh giữa các quốc gia trong khu vực.', 'xác lập được một cực trong xu thế đa cực đang vận động hình thành.', 'mở ra một chương mới trong lịch sử phát triển khu vực Đông Nam Á.',
    4, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là D: mở ra một chương mới trong lịch sử phát triển khu vực Đông Nam Á.'
);
