    'Q_LS9_B19_P_52', 'ed37275c-787b-4801-af9f-fb311c5960df', 'LS9_KNTT_B19', 'Nhận xét nào sau đây phản ánh đúng về mối quan hệ giữa ba trụ cột trong Cộng đồng ASEAN?',
    'Ba trụ cột nối tiếp nhau ra đời, bổ sung cho nhau.', 'Các trụ cột tồn tại độc lập nhau, mang sắc thái riêng.', 'Mỗi trụ cột trong cộng đồng bổ sung, hỗ trợ cho nhau.', 'Cộng đồng Văn hoá - xã hội quyết định mọi sự phát triển.',
    3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: Mỗi trụ cột trong cộng đồng bổ sung, hỗ trợ cho nhau.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B19_P_53', 'ed37275c-787b-4801-af9f-fb311c5960df', 'LS9_KNTT_B19', 'Cộng đồng ASEAN ra đời năm 2015 có ý nghĩa cơ bản nào sau đây?',
    'Làm thất bại âm mưu của các thế lực trong và ngoài khu vực Đông Á.', 'Thúc đẩy hợp tác khu vực toàn diện theo chiều sâu và gắn bó chặt chẽ.', 'Chấm dứt hoàn toàn sự cạnh tranh và bất đồng giữa các nước thành viên.', 'Là một sự kiện mang tính đột biến trong quá trình hợp tác ở Đông Nam Á.',
    2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: Thúc đẩy hợp tác khu vực toàn diện theo chiều sâu và gắn bó chặt chẽ.'
);
