INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B19_P_55', 'ed37275c-787b-4801-af9f-fb311c5960df', 'LS9_KNTT_B19', 'Nhận xét nào sau đây phản ánh đúng về sự ra đời của Cộng đồng ASEAN?',
    'Diễn ra lâu dài vì sự chống phá quyết liệt của các cường quốc.', 'Có quá trình ra đời lâu dài với sự chuẩn bị đầy đủ về nhiều mặt.', 'Sớm được thành lập với sự đồng thuận của các nước thành viên.', 'Ra đời và tồn tại song song với Hiệp hội các quốc gia Đông Nam Á.',
    2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: Có quá trình ra đời lâu dài với sự chuẩn bị đầy đủ về nhiều mặt.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B19_P_56', 'ed37275c-787b-4801-af9f-fb311c5960df', 'LS9_KNTT_B19', 'Tuyên bố Bali (2003) và Hiến chương ASEAN (2007) đã',
    'xoá bỏ những bất đồng trong khu vực.', 'thúc đẩy các hoạt động liên kết khu vực.', 'mở rộng thêm lĩnh vực hợp tác của ASEAN.', 'hoàn thành quá trình nhất thể hoá khu vực.',
    2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: thúc đẩy các hoạt động liên kết khu vực.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B19_P_57', 'ed37275c-787b-4801-af9f-fb311c5960df', 'LS9_KNTT_B19', 'Hội nghị cấp cao ASEAN 14 ở Thái Lan (2009) đã thông qua',
    'Tầm nhìn Cộng đồng ASEAN sau năm 2025.', 'việc thành lập Cộng đồng Chính trị - An ninh ASEAN.', 'Lộ trình xây dựng Cộng đồng ASEAN (2009 - 2015).', 'mục tiêu hình thành Cộng đồng ASEAN vào năm 2015.',
    3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: Lộ trình xây dựng Cộng đồng ASEAN (2009 - 2015).'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B19_P_58', 'ed37275c-787b-4801-af9f-fb311c5960df', 'LS9_KNTT_B19', 'Quá trình phát triển từ “ASEAN 5” lên “ASEAN 10” diễn ra lâu dài vì',
    'nguyên tắc đồng thuận của 5 nước lớn sáng lập.', 'không có mục tiêu rõ ràng ngay từ khi thành lập.', 'nhiều nước vẫn trong tình trạng nghèo nàn, lạc hậu.', 'mức độ giành được độc lập ở mỗi nước khác nhau.',
    4, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là D: mức độ giành được độc lập ở mỗi nước khác nhau.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B19_P_59', 'ed37275c-787b-4801-af9f-fb311c5960df', 'LS9_KNTT_B19', 'Sau Chiến tranh lạnh, đặc biệt là khi vấn đề Campuchia được giải quyết, xu thế nổi bật của tổ chức ASEAN là',
    'đẩy mạnh liên kết theo hướng nhất thể hóa khu vực.', 'chuyển trọng tâm sang hợp tác về kinh tế đối ngoại.', 'mở rộng các thành viên ngoài khu vực Đông Nam Á.', 'chú trọng kết nạp các nước Đông Nam Á vào tổ chức.',
    4, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là D: chú trọng kết nạp các nước Đông Nam Á vào tổ chức.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B19_P_61', 'ed37275c-787b-4801-af9f-fb311c5960df', 'LS9_KNTT_B19', 'Các nhà lãnh đạo ASEAN ký Tuyên bố Cuala Lămpơ (2015) đã',
    'chính thức thành lập Cộng đồng ASEAN.', 'chấm dứt những mâu thuẫn trong nội khối.', 'đặt cơ sở cho sự chuẩn bị ra đời cộng đồng mới.', 'làm giảm tính phụ thuộc của các nước ASEAN.',
    1, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là A: chính thức thành lập Cộng đồng ASEAN.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
