INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B20_P_49', '46c6ef5d-b3c2-4409-9ade-07cb815e9c34', 'LS9_KNTT_B20', 'Một trong những hạn chế của công cuộc Đổi mới ở Việt Nam giai đoạn 1986 - 1991 là',
    'đời sống nhân dân ngày càng khó khăn, thiếu thốn.', 'xã hội lâm vào tình trạng bất ổn nghiêm trọng.', 'nhiều cơ sở kinh tế còn lạc hậu, sản xuất chưa hiệu quả.', 'tình trạng thiếu lương thực diễn ra ngày càng trầm trọng.',
    3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: nhiều cơ sở kinh tế còn lạc hậu, sản xuất chưa hiệu quả.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B20_P_50', '46c6ef5d-b3c2-4409-9ade-07cb815e9c34', 'LS9_KNTT_B20', 'Nội dung nào sau đây phản ánh đúng ý nghĩa của công cuộc Đổi mới đất nước giai đoạn 1986 - 1991?',
    'Đưa Việt Nam dần thoát khỏi tình trạng khủng hoảng.', 'Mỹ tuyên bố xoá bỏ lệnh cấm vận đối với Việt Nam.', 'Thu nhập bình quân đầu người của Việt Nam đạt tốp đầu của châu Á.', 'Đưa Việt Nam trở thành cường quốc công nghiệp trong khu vực.',
    1, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là A: Đưa Việt Nam dần thoát khỏi tình trạng khủng hoảng.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B20_P_51', '46c6ef5d-b3c2-4409-9ade-07cb815e9c34', 'LS9_KNTT_B20', 'Nội dung nào sau đây là điều kiện tiên quyết để Việt Nam tiến lên xây dựng chủ nghĩa xã hội?',
    'Đất nước phải giành được độc lập và thống nhất.', 'Hoàn thành công cuộc hàn gắn vết thương chiến tranh.', 'Đảng phải đề ra đường lối phát triển đúng đắn, sáng tạo.', 'Phải nhận được sự ủng hộ của các nước XHCN trên thế giới.',
    1, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là A: Đất nước phải giành được độc lập và thống nhất.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B20_P_52', '46c6ef5d-b3c2-4409-9ade-07cb815e9c34', 'LS9_KNTT_B20', 'Sau đại thắng Xuân 1975, đất nước Việt Nam được thống nhất về',
    'lãnh thổ.', 'Nhà nước.', 'quân sự.', 'chính quyền.',
    1, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là A: lãnh thổ.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B20_P_53', '46c6ef5d-b3c2-4409-9ade-07cb815e9c34', 'LS9_KNTT_B20', 'Sau đại thắng Xuân 1975, yếu tố nào tồn tại còn trái nguyện vọng, tình cảm thiêng liêng của nhân dân Việt Nam?',
    'Sự chống phá mạnh mẽ của các thế lực phản động trong và ngoài nước.', 'Ở mỗi miền đất nước vẫn tồn tại hình thức tổ chức nhà nước khác nhau.', 'Hoa Kì không trao trả tù binh bị bắt, không hàn gắn vết thương chiến tranh.', 'Nền kinh tế phát triển không cân đối, lệ thuộc vào viện trợ của nước ngoài.',
    2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: Ở mỗi miền đất nước vẫn tồn tại hình thức tổ chức nhà nước khác nhau.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B20_P_54', '46c6ef5d-b3c2-4409-9ade-07cb815e9c34', 'LS9_KNTT_B20', 'Sau đại thắng Xuân 1975, nhiệm vụ cấp thiết hàng đầu của cách mạng Việt Nam là',
    'xoá bỏ sự chia cắt về lãnh thổ.', 'hội nhập vào nền kinh tế toàn cầu.', 'thống nhất đất nước về mặt nhà nước.', 'khôi phục và phát triển kinh tế ở hai miền.',
    2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: hội nhập vào nền kinh tế toàn cầu.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B20_P_55', '46c6ef5d-b3c2-4409-9ade-07cb815e9c34', 'LS9_KNTT_B20', 'Nội dung nào sau đây phản ánh điều kiện thuận lợi của Việt Nam ngay sau đại thắng Xuân 1975?',
    'Đất nước đã thống nhất về mặt lãnh thổ.', 'Việt Nam được kết nạp vào Liên hợp quốc.', 'Các thế lực phản động trong nước bị xóa bỏ.', 'Những hậu quả của chiến tranh đã được khắc phục.',
    1, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là A: Đất nước đã thống nhất về mặt lãnh thổ.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B20_P_56', '46c6ef5d-b3c2-4409-9ade-07cb815e9c34', 'LS9_KNTT_B20', 'Nội dung nào sau đây đặc điểm nổi bật của kinh tế miền Nam Việt Nam sau giải phóng năm 1975?',
    'Kinh tế phát triển mạnh theo phương thức tư bản chủ nghĩa.', 'Kinh tế hàng hoá nhiều thành phần, vận hành theo cơ chế thị trường.', 'Kinh tế có sự phát triển mạnh mẽ, đứng đầu khu vực Đông Nam Á.', 'Phát triển mất cân đối, lệ thuộc nặng nề vào sự viện trợ từ bên ngoài.',
    4, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là D: Phát triển mất cân đối, lệ thuộc nặng nề vào sự viện trợ từ bên ngoài.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B20_P_59', '46c6ef5d-b3c2-4409-9ade-07cb815e9c34', 'LS9_KNTT_B20', 'Ngày 25/4/1976 đi vào lịch sử dân tộc Việt Nam với sự kiện chính trị trọng đại nào sau đây?',
    'Quốc hội khóa VI họp phiên đầu tiên ở Hà Nội.', 'Đại hội Đại biểu toàn quốc lần thứ IV của Đảng.', 'Hội nghị Hiệp thương chính trị thống nhất đất nước.', 'Cuộc tổng tuyển cử bầu Quốc hội chung trong cả nước.',
    4, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là D: Cuộc tổng tuyển cử bầu Quốc hội chung trong cả nước.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B20_P_60', '46c6ef5d-b3c2-4409-9ade-07cb815e9c34', 'LS9_KNTT_B20', 'Kì họp thứ nhất Quốc hội khóa VI nước Việt Nam thống nhất (24/6 đến 3/7/1976) đã có quyết định quan trọng nào sau đây?',
    'Đặt tên nước là Việt Nam Dân chủ Cộng hòa.', 'Xác lập những thành tích của Chính phủ lâm thời.', 'Thông qua bản Hiến pháp của nước Việt Nam mới.', 'Đặt tên nước là Cộng hòa xã hội chủ nghĩa Việt Nam.',
    4, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là D: Đặt tên nước là Cộng hòa xã hội chủ nghĩa Việt Nam.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B20_P_62', '46c6ef5d-b3c2-4409-9ade-07cb815e9c34', 'LS9_KNTT_B20', 'Việc hoàn thành thống nhất đất nước về mặt nhà nước ở Việt Nam sau năm 1975 không có ý nghĩa nào sau đây?',
    'Đánh dấu sự hoàn chỉnh về lý luận đi lên xây dựng chủ nghĩa xã hội.', 'Đáp ứng được nguyện vọng tha thiết của nhân dân hai miền Nam - Bắc.', 'Tạo điều kiện chính trị cơ bản phát huy sức mạnh toàn diện của đất nước.', 'Mở ra những khả năng to lớn để bảo vệ Tổ quốc và mở rộng quan hệ quốc tế.',
    1, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là A: Đánh dấu sự hoàn chỉnh về lý luận đi lên xây dựng chủ nghĩa xã hội.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B20_P_63', '46c6ef5d-b3c2-4409-9ade-07cb815e9c34', 'LS9_KNTT_B20', 'Ngày 20/7/1977 đánh dấu thắng lợi to lớn trong hoạt động đối ngoại khi Việt Nam',
    'được kết nạp vào Tổ chức Y tế thế giới.', 'tham gia Tổ chức Thương mại thế giới.', 'được kết nạp vào tổ chức Liên hợp quốc.', 'tham gia Hiệp hội các quốc gia Đông Nam Á.',
    3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: được kết nạp vào tổ chức Liên hợp quốc.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B20_P_64', '46c6ef5d-b3c2-4409-9ade-07cb815e9c34', 'LS9_KNTT_B20', 'Cuộc tổng tuyển bầu Quốc hội chung trong cả nước (25/4/1976) có ý nghĩa lịch sử nào sau đây?',
    'Thể hiện đường lối đổi mới đúng đắn, sáng tạo của Đảng.', 'Hoàn thành sự nghiệp thống nhất đất nước về mặt nhà nước.', 'Chứng tỏ chính trị ở Việt Nam không chị phản động chống phá.', 'Là bước tiến quan trọng cho sự thống nhất đất nước về mặt Nhà nước.',
    4, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là D: Là bước tiến quan trọng cho sự thống nhất đất nước về mặt Nhà nước.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B20_P_65', '46c6ef5d-b3c2-4409-9ade-07cb815e9c34', 'LS9_KNTT_B20', 'Đảng và Nhà nước Việt Nam tiến hành đổi mới đất nước từ năm 1986 trong bối cảnh nào sau đây?',
    'Những tác động của cuộc khủng hoảng năng lượng năm 1973.', 'Những tác động của cuộc cải cách ở Trung Quốc và Liên Xô.', 'Đất nước lâm vào khủng hoảng trầm trọng về kinh tế - xã hội.', 'Những tác động mạnh mẽ của cách mạng khoa học công nghệ.',
    3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: Đất nước lâm vào khủng hoảng trầm trọng về kinh tế - xã hội.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B20_P_67', '46c6ef5d-b3c2-4409-9ade-07cb815e9c34', 'LS9_KNTT_B20', 'Năm 1986, Đảng và Nhà nước Việt Nam tiến hành đổi mới toàn diện đất nước nhằm mục đích nào sau đây?',
    'Xoá bỏ lạm phát, khắc phục tình trạng nghèo nàn và lạc hậu.', 'Xây dựng cơ sở vật chất kỹ thuật hiện đại, có thu nhập ở mức cao.', 'Cứu vãn sự sụp đổ của mô hình chủ nghĩa xã hội trên toàn thế giới.', 'Khắc phục sai lầm, khuyết điểm, đưa đất nước thoát khỏi khủng hoảng.',
    4, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là D: Khắc phục sai lầm, khuyết điểm, đưa đất nước thoát khỏi khủng hoảng.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B20_P_68', '46c6ef5d-b3c2-4409-9ade-07cb815e9c34', 'LS9_KNTT_B20', 'Đường lối đổi mới được Đảng Cộng sản Việt Nam đề ra từ Đại hội VI (12/1986) xác định trọng tâm là đổi mới về',
    'chính trị.', 'văn hóa.', 'xã hội.', 'kinh tế.',
    4, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là D: kinh tế.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B20_P_69', '46c6ef5d-b3c2-4409-9ade-07cb815e9c34', 'LS9_KNTT_B20', 'Đường lối đổi mới về chính trị được Đảng Cộng sản Việt Nam đề ra từ Đại hội VI (12/1986) là',
    'xây dựng Nhà nước pháp quyền xã hội chủ nghĩa.', 'đẩy mạnh công nghiệp hoá, hiện đại hoá đất nước.', 'xây dựng nhà nước quân chủ của dân, do dân, vì dân.', 'bình thường hóa quan hệ ngoại giao với Mĩ và Liên Xô.',
    1, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là A: xây dựng Nhà nước pháp quyền xã hội chủ nghĩa.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B20_P_70', '46c6ef5d-b3c2-4409-9ade-07cb815e9c34', 'LS9_KNTT_B20', 'Trong đường lối đổi mới đất nước (từ tháng 12/1986), Đảng Cộng sản Việt Nam chủ trương hình thành cơ chế kinh tế',
    'bao cấp.', 'tập trung.', 'thị trường.', 'quan liêu.',
    3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: thị trường.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B20_P_72', '46c6ef5d-b3c2-4409-9ade-07cb815e9c34', 'LS9_KNTT_B20', 'Ba chương trình kinh tế lớn được Đại hội VI của Đảng Cộng sản Việt Nam (12/1986) xác định là',
    'lương thực - thực phẩm, hàng tiêu dùng, hàng dệt may.', 'hàng tiêu dùng, hàng xuất khẩu, hàng công nghiệp nặng.', 'lương thực - thực phẩm, hàng tiêu dùng, hàng nhập khẩu.', 'lương thực - thực phẩm, hàng tiêu dùng, hàng xuất khẩu.',
    4, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là D: lương thực - thực phẩm, hàng tiêu dùng, hàng xuất khẩu.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B20_P_74', '46c6ef5d-b3c2-4409-9ade-07cb815e9c34', 'LS9_KNTT_B20', 'Trong kế hoạch Nhà nước 5 năm (1986 - 1990), Việt Nam đạt được thành tựu nổi bật nào sau đây?',
    'Trở thành nước xuất khẩu lương thực hàng đầu thế giới.', 'Xuất khẩu nhiều mặt hàng công nghiệp có giá trị kinh tế lớn.', 'Xây dựng nền công nghiệp hiện đại gắn liền với kinh tế tri thức.', 'Đáp ứng nhu cầu lương thực trong nước, có dự trữ và xuất khẩu.',
    4, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là D: Đáp ứng nhu cầu lương thực trong nước, có dự trữ và xuất khẩu.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B20_P_75', '46c6ef5d-b3c2-4409-9ade-07cb815e9c34', 'LS9_KNTT_B20', 'Những thành tựu bước đầu của công cuộc đổi mới (1986 - 1990) ở Việt Nam đã chứng tỏ điều nội dung nào sau đây?',
    'Đường lối đổi mới của Đảng là đúng đắn, sáng tạo, phù hợp.', 'Sự viện trợ của cộng đồng quốc tế đã phát huy hiệu quả cao.', 'Việt Nam đã xây dựng xong cơ sở vật chất - kĩ thuật của CNXH.', 'Thời kì quá độ lên CNXH ở Việt Nam đã hoàn thành trước thời hạn.',
    1, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là A: Đường lối đổi mới của Đảng là đúng đắn, sáng tạo, phù hợp.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B20_P_76', '46c6ef5d-b3c2-4409-9ade-07cb815e9c34', 'LS9_KNTT_B20', 'Nội dung nào không phải là hạn chế của thời kì đầu tiên thực hiện đường lối đổi mới (1986 - 1990) ở Việt Nam?',
    'Nền kinh tế chưa vững chắc, hiệu quả và sức cạnh tranh thấp.', 'Việt Nam vẫn nằm trong nhóm nước có thu nhập trung bình.', 'Nền kinh tế phát triển vẫn mất cân đối, chỉ số lạm phát vẫn cao.', 'Tình trạng tham nhũng, suy thoái về tư tưởng của một số đảng viên.',
    2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: Việt Nam vẫn nằm trong nhóm nước có thu nhập trung bình.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B20_P_78', '46c6ef5d-b3c2-4409-9ade-07cb815e9c34', 'LS9_KNTT_B20', 'Hạn chế bước đầu trong thời kì thực hiện đường lối đổi mới (1986 - 1990) ở Việt Nam là',
    'cơ chế quản lý tập trung, quan liêu bao cấp vẫn tồn tại.', 'kinh tế vẫn lâm vào tình trạng khủng hoảng trầm trọng.', 'chế độ tiền lương cải cách chậm, trả lương bằng hiện vật.', 'phân hoá giàu nghèo giữa các vùng, các ngành ở mức cao.',
    4, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là D: phân hoá giàu nghèo giữa các vùng, các ngành ở mức cao.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B20_P_79', '46c6ef5d-b3c2-4409-9ade-07cb815e9c34', 'LS9_KNTT_B20', 'Nội dung nào sau đây phản ánh thành tựu trong lĩnh vực tài chính ở Việt Nam trong 5 năm đầu đổi mới (1986 - 1990)?',
    'Tình trạng nợ công đã được giải quyết.', 'Kiềm chế được một bước đà lạm phát.', 'Phát hành tiền Việt Nam mới bằng polime.', 'Nguồn thu tài chính đã đảm bảo cho phần chi.',
    2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: Kiềm chế được một bước đà lạm phát.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B20_P_80', '46c6ef5d-b3c2-4409-9ade-07cb815e9c34', 'LS9_KNTT_B20', 'Nội dung nào sau đây phản ánh thành tựu nổi bật trong quan hệ quốc tế của Việt Nam năm 1991?',
    'Nâng quan hệ đối ngoại với Trung Quốc lên cấp độ cao nhất.', 'Việt Nam đã bình thường hoá quan hệ đối ngoại với Trung Quốc.', 'Buộc Mỹ phải xoá bỏ lệnh cấm vận và thiết lập quan hệ song phương.', 'Là thành viên không thường trực của Hội đồng Bảo an Liên hợp quốc.',
    2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: Việt Nam đã bình thường hoá quan hệ đối ngoại với Trung Quốc.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B20_P_81', '46c6ef5d-b3c2-4409-9ade-07cb815e9c34', 'LS9_KNTT_B20', 'Nội dung nào sau đây phản ánh thành tựu của Việt Nam đạt được trong 5 năm đầu (1986 - 1990) của công cuộc đổi mới?',
    'Việt Nam đã hoàn thành công cuộc hiện đại hóa đất nước.', 'Việt Nam trở thành nước xuất khẩu gạo đứng đầu thế giới.', 'Đáp ứng được nhu cầu lương thực, thực phẩm trong nhân dân.', 'Sản xuất trong nước phát triển, thoát khỏi sự cấm vận của Mĩ.',
    3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: Đáp ứng được nhu cầu lương thực, thực phẩm trong nhân dân.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B20_P_84', '46c6ef5d-b3c2-4409-9ade-07cb815e9c34', 'LS9_KNTT_B20', 'Hội nghị Hiệp thương chính trị của đại biểu hai miền Nam - Bắc được tổ chức tại Sài Gòn (11/1975) đã',
    'quyết định tiến hành cuộc tổng tuyển cử bầu Quốc hội trong cả nước.', 'thống nhất hai mặt trận ở hai miền thành Mặt trận Tổ quốc Việt Nam.', 'thông qua chính sách đối nội, đối ngoại của nước Việt Nam thống nhất.', 'thông qua các chủ trương, biện pháp thống nhất đất nước về mặt nhà nước.',
    4, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là D: thông qua các chủ trương, biện pháp thống nhất đất nước về mặt nhà nước.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B20_P_85', '46c6ef5d-b3c2-4409-9ade-07cb815e9c34', 'LS9_KNTT_B20', 'Việc hoàn thành thống nhất đất nước về mặt nhà nước ở Việt Nam năm 1976 đã',
    'đánh dấu việc hoàn thành thống nhất các tổ chức chính trị - xã hội.', 'tạo khả năng to lớn để mở rộng quan hệ với các nước trên thế giới.', 'thể hiện mong muốn được gia nhập tổ chức ASEAN của Việt Nam.', 'tạo điều kiện tiếp tục hoàn thành cuộc cách mạng giải phóng dân tộc.',
    2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: tạo khả năng to lớn để mở rộng quan hệ với các nước trên thế giới.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B20_P_86', '46c6ef5d-b3c2-4409-9ade-07cb815e9c34', 'LS9_KNTT_B20', 'Ý nghĩa của việc hoàn thành thống nhất về mặt nhà nước sau đại thắng Xuân 1975 không phải là',
    'chấm dứt sự can thiệp, chống phá của Mỹ và các thế lực thù địch.', 'tạo điều kiện thuận lợi để cả nước đi lên xây dựng chủ nghĩa xã hội.', 'mở ra khả năng to lớn để bảo vệ Tổ quốc và mở rộng quan hệ quốc tế.', 'tạo điều kiện chính trị cơ bản để phát huy sức mạnh toàn diện của đất nước.',
    1, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là A: chấm dứt sự can thiệp, chống phá của Mỹ và các thế lực thù địch.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B20_P_88', '46c6ef5d-b3c2-4409-9ade-07cb815e9c34', 'LS9_KNTT_B20', 'Từ năm 1986, Đảng chủ trương, đổi mới không phải là thay đổi mục tiêu chủ nghĩa xã hội mà phải làm cho mục tiêu đó',
    'nhanh chóng trở thành hiện thực ở Việt Nam và thế giới.', 'phù hợp với những lí luận cách mạng tiên tiến trên thế giới.', 'phù hợp với thực tiễn Việt Nam và xu thế phát triển của thế giới.', 'được thực hiện hiệu quả với những bước đi và biện pháp thích hợp.',
    4, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là D: được thực hiện hiệu quả với những bước đi và biện pháp thích hợp.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B20_P_91', '46c6ef5d-b3c2-4409-9ade-07cb815e9c34', 'LS9_KNTT_B20', 'Kì họp đầu tiên của Quốc hội khóa VI năm 1976 và Quốc hội khóa I năm 1946 đều có quyết định tương đồng nào sau đây?',
    'Bầu Ban dự thảo Hiến pháp.', 'Xác nhận thành tích của Chính phủ lâm thời.', 'Thông qua bản Hiến pháp của nước Việt Nam mới.', 'Lấy tên nước là Cộng hòa xã hội chủ nghĩa Việt Nam.',
    1, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là A: Bầu Ban dự thảo Hiến pháp.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B20_P_92', '46c6ef5d-b3c2-4409-9ade-07cb815e9c34', 'LS9_KNTT_B20', 'Trong những năm chủ nghĩa xã hội ở Liên Xô và Đông Âu lâm vào khủng hoảng, Đảng và Nhà nước Việt Nam cho rằng',
    'Việt Nam chịu tác động lớn nên cần phải đổi mới đất nước.', 'mô hình chủ nghĩa xã hội chỉ phù hợp ở châu Á và Mĩ La-tinh.', 'Việt Nam không chịu tác động từ cuộc khủng hoảng ở Liên Xô.', 'Việt Nam cần tăng cường viện trợ cho Liên Xô và các nước Đông Âu.',
    1, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là A: Việt Nam chịu tác động lớn nên cần phải đổi mới đất nước.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B20_P_93', '46c6ef5d-b3c2-4409-9ade-07cb815e9c34', 'LS9_KNTT_B20', 'Địa bàn nào sau đây là mục tiêu tấn công quy mô lớn của lực lượng Pôn Pốt năm 1978?',
    'Gia Lai.', 'Tây Ninh.', 'Kon Tum.', 'Bình Phước.',
    2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: Tây Ninh.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B20_P_95', '46c6ef5d-b3c2-4409-9ade-07cb815e9c34', 'LS9_KNTT_B20', 'Năm 1979, cuộc chiến đấu chống quân Trung Quốc diễn ra quyết liệt ở địa phương nào sau đây?',
    'Phú Thọ.', 'Thái Nguyên.', 'Hà Giang.', 'Tuyên Quang.',
    3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: Hà Giang.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B20_P_96', '46c6ef5d-b3c2-4409-9ade-07cb815e9c34', 'LS9_KNTT_B20', 'Năm 1979, quân đội Trung Quốc tấn công tỉnh nào sau đây ở biên giới phía Bắc Việt Nam?',
    'Sơn La.', 'Cao Bằng.', 'Điện Biên.', 'Hoà Bình.',
    2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: Cao Bằng.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B20_P_97', '46c6ef5d-b3c2-4409-9ade-07cb815e9c34', 'LS9_KNTT_B20', 'Năm 1982, Chính phủ Việt Nam thành lập huyện đảo nào sau đây?',
    'Cát Hải.', 'Trường Sa.', 'Kiên Hải.', 'Bạch Long Vĩ.',
    2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: Trường Sa.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B20_P_98', '46c6ef5d-b3c2-4409-9ade-07cb815e9c34', 'LS9_KNTT_B20', 'Đảo nào của Việt Nam là mục tiêu tấn công của Trung Quốc vào tháng 3 năm 1988?',
    'Thị Tứ.', 'Nam Yết.', 'Gạc Ma.', 'Song Tử Tây.',
    3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: Gạc Ma.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B20_P_99', '46c6ef5d-b3c2-4409-9ade-07cb815e9c34', 'LS9_KNTT_B20', 'Xung đột căng thẳng kéo dài giữa Việt Nam và Trung Quốc sau năm 1979 diễn ra quyết liệt ở',
    'Phong Thổ Lai Châu).', 'Vị Xuyên (Hà Giang).', 'Móng Cái (Quảng Ninh).', 'Đình Lập (Lạng Sơn).',
    2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: Vị Xuyên (Hà Giang).'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B20_P_100', '46c6ef5d-b3c2-4409-9ade-07cb815e9c34', 'LS9_KNTT_B20', 'Năm 1979, Trung Quốc tấn công biên giới phía Bắc của Việt Nam với kế hoạch nào sau đây?',
    'Chính phục từng gói nhỏ.', 'Đánh nhanh thắng nhanh.', 'Lấy chiến tranh nuôi chiến tranh.', 'Dùng người Việt đánh người Việt.',
    2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: Đánh nhanh thắng nhanh.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B20_P_101', '46c6ef5d-b3c2-4409-9ade-07cb815e9c34', 'LS9_KNTT_B20', 'Để chuẩn bị tấn công Việt Nam năm 1979, Trung Quốc không có hành động nào sau đây?',
    'Ủng hộ Pôn Pốt chống Việt Nam.', 'Khiêu khích dọc biên giới phía Bắc.', 'Cắt viện trợ, rút chuyên gia về nước.', 'Phá huỷ các công trình dọc biên giới.',
    4, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là D: Phá huỷ các công trình dọc biên giới.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B20_P_102', '46c6ef5d-b3c2-4409-9ade-07cb815e9c34', 'LS9_KNTT_B20', 'Từ năm 1979 đến năm 1990, mối quan hệ Việt Nam và Trung Quốc có đặc điểm nổi bật nào sau đây?',
    'Chuyển từ đối thoại sang đối đầu.', 'Bình thường hoá quan hệ đối ngoại.', 'Tiếp tục có những căng thẳng kéo dài.', 'Thực thi chính sách hoà bình, trung lập.',
    3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: Tiếp tục có những căng thẳng kéo dài.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B20_P_103', '46c6ef5d-b3c2-4409-9ade-07cb815e9c34', 'LS9_KNTT_B20', 'Việt Nam đã triển khai hoạt động nào sau đây nhằm thực thi chủ quyền đối với quần đảo Hoàng Sa và quần đảo Trường Sa?',
    'Xây dựng các cảng biển.', 'Phát triển các ngư trường.', 'Thiết lập các ngọn đèn biển.', 'Lập nhiều cảng thương mại.',
    3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: Thiết lập các ngọn đèn biển.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B20_P_104', '46c6ef5d-b3c2-4409-9ade-07cb815e9c34', 'LS9_KNTT_B20', 'Năm 1978, lực lượng Pôn Pốt mở cuộc tấn công quy mô lớn vào Tây Ninh nhằm mục tiêu chủ yếu nào sau đây?',
    'Phá huỷ căn cứ quân sự lớn nhất nước ta.', 'Xây dựng căn cứ quân sự mới của chúng.', 'Mở đường tiến sâu vào lãnh thổ Việt Nam.', 'Đánh chiếm vựa lúa lớn nhất của Việt Nam',
    3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: Mở đường tiến sâu vào lãnh thổ Việt Nam.'
);
INSERT INTO lesson_question (
