    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B21_P_45', '9c7ec3ef-367f-4bde-bed5-a5cc310346a8', 'LS9_KNTT_B21', 'Sự phát triển nhanh chóng của cuộc cách mạng khoa học - kĩ thuật hiện đại dẫn đến hiện tượng nào sau đây?',
    'Chảy máu tài nguyên.', 'Sự bùng nổ thông tin.', 'Bùng nổ dân số.', 'Chảy máu chất xám.',
    2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: Sự bùng nổ thông tin.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B21_P_47', '9c7ec3ef-367f-4bde-bed5-a5cc310346a8', 'LS9_KNTT_B21', 'Tác động lớn của cách mạng khoa học - công nghệ đối với nền kinh tế thế giới là',
    'hình thành một thị trường thế giới với xu thế toàn cầu hoá.', 'tạo ra nhiều việc làm cho kinh tế các nước đang phát triển.', 'tạo ra sự cạnh tranh đối với những nước kinh tế kém phát triển.', 'làm cho nền kinh tế phát triển theo chiều sâu, nhất là trong nông nghiệp.',
    1, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là A: hình thành một thị trường thế giới với xu thế toàn cầu hoá.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
    option_1, option_2, option_3, option_4, 
    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B21_P_48', '9c7ec3ef-367f-4bde-bed5-a5cc310346a8', 'LS9_KNTT_B21', 'Sự ra đời của các tổ chức liên kết kinh tế, thương mại, tài chính quốc tế và khu vực có vai trò',
    'góp phần hình thành một nền tài chính chung toàn thế giới.', 'duy trì và bảo vệ quyền lợi cho các quốc gia kém phát triển.', 'giải quyết những vấn đề kinh tế chung của thế giới và khu vực.', 'ngăn chặn những cuộc khủng hoảng kinh tế - tài chính thế giới.',
    3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: giải quyết những vấn đề kinh tế chung của thế giới và khu vực.'
);
INSERT INTO lesson_question (
