    correct_answer, time_limit, stage_tag, difficulty, explanation
) VALUES (
    'Q_LS9_B21_P_52', '9c7ec3ef-367f-4bde-bed5-a5cc310346a8', 'LS9_KNTT_B21', 'Thành tựu khiến thế giới xích lại gần nhau hơn mà cuộc cách mạng khoa học - kỹ thuật hiện đại mang lại là',
    'kết nối hệ thống máy tính toàn cầu, Internet.', 'thành tựu trong lĩnh vực nông nghiệp xanh.', 'thành tựu trong lĩnh vực công nghệ sinh học.', 'tìm ra những hành tinh mới ngoài Trái Đất.',
    1, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là A: kết nối hệ thống máy tính toàn cầu, Internet.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
