) VALUES (
    'Q_LS9_B21_P_53', '9c7ec3ef-367f-4bde-bed5-a5cc310346a8', 'LS9_KNTT_B21', 'Tiền đề thúc đẩy sự bùng nổ của cuộc cách mạng khoa học - công nghệ ở nửa sau thế kỷ XX là',
    'sự vươn lên mạnh mẽ của nền kinh tế Mỹ, Tây Âu, Nhật Bản.', 'những thắng lợi của phong trào giải phóng dân tộc trên thế giới.', 'những hậu quả nặng nề của cuộc Chiến tranh thế giới lần hai.', 'những thành tựu về khoa học - kỹ thuật cuối thế kỷ XIX đầu thế kỷ XX.',
    4, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là D: những thành tựu về khoa học - kỹ thuật cuối thế kỷ XIX đầu thế kỷ XX.'
);
INSERT INTO lesson_question (
    id, lesson_id, lesson_code, question_text, 
